#[cfg(test)]
mod priority_reducer_census_tests {
    use super::PriorityReducerFamily;
    use std::collections::BTreeSet;

    /// R14–R18: Freeze the independently discovered Priority-reducer surface
    /// before the private announcement facade is introduced. This scans the
    /// normal reducer source rather than deriving the result from a future
    /// facade inventory, so a new direct Priority arm cannot hide behind the
    /// inventory it is required to update.
    #[test]
    fn priority_reducer_has_the_frozen_action_family_census() {
        let source = include_str!("engine.rs");
        let start = source
            .find("(WaitingFor::Priority { player }, GameAction::PassPriority)")
            .expect("Priority reducer starts at PassPriority");
        let end_marker = "(WaitingFor::Priority { player }, GameAction::SetAutoPass { mode })";
        let end = source[start..]
            .find(end_marker)
            .map(|offset| start + offset + end_marker.len())
            .expect("Priority reducer ends at SetAutoPass");

        let mut families = BTreeSet::new();
        let mut lines_after_priority_pattern = 0usize;
        for line in source[start..end].lines() {
            if line.contains("WaitingFor::Priority { player }") {
                lines_after_priority_pattern = 6;
            }
            if lines_after_priority_pattern > 0 {
                if let Some(action) = line.split("GameAction::").nth(1) {
                    let name = action
                        .chars()
                        .take_while(|character| {
                            character.is_ascii_alphabetic() || *character == '_'
                        })
                        .collect::<String>();
                    if !name.is_empty() {
                        families.insert(name);
                    }
                }
                lines_after_priority_pattern -= 1;
            }
        }

        let expected = [
            "ActivateAbility",
            "ActivateManaSource",
            "ActivateNinjutsu",
            "ActivateStation",
            "BeginResolveAll",
            "CastPreparedCopy",
            "CastSpell",
            "CastSpellAsSneak",
            "CastSpellAsWebSlinging",
            "CastSpellForFree",
            "CompanionToHand",
            "CrewVehicle",
            "EndContinuousEffect",
            "Equip",
            "Foretell",
            "PassPriority",
            "PlayFaceDown",
            "PlayLand",
            "RollPlanarDie",
            "SaddleMount",
            "SetAutoPass",
            "TapLandForMana",
            "Transform",
            "TurnFaceUp",
            "UnlockRoomDoor",
            "UntapLandForMana",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect::<BTreeSet<_>>();

        assert_eq!(families, expected);
        let preflight_families = PriorityReducerFamily::ALL
            .into_iter()
            .map(|family| format!("{family:?}"))
            .collect::<BTreeSet<_>>();
        let expected_preflight_families = expected
            .iter()
            .filter(|family| {
                !matches!(
                    family.as_str(),
                    "BeginResolveAll" | "PassPriority" | "SetAutoPass"
                )
            })
            .map(|family| (*family).to_owned())
            .collect::<BTreeSet<_>>();
        assert_eq!(preflight_families, expected_preflight_families);
    }
}

#[cfg(test)]
mod priority_facade_boundary_tests {
    /// R18: Provider announcements remain opaque until the one engine-owned
    /// facade. This source guard is intentionally scoped to the frozen provider
    /// set: ordinary `GameAction` producers are not part of this boundary.
    #[test]
    fn facade_access_is_constructed_once_and_provider_accessors_only_borrow_it() {
        let engine_source = include_str!("engine.rs");
        let facade_constructor = ["PriorityAnnouncementFacadeAccess::", "new()"].concat();
        assert_eq!(
            engine_source.matches(&facade_constructor).count(),
            1,
            "the facade capability must have one constructor call"
        );

        let announcement_start = engine_source
            .find("enum PriorityAnnouncement {")
            .map(|offset| offset + "enum PriorityAnnouncement {".len())
            .expect("private announcement sum exists");
        let announcement_end = engine_source[announcement_start..]
            .find("\n}\n\nimpl PriorityAnnouncement")
            .map(|offset| announcement_start + offset)
            .expect("private announcement sum closes before its family match");
        assert!(
            !engine_source[announcement_start..announcement_end].contains('{'),
            "Priority announcements must carry provider-owned opaque values, not raw fields"
        );

        for provider_source in [
            include_str!("casting.rs"),
            include_str!("mana_sources.rs"),
            include_str!("morph.rs"),
            include_str!("transform.rs"),
            include_str!("keywords.rs"),
            include_str!("room.rs"),
            include_str!("companion.rs"),
            include_str!("planechase.rs"),
            include_str!("end_continuous_effect.rs"),
            include_str!("crew_payment.rs"),
            include_str!("effects/prepare.rs"),
            include_str!("effects/attach.rs"),
        ] {
            assert!(
                !provider_source.contains("PriorityAnnouncementFacadeAccess::"),
                "providers may not construct or invoke the facade capability"
            );
            for line in provider_source
                .lines()
                .filter(|line| line.contains("PriorityAnnouncementFacadeAccess"))
            {
                assert!(
                    line.contains("use ") || line.contains("_access: &"),
                    "provider capability mentions must be imports or borrowed read-only accessors: {line}"
                );
            }
        }
    }
}

#[cfg(test)]
mod priority_principal_tests {
    use super::{
        apply_actionless_priority_pass_for_prospective, preflight_priority_window,
        priority_announcement_to_action, priority_preflight_candidates,
        priority_principal_for_preflight, PriorityPreflight, PriorityPreflightBlock,
        PriorityPreflightCandidate, PriorityPreflightIndeterminate, PriorityReducerFamily,
    };
    use crate::game::game_object::BackFaceData;
    use crate::game::scenario::{GameScenario, P0};
    use crate::game::zones;
    use crate::types::ability::{
        AbilityDefinition, AbilityKind, Effect, QuantityExpr, TargetFilter,
    };
    use crate::types::card_type::{CardType, CoreType};
    use crate::types::game_state::{GameState, WaitingFor};
    use crate::types::identifiers::{CardId, ObjectId};
    use crate::types::mana::{ManaColor, ManaCost, ManaCostShard, ManaType, ManaUnit};
    use crate::types::phase::Phase;
    use crate::types::player::PlayerId;
    use crate::types::zones::Zone;

    fn issue_4001_alternative_face_fixture(mana_count: usize) -> (GameState, ObjectId) {
        let mut scenario = GameScenario::new();
        scenario.at_phase(Phase::DeclareAttackers);
        let object_id = scenario
            .add_creature_to_hand(P0, "Frolicking Familiar", 2, 2)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Red],
                generic: 2,
            })
            .id();
        let mut runner = scenario.build();
        runner
            .state_mut()
            .objects
            .get_mut(&object_id)
            .unwrap()
            .back_face = Some(BackFaceData {
            is_swap_snapshot: false,
            trigger_printed_origins: Vec::new(),
            name: "Blow Off Steam".to_string(),
            power: None,
            toughness: None,
            loyalty: None,
            printed_loyalty: None,
            defense: None,
            card_types: {
                let mut card_types = CardType::default();
                card_types.core_types.push(CoreType::Instant);
                card_types.subtypes.push("Adventure".to_string());
                card_types
            },
            mana_cost: ManaCost::Cost {
                shards: vec![ManaCostShard::Red],
                generic: 1,
            },
            keywords: Vec::new(),
            abilities: vec![AbilityDefinition::new(
                AbilityKind::Spell,
                Effect::DealDamage {
                    amount: QuantityExpr::Fixed { value: 2 },
                    target: TargetFilter::Any,
                    damage_source: None,
                    excess: None,
                },
            )],
            trigger_definitions: Default::default(),
            replacement_definitions: Default::default(),
            static_definitions: Default::default(),
            color: vec![ManaColor::Red],
            printed_ref: None,
            modal: None,
            additional_cost: None,
            strive_cost: None,
            casting_restrictions: Vec::new(),
            casting_options: Vec::new(),
            layout_kind: None,
            parse_warnings: vec![],
        });
        for _ in 0..mana_count {
            runner.state_mut().players[0].mana_pool.add(ManaUnit::new(
                ManaType::Red,
                ObjectId(0),
                false,
                Vec::new(),
            ));
        }
        (runner.state().clone(), object_id)
    }

    #[test]
    fn principal_preserves_the_controlled_priority_seat() {
        let controlled_seat = PlayerId(0);
        let controller = PlayerId(1);
        let mut state = GameState::new_two_player(42);
        state.active_player = controlled_seat;
        state.waiting_for = WaitingFor::Priority {
            player: controlled_seat,
        };
        state.turn_decision_controller = Some(controller);
        state.priority_player = controller;

        let principal = priority_principal_for_preflight(&state)
            .expect("a synchronized controlled Priority window has a principal");

        assert_eq!(principal.semantic_holder(), controlled_seat);
        assert_eq!(principal.authenticated_actor(), controller);
        assert_eq!(principal.land_resource_owner(), controlled_seat);
    }

    #[test]
    fn principal_rejects_stale_priority_authority_without_mutating_the_wait() {
        let controlled_seat = PlayerId(0);
        let controller = PlayerId(1);
        let mut state = GameState::new_two_player(42);
        state.active_player = controlled_seat;
        state.waiting_for = WaitingFor::Priority {
            player: controlled_seat,
        };
        state.turn_decision_controller = Some(controller);
        state.priority_player = controlled_seat;
        let waiting_before = state.waiting_for.clone();

        assert!(matches!(
            priority_principal_for_preflight(&state),
            Err(PriorityPreflightIndeterminate::PriorityAuthorityMismatch)
        ));
        assert_eq!(state.waiting_for, waiting_before);
    }

    #[test]
    fn principal_rejects_non_priority_without_mutating_the_wait() {
        let mut state = GameState::new_two_player(42);
        state.waiting_for = WaitingFor::GameOver { winner: None };
        let waiting_before = state.waiting_for.clone();

        assert!(matches!(
            priority_principal_for_preflight(&state),
            Err(PriorityPreflightIndeterminate::NotPriority)
        ));
        assert_eq!(state.waiting_for, waiting_before);
    }

    #[test]
    fn priority_preflight_reports_an_actionless_empty_window() {
        let player = PlayerId(0);
        let mut state = GameState::new_two_player(42);
        state.active_player = player;
        state.priority_player = player;
        state.waiting_for = WaitingFor::Priority { player };

        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionless
        );
    }

    #[test]
    fn priority_preflight_keeps_cast_legal_only_through_alternative_face() {
        let (state, object_id) = issue_4001_alternative_face_fixture(2);
        let before = state.clone();

        assert!(
            crate::game::casting::effective_spell_cost(&state, P0, object_id).is_none(),
            "the creature front face must remain unpreparable outside a main phase"
        );
        assert!(
            crate::game::casting::can_cast_object_now(&state, P0, object_id),
            "the instant Adventure face must make the object castable"
        );
        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionable {
                family: PriorityReducerFamily::CastSpell,
            }
        );
        assert_eq!(state, before);
    }

    #[test]
    fn priority_preflight_stays_actionless_when_neither_face_is_castable() {
        let (state, object_id) = issue_4001_alternative_face_fixture(0);
        let before = state.clone();

        assert!(
            !crate::game::casting::can_cast_object_now(&state, P0, object_id),
            "neither the front face nor the Adventure face is currently castable"
        );
        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionless
        );
        assert_eq!(state, before);
    }

    #[test]
    fn priority_preflight_reports_stale_authority_without_inventing_a_family() {
        let controlled_seat = PlayerId(0);
        let controller = PlayerId(1);
        let mut state = GameState::new_two_player(42);
        state.active_player = controlled_seat;
        state.waiting_for = WaitingFor::Priority {
            player: controlled_seat,
        };
        state.turn_decision_controller = Some(controller);
        state.priority_player = controlled_seat;
        let before = state.clone();

        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Indeterminate {
                family: None,
                block: PriorityPreflightBlock::Principal(
                    PriorityPreflightIndeterminate::PriorityAuthorityMismatch,
                ),
            }
        );
        assert_eq!(state, before);
    }

    #[test]
    fn priority_preflight_clones_a_land_announcement_without_mutating_live_state() {
        let player = PlayerId(0);
        let mut state = GameState::new_two_player(42);
        state.active_player = player;
        state.priority_player = player;
        state.phase = crate::types::phase::Phase::PreCombatMain;
        state.waiting_for = WaitingFor::Priority { player };
        let land = zones::create_object(
            &mut state,
            CardId(1),
            player,
            "Island".to_string(),
            Zone::Hand,
        );
        state
            .objects
            .get_mut(&land)
            .expect("new hand object exists")
            .card_types
            .core_types
            .push(CoreType::Land);
        state.players[player.0 as usize].hand.push_back(land);
        let before = state.clone();

        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionable {
                family: PriorityReducerFamily::PlayLand
            }
        );
        assert_eq!(state, before);
    }

    #[test]
    fn priority_preflight_routes_basic_land_mana_through_the_mana_provider() {
        let player = PlayerId(0);
        let mut state = GameState::new_two_player(42);
        state.active_player = player;
        state.priority_player = player;
        state.waiting_for = WaitingFor::Priority { player };
        let forest = zones::create_object(
            &mut state,
            CardId(1),
            player,
            "Forest".to_string(),
            Zone::Battlefield,
        );
        let forest = state
            .objects
            .get_mut(&forest)
            .expect("new battlefield Forest exists");
        forest.card_types.core_types.push(CoreType::Land);
        forest.card_types.subtypes.push("Forest".to_string());
        let before = state.clone();

        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionable {
                family: PriorityReducerFamily::TapLandForMana,
            }
        );
        assert_eq!(state, before);
    }

    #[test]
    fn priority_play_face_down_candidate_is_reachable_but_not_an_exact_legal_action_candidate() {
        use crate::types::actions::GameAction;
        use crate::types::keywords::Keyword;
        use crate::types::mana::{ManaCost, ManaType, ManaUnit};

        let player = PlayerId(0);
        let mut state = GameState::new_two_player(42);
        state.active_player = player;
        state.priority_player = player;
        state.phase = crate::types::phase::Phase::PreCombatMain;
        state.waiting_for = WaitingFor::Priority { player };
        let morph = zones::create_object(
            &mut state,
            CardId(7_301),
            player,
            "Preflight Morph".to_string(),
            Zone::Hand,
        );
        {
            let object = state.objects.get_mut(&morph).unwrap();
            object.card_types.core_types.push(CoreType::Creature);
            object.base_card_types = object.card_types.clone();
            object.mana_cost = ManaCost::generic(8);
            object.base_mana_cost = object.mana_cost.clone();
            object.keywords = vec![Keyword::morph(ManaCost::generic(5))];
            object.base_keywords = object.keywords.clone();
        }
        let sibling_spell = zones::create_object(
            &mut state,
            CardId(7_303),
            player,
            "Preflight Sibling Spell".to_string(),
            Zone::Hand,
        );
        {
            let object = state.objects.get_mut(&sibling_spell).unwrap();
            object.card_types.core_types.push(CoreType::Creature);
            object.base_card_types = object.card_types.clone();
            object.mana_cost = ManaCost::zero();
            object.base_mana_cost = object.mana_cost.clone();
        }
        let sibling_action = GameAction::CastSpell {
            object_id: sibling_spell,
            card_id: state.objects[&sibling_spell].card_id,
            targets: Vec::new(),
            payment_mode: crate::types::game_state::CastPaymentMode::Auto,
        };
        let prohibition = zones::create_object(
            &mut state,
            CardId(7_302),
            PlayerId(1),
            "Preflight Name Prohibition".to_string(),
            Zone::Battlefield,
        );
        {
            use crate::types::ability::{ChosenAttribute, StaticDefinition, TargetFilter};
            use crate::types::statics::{ProhibitionScope, StaticMode};

            let object = state.objects.get_mut(&prohibition).unwrap();
            object.card_types.core_types.push(CoreType::Enchantment);
            object.base_card_types = object.card_types.clone();
            object
                .chosen_attributes
                .push(ChosenAttribute::CardName("Preflight Morph".to_string()));
            object.static_definitions.push(
                StaticDefinition::new(StaticMode::CantBeCast {
                    who: ProhibitionScope::AllPlayers,
                })
                .affected(TargetFilter::HasChosenName),
            );
        }
        for _ in 0..3 {
            state.players[0].mana_pool.add(ManaUnit::new(
                ManaType::Colorless,
                morph,
                false,
                vec![],
            ));
        }
        let principal = priority_principal_for_preflight(&state)
            .expect("the synchronized priority window has a principal");
        let play_face_down = priority_preflight_candidates(&state, &principal)
            .into_iter()
            .find(|candidate| candidate.family() == PriorityReducerFamily::PlayFaceDown)
            .expect("the family-specific face-down candidate must be reachable");
        assert_eq!(play_face_down.family(), PriorityReducerFamily::PlayFaceDown);
        assert_eq!(
            preflight_priority_window(&state),
            PriorityPreflight::Actionable {
                family: PriorityReducerFamily::CastSpell,
            },
            "the unchanged first-wins aggregate must report the earlier CastSpell family"
        );
        let candidates = crate::ai_support::candidate_actions(&state);
        assert!(candidates
            .iter()
            .any(|candidate| candidate.action == sibling_action));
        assert!(candidates
            .iter()
            .all(|candidate| !matches!(candidate.action, GameAction::PlayFaceDown { .. })));
        let legal_actions = crate::ai_support::legal_actions(&state);
        assert!(legal_actions.contains(&sibling_action));
        assert!(legal_actions
            .iter()
            .all(|action| !matches!(action, GameAction::PlayFaceDown { .. })));

        let PriorityPreflightCandidate::Announcement(announcement) = play_face_down else {
            panic!("the reachable face-down family must carry a reducer announcement")
        };
        let action = priority_announcement_to_action(announcement);
        assert!(matches!(
            action,
            GameAction::PlayFaceDown { object_id, .. } if object_id == morph
        ));
        let mut projected = state.clone();
        super::apply_as_current(&mut projected, action)
            .expect("the reconstructed face-down announcement must reduce successfully");
        assert!(projected.waiting_for.pending_cast_ref().is_none());
        assert!(projected.pending_cast.is_none());
        assert_eq!(projected.objects[&morph].zone, Zone::Battlefield);
        assert!(projected.objects[&morph].face_down);
    }

    #[test]
    fn prospective_actionless_pass_rejects_an_actionable_window_without_mutation() {
        let player = PlayerId(0);
        let mut state = GameState::new_two_player(42);
        state.active_player = player;
        state.priority_player = player;
        state.phase = crate::types::phase::Phase::PreCombatMain;
        state.waiting_for = WaitingFor::Priority { player };
        let land = zones::create_object(
            &mut state,
            CardId(1),
            player,
            "Island".to_string(),
            Zone::Hand,
        );
        state
            .objects
            .get_mut(&land)
            .expect("new hand object exists")
            .card_types
            .core_types
            .push(CoreType::Land);
        state.players[player.0 as usize].hand.push_back(land);
        let before = state.clone();

        assert!(apply_actionless_priority_pass_for_prospective(&mut state).is_err());
        assert_eq!(state, before);
    }

    /// CR 602.2b + CR 601.2g: the Priority preflight announces an activation in
    /// the payment mode its offer carries. Greed ("{B}, Pay 2 life: Draw a
    /// card.") at one life with a Swamp and two Pristine Talismans ("{T}: Add
    /// {C}. You gain 1 life.") can be completed only by a manual payment, so its
    /// announcement reconstructs a Manual activation, which the reducer opens
    /// into the mana-payment window; at three life the same announcement is
    /// automatic and the activation is put on the stack.
    #[test]
    fn activate_ability_announcement_carries_the_offered_payment_mode() {
        use crate::types::actions::GameAction;
        use crate::types::game_state::CastPaymentMode;

        for (life, expected) in [(1, CastPaymentMode::Manual), (3, CastPaymentMode::Auto)] {
            let mut scenario = GameScenario::new();
            scenario.at_phase(Phase::PreCombatMain).with_life(P0, life);
            let greed = scenario
                .add_enchantment_from_oracle(P0, "Greed", "{B}, Pay 2 life: Draw a card.")
                .id();
            scenario.add_basic_land(P0, ManaColor::Black);
            for _ in 0..2 {
                scenario.add_artifact_from_oracle(
                    P0,
                    "Pristine Talisman",
                    "{T}: Add {C}. You gain 1 life.",
                );
            }
            let runner = scenario.build();
            let state = runner.state();
            let principal =
                priority_principal_for_preflight(state).expect("a synchronized priority window");

            let announced: Vec<GameAction> = priority_preflight_candidates(state, &principal)
                .into_iter()
                .filter_map(|candidate| match candidate {
                    PriorityPreflightCandidate::Announcement(announcement) => {
                        Some(priority_announcement_to_action(announcement))
                    }
                    PriorityPreflightCandidate::Indeterminate { .. } => None,
                })
                .filter(|action| {
                    matches!(action, GameAction::ActivateAbility { source_id, .. } if *source_id == greed)
                })
                .collect();
            assert_eq!(
                announced,
                vec![GameAction::ActivateAbility {
                    source_id: greed,
                    ability_index: 0,
                    payment_mode: expected,
                }],
                "life {life}"
            );

            let mut projected = state.clone();
            super::apply_as_current(&mut projected, announced[0].clone())
                .expect("the announced activation reduces");
            match expected {
                CastPaymentMode::Manual => assert!(
                    matches!(projected.waiting_for, WaitingFor::ManaPayment { .. }),
                    "CR 601.2g: the manual activation opens the window: {:?}",
                    projected.waiting_for
                ),
                CastPaymentMode::Auto | CastPaymentMode::AutoExceptSacrificialMana => {
                    assert_eq!(projected.stack.len(), 1, "the activation is on the stack")
                }
            }
        }
    }
}

#[cfg(test)]
mod shortcut_schema_tests {
    use super::{build_shortcut_schema, MAX_SHORTCUT_CYCLES};
    use crate::analysis::decision_template::IterationCount;

    /// The constructor NARROWS a published suggestion to the capacity it derives and never
    /// RAISES one — the one site where a producer's seed and this engine's budget meet.
    ///
    /// Board class: a producer that measured NO threshold, so the derived capacity is the
    /// budget, handing a `Fixed` seed strictly below it. The offer-level rows cannot see this
    /// arm: a producer that measured a threshold seeds exactly that threshold, so narrowing and
    /// setting-to-capacity publish the same integer there.
    ///
    /// REVERT-PROBE: make the `Fixed` arm `Fixed(deliverable_capacity)` (set-to-capacity) ⇒ the
    /// unmeasured seed is published as the budget and the inequality below FLIPS. Drop the
    /// `.min(..)` ⇒ the over-capacity seed below is published unnarrowed ⇒ FLIPS.
    #[test]
    fn the_constructor_narrows_a_suggestion_and_never_raises_one() {
        let seed = 3;
        assert!(
            seed < MAX_SHORTCUT_CYCLES,
            "BOARD CLASS: the seed must sit strictly below the budget, else narrowing and \
             setting-to-capacity publish the same integer and this arm measures nothing"
        );
        let unmeasured = build_shortcut_schema(Vec::new(), IterationCount::Fixed(seed), None);
        assert!(
            !unmeasured.is_bounded(),
            "REACH-GUARD: this arm's subject is a producer that measured nothing"
        );
        assert_eq!(unmeasured.deliverable_capacity, MAX_SHORTCUT_CYCLES);
        assert_eq!(
            unmeasured.iteration_count,
            IterationCount::Fixed(seed),
            "the seed is published as handed, not raised to the capacity"
        );
        assert_ne!(
            unmeasured.iteration_count,
            IterationCount::Fixed(unmeasured.deliverable_capacity),
            "suggestion and capacity are UNEQUAL here — the shape a set-to-capacity \
             constructor cannot produce"
        );

        // The other direction, same invocation: a seed ABOVE the derived capacity comes back
        // narrowed TO it, so the arm fires both ways rather than passing by inaction.
        let measured = 5;
        assert!(
            measured < MAX_SHORTCUT_CYCLES,
            "BOARD CLASS: sub-budget threshold"
        );
        let over = build_shortcut_schema(
            Vec::new(),
            IterationCount::Fixed(measured + 4),
            Some(measured),
        );
        assert_eq!(over.deliverable_capacity, measured);
        assert_eq!(over.iteration_count, IterationCount::Fixed(measured));

        // Hostile sibling: `WithoutEnd` names no count, so there is nothing to narrow — the
        // member a `match` collapsing both variants would break.
        let endless = build_shortcut_schema(Vec::new(), IterationCount::WithoutEnd, Some(measured));
        assert_eq!(endless.iteration_count, IterationCount::WithoutEnd);
        assert_eq!(endless.deliverable_capacity, measured);
    }
}

/// item-4 C2b — `build_bounded_declaration`, the consumer that turns the window's observed
/// answers into the offer's own CR 732.2a declaration.
///
/// TIER NOTE, stated because it is FORCED rather than chosen: rows D1 / D1-P / D1-P-sib drive
/// the real F4 dump through production `apply()` and live in
/// `crates/engine/tests/integration/fantastic_four_bounded_loop.rs`. The three rows HERE are the
/// ones no tracked board can reach — a `Decline`d CR 603.5 answer at a certifying offer, and a
/// point kind the bounded publisher cannot mint — so each states its own unreachability rather
/// than implying a wire row was available and skipped.
#[cfg(test)]
mod bounded_declaration_tests {
    use super::{build_bounded_declaration, build_shortcut_schema, pin_observed_declaration};
    use crate::analysis::decision_template::{
        ChoicePoint, DecisionPoint, DecisionPointKind, DecisionSlot, IterationCount,
        MayChoiceOption, PinnedDecision, ShortcutDecisionSchema, TargetPin,
    };
    use crate::analysis::resource::SlotCharge;
    use crate::types::ability::TargetRef;
    use crate::types::game_state::{GameState, YieldTarget};
    use crate::types::identifiers::ObjectId;
    use crate::types::mana::ManaColor;
    use crate::types::player::PlayerId;

    const PROPOSER: PlayerId = PlayerId(0);
    const AIMED: PlayerId = PlayerId(1);

    /// A CR 400.7-stable source identity, built the way `object_decision_source` builds one.
    fn source(id: u64) -> YieldTarget {
        YieldTarget::ThisObject {
            source_id: ObjectId(id),
            incarnation: Some(1),
            trigger_description: None,
        }
    }

    fn take(slot: &DecisionSlot) -> PinnedDecision {
        PinnedDecision::MayChoice {
            slot: slot.clone(),
            take: MayChoiceOption::Take,
        }
    }

    /// The announcement at `slot` that resolved in the certified window aimed at `AIMED`.
    fn aimed(slot: &DecisionSlot) -> SlotCharge {
        SlotCharge {
            slot: slot.clone(),
            magnitude: 1,
            reaches: vec![AIMED],
            aimed_at: Some(AIMED),
        }
    }

    fn targets_kind() -> DecisionPointKind {
        DecisionPointKind::Targets {
            legal_targets: vec![TargetRef::Player(AIMED)],
            min_targets: 1,
            max_targets: 1,
            ordered: false,
        }
    }

    /// The two-kind schema the bounded publisher actually mints: one CR 603.5 `may` gate and one
    /// CR 601.2c target slot, on two distinct sources.
    fn may_and_target_schema() -> ShortcutDecisionSchema {
        build_shortcut_schema(
            vec![
                DecisionPoint {
                    slot: DecisionSlot::first(source(100), ChoicePoint::MayGate),
                    kind: DecisionPointKind::MayChoice,
                },
                DecisionPoint {
                    slot: DecisionSlot::first(source(200), ChoicePoint::AnnouncedTarget),
                    kind: targets_kind(),
                },
            ],
            IterationCount::Fixed(4),
            Some(4),
        )
    }

    /// **Row D3 — the consumer is TOTAL and FAIL-CLOSED over the four `DecisionPointKind`s the
    /// bounded producer cannot mint.**
    ///
    /// CR 700.2 (`Mode`), CR 732.6 (`UnlessBreak`), CR 601.2h + CR 702.51a (`ConvokeTaps`) and
    /// CR 608.2d + CR 605.3b (`ManaColor`) are real choice kinds that an observed aim does not
    /// answer, so there is nothing to pin for them and the declaration must refuse rather than
    /// guess.
    ///
    /// # ⚠ THE CHARGE ON THE FOUR-KIND POINT IS LOAD-BEARING, NOT DECORATION
    ///
    /// An UNCHARGED four-kind point with no recorded answer exits at the recorded lookup's `?` —
    /// before control ever reaches the arm this row is about — and the reddening mutation returns
    /// `None` there too, so real and mutant AGREE and nothing can red. Each case therefore
    /// charges its own point.
    ///
    /// # Unreachable today, and the row says so
    ///
    /// `bounded_cycle_pin_slots_for_window` constructs only `Targets` and `MayChoice` points. The
    /// other four have one producer, `pinned_decisions_to_points`, which serves the two mints that
    /// publish `declaration: None`. The row exists so a publisher relaxation gets a red test
    /// instead of a silent pin.
    ///
    /// REVERT-PROBE: replace the four-kind arm with `_ => continue` ⇒ each case builds a
    /// `Some(template)` with the four-kind point silently dropped ⇒ every `is_none()` flips while
    /// the control stays green.
    ///
    /// *What wrong implementation would still pass this row?* One that returns `None` for
    /// EVERYTHING — which the control arm (the same fixture with only mintable kinds) refuses.
    #[test]
    fn d3_the_consumer_fail_closes_on_every_kind_the_bounded_publisher_cannot_mint() {
        // Each kind rides with the CHOICE POINT it names, because the odd slot is minted at
        // the point its own published kind means rather than at one value for all four.
        let unmintable = [
            (
                ChoicePoint::Mode,
                DecisionPointKind::Mode {
                    available_modes: vec![0, 1],
                    min_modes: 1,
                    max_modes: 1,
                    allow_repeats: false,
                },
            ),
            (ChoicePoint::UnlessBreak, DecisionPointKind::UnlessBreak),
            (
                ChoicePoint::ConvokeTaps,
                DecisionPointKind::ConvokeTaps {
                    tappable: vec![ObjectId(31)],
                },
            ),
            (
                ChoicePoint::ManaColor,
                DecisionPointKind::ManaColor {
                    color: ManaColor::Blue,
                },
            ),
        ];

        // ── CONTROL, first: the same shape with only MINTABLE kinds yields `Some` ──
        let control_schema = may_and_target_schema();
        let state = GameState::new_two_player(7);
        assert!(
            build_bounded_declaration(
                &state,
                PROPOSER,
                &control_schema,
                None,
                &[
                    take(&control_schema.points[0].slot),
                    PinnedDecision::Targets {
                        slot: control_schema.points[1].slot.clone(),
                        targets: vec![TargetPin::Player(AIMED)],
                    },
                ],
                &[],
                &control_schema.iteration_count
            )
            .is_some(),
            "CONTROL: a fully-answered two-kind schema DOES publish a declaration — without this \
             a consumer that refused everything would pass all four cases below"
        );

        for (point, kind) in unmintable {
            let odd_slot = DecisionSlot::first(source(300), point);
            let schema = build_shortcut_schema(
                vec![
                    DecisionPoint {
                        slot: DecisionSlot::first(source(100), ChoicePoint::MayGate),
                        kind: DecisionPointKind::MayChoice,
                    },
                    DecisionPoint {
                        slot: odd_slot.clone(),
                        kind: kind.clone(),
                    },
                ],
                IterationCount::Fixed(4),
                Some(4),
            );
            // The OTHER point is answered, so the refusal cannot be attributed to it; the pin
            // step is asked directly because the publisher's coverage gate refuses a dropped
            // point too.
            assert!(
                pin_observed_declaration(
                    &state,
                    PROPOSER,
                    &schema.points,
                    &[aimed(&odd_slot)],
                    &[take(&schema.points[0].slot)],
                )
                .is_none(),
                "CR 732.2a: an observed aim does not answer {kind:?}, so the declaration must \
                 refuse rather than pin a guess or silently drop the point"
            );
        }
    }

    /// **Row D4 — an empty schema publishes NO declaration.**
    ///
    /// LOAD-BEARING, not tidiness: an empty schema exposes no slot, so a declaration minted
    /// against one that pinned a SLOT-ADDRESSING choice would be refused by the handler that
    /// has to accept it — `validate_pins` matches those pins to a published point. Publishing
    /// one would make `declaration.is_some()`, the predicate `ai_support::candidates` gates
    /// its declare candidate on, mean the opposite of what it says.
    /// The invariant is also staged at fixture level by
    /// `tests/integration/loop_shortcut.rs::r28_empty_schema_offer`, which passes
    /// `declaration: None` for this reason.
    ///
    /// REVERT-PROBE: delete the `schema.points.is_empty()` early return ⇒ the loop body never
    /// runs, step (4) builds a template with ZERO decisions ⇒ `is_none()` flips.
    ///
    /// *What wrong implementation would still pass this row?* One that also refuses a
    /// fully-answered NON-empty schema — which D3's control refuses.
    #[test]
    fn d4_an_empty_schema_publishes_no_declaration() {
        let empty = build_shortcut_schema(Vec::new(), IterationCount::Fixed(4), Some(4));
        assert!(
            empty.points.is_empty(),
            "reach-guard: this fixture is the empty-schema case"
        );
        // Answered anyway: the refusal must be keyed on the EMPTY POINT SET, not on an empty
        // answer list.
        let recorded = [take(&DecisionSlot::first(
            source(100),
            ChoicePoint::MayGate,
        ))];
        assert!(
            build_bounded_declaration(
                &GameState::new_two_player(7),
                PROPOSER,
                &empty,
                None,
                &recorded,
                &[],
                &empty.iteration_count
            )
            .is_none(),
            "CR 732.2a: an offer that publishes no choice states no declaration"
        );
    }

    /// **Row D8 — the PUBLISHER cannot publish what the HANDLER would refuse.**
    ///
    /// `ai_support::candidates` reads `declaration.is_some()` as *"`handle_declare_shortcut`
    /// will accept this"* and hands the published template straight to `DeclareShortcut`. That
    /// reading was unenforced: the publisher ran neither firewall half. This row pins the
    /// implication itself.
    ///
    /// # The two halves are measured on DIFFERENT instruments, so this is not circular
    ///
    /// The "handler refuses it" half is measured by calling `validate_pins` DIRECTLY on the
    /// template the pre-fix publisher would have emitted — the handler's own value-legality
    /// firewall, at the range that handler validates a capacity-valued `Fixed` declaration over.
    /// Only then is the publisher asked. A row that asserted `is_none()` alone would pass on a
    /// publisher that refuses for any unrelated reason.
    ///
    /// # Reach-guards, asserted BEFORE the claim
    ///
    /// `predictability_gate` PASSES on the hostile template (both published slots are pinned) —
    /// so the refusal is attributable to the VALUE half, not to coverage. Reachability is NOT
    /// claimed: the disagreement staged here is fixture-made.
    ///
    /// REVERT-PROBE: delete step (5)'s `declaration_conforms(..)` call (return `Some(template)`)
    /// ⇒ the hostile arm's `is_none()` flips while the control stays green.
    ///
    /// *What wrong implementation would still pass this row?* One that validates COVERAGE only —
    /// `predictability_gate` alone passes here, which is why the reach-guard asserts it. And one
    /// that refuses everything, which the control arm refuses.
    #[test]
    fn d8_the_publisher_refuses_a_declaration_the_declare_handler_would_reject() {
        use crate::analysis::decision_template::{
            declaration_conforms, predictability_gate, validate_pins, DecisionGroupKey,
            DecisionKind, DecisionTemplate, ReplayMode,
        };

        let schema = may_and_target_schema();
        let [may_point, target_point] = &schema.points[..] else {
            panic!("the fixture publishes exactly two points");
        };
        // CR 608.2b: the published legal set names AIMED only, so a pin naming PROPOSER is
        // outside the offer's own legal set — an illegal pin VALUE at a legally exposed slot.
        assert!(
            !matches!(&target_point.kind, DecisionPointKind::Targets { legal_targets, .. }
                if legal_targets.contains(&TargetRef::Player(PROPOSER))),
            "reach-guard: PROPOSER must NOT be a published legal target, or the hostile pin \
             below is a conforming one and this row measures nothing"
        );

        for (label, pinned, expect_published) in [
            ("hostile", TargetPin::Player(PROPOSER), false),
            ("control", TargetPin::Player(AIMED), true),
        ] {
            let state = GameState::new_two_player(7);

            // The template the UNVALIDATED publisher would have emitted, spelled out here so the
            // handler-side half below is measured on it rather than on whatever the publisher
            // now returns.
            let as_published = DecisionTemplate {
                owner: PROPOSER,
                decisions: vec![
                    PinnedDecision::MayChoice {
                        slot: may_point.slot.clone(),
                        take: MayChoiceOption::Take,
                    },
                    PinnedDecision::Targets {
                        slot: target_point.slot.clone(),
                        targets: vec![pinned.clone()],
                    },
                ],
                replay: ReplayMode::Scheduled {
                    count: schema.iteration_count.clone(),
                },
                key: DecisionGroupKey::from_sources(
                    &schema
                        .points
                        .iter()
                        .map(|point| point.slot.source.clone())
                        .collect::<Vec<_>>(),
                    DecisionKind::LoopChoice,
                ),
            };
            assert!(
                predictability_gate(&as_published, &schema.points).is_ok(),
                "[{label}] reach-guard: COVERAGE passes on this template — every published slot \
                 is pinned — so the handler's verdict below is the VALUE half's"
            );

            // ── HALF 1, on the handler's own instrument: would `handle_declare_shortcut` take
            //    it, at the range it validates the AI's capacity-valued `Fixed` candidate over?
            let handler_accepts =
                validate_pins(&schema, &as_published, schema.deliverable_capacity, &state).is_ok();
            assert_eq!(
                handler_accepts, expect_published,
                "[{label}] the declare-time pin firewall's verdict on the published shape"
            );
            // This row stages no certified period, so the AIM conjunct takes its `per_cycle`
            // absence arm and the authority's verdict here is its coverage ∧ value half.
            assert_eq!(
                declaration_conforms(
                    &schema,
                    &as_published,
                    schema.deliverable_capacity,
                    crate::analysis::decision_template::AimContext {
                        proposer: PROPOSER,
                        per_cycle: None,
                        published: Some(&as_published),
                    },
                    None,
                    &state
                ),
                handler_accepts,
                "[{label}] and the shared authority agrees with its own value half — it is a \
                 conjunction of its gates, not a separate predicate"
            );

            // ── HALF 2: the PUBLISHER's verdict must be the same one ──
            assert_eq!(
                build_bounded_declaration(
                    &state,
                    PROPOSER,
                    &schema,
                    None,
                    &as_published.decisions,
                    &[],
                    &schema.iteration_count
                )
                .is_some(),
                handler_accepts,
                "[{label}] CR 732.2a: `declaration.is_some()` is read as 'the declare handler \
                 will accept this'. A template the handler refuses must NOT be published, and a \
                 template it accepts must be"
            );
        }
    }

    /// CR 732.2a: over a recorded period the publisher states the period's own answers.
    #[test]
    fn the_publisher_refuses_a_declaration_the_recorded_period_did_not_answer() {
        let schema = may_and_target_schema();
        let [may_point, target_point] = &schema.points[..] else {
            panic!("the fixture publishes exactly two points");
        };
        let state = GameState::new_two_player(7);
        let recorded = |take| {
            vec![
                PinnedDecision::MayChoice {
                    slot: may_point.slot.clone(),
                    take,
                },
                PinnedDecision::Targets {
                    slot: target_point.slot.clone(),
                    targets: vec![TargetPin::Player(AIMED)],
                },
            ]
        };
        let published = |recorded: &[PinnedDecision]| {
            build_bounded_declaration(
                &state,
                PROPOSER,
                &schema,
                None,
                recorded,
                &[],
                &schema.iteration_count,
            )
            .map(|template| {
                template.decisions.iter().find_map(|pin| match pin {
                    PinnedDecision::MayChoice { take, .. } => Some(*take),
                    _ => None,
                })
            })
        };
        assert_eq!(
            published(&recorded(MayChoiceOption::Take)),
            Some(Some(MayChoiceOption::Take)),
        );
        assert_eq!(
            published(&recorded(MayChoiceOption::Decline)),
            Some(Some(MayChoiceOption::Decline)),
            "the \"may\" is published as the recorded period answered it"
        );
    }
}

/// PR-7 Combo-UI Stage 2: the pin slots a bounded offer publishes and the declare firewall.
#[cfg(test)]
mod stage2_injector_tests {
    use super::*;
    use crate::analysis::decision_template::{
        ChoicePoint, DecisionGroupKey, DecisionKind, DecisionSlot, DecisionTemplate,
        IterationCount, PinnedDecision, ReplayMode,
    };
    use crate::game::scenario::GameScenario;
    use crate::types::game_state::YieldTarget;

    const P0: PlayerId = PlayerId(0);
    const P1: PlayerId = PlayerId(1);
    const P2: PlayerId = PlayerId(2);

    fn this_object(id: ObjectId) -> YieldTarget {
        YieldTarget::ThisObject {
            source_id: id,
            incarnation: None,
            trigger_description: None,
        }
    }

    /// The window enumerator over `state.stack` alone.
    fn stack_pin_slots(
        state: &GameState,
        proposer: PlayerId,
    ) -> Vec<crate::analysis::decision_template::DecisionPoint> {
        bounded_cycle_pin_slots_for_window(
            &crate::analysis::resource::certified_period_touch(
                &[],
                state,
                crate::analysis::resource::PeriodCertification::ResourceSignatureOnly,
            ),
            proposer,
        )
    }

    /// Park a test offer with the shared certificate and caller-provided schema.
    fn park_on_shortcut_offer(
        state: &mut GameState,
        schema: crate::analysis::decision_template::ShortcutDecisionSchema,
    ) {
        use crate::analysis::loop_check::{LoopCertificate, WinKind};
        use crate::analysis::resource::BoardDelta;

        state.waiting_for = WaitingFor::LoopShortcut {
            proposer: P0,
            predicted_winner: None,
            certificate: LoopCertificate {
                unbounded: Vec::new(),
                rising: Vec::new(),
                win_kind: Some(WinKind::LethalDamage),
                win_kind_at: None,
                mandatory: false,
                residual_board_delta: BoardDelta::default(),
                per_cycle: None,
            },
            schema,
            declaration: None,
            counted_take: Default::default(),
            period: Default::default(),
        };
    }

    /// Place a bare object in `zone` without touching the zone vectors — enough for the
    /// identity/zone predicates under test, which read `state.objects` only.
    fn place(state: &mut GameState, id: u64, zone: crate::types::zones::Zone) -> ObjectId {
        let oid = ObjectId(id);
        let mut o = crate::game::game_object::GameObject::new(
            oid,
            CardId(0),
            P0,
            "Emblem".to_string(),
            zone,
        );
        o.incarnation = 3;
        state.objects.insert(oid, o);
        oid
    }

    /// CR 114.4 + CR 608.2b: a pinned SLOT whose source is a command-zone emblem must match
    /// the prompt that emblem raised; a graveyard or exile source must NOT.
    ///
    /// The shipped BATTLEFIELD arm is exercised end-to-end by `injector_routes_pinned_targets_per_source` above and by the
    /// `kilo_live_offer_from_real_dump` rows, and this row asserts that arm is unchanged.
    ///
    /// The zone disjuncts this row pins now live one call down, in
    /// [`crate::analysis::decision_template::resolve_ability_instance`], which
    /// `slot_source_prompted` delegates to — so all three probes below are run THERE. That
    /// delegation is why this row is also the maintained-invariant row for the factoring: it
    /// stays green unmodified, and a factoring that silently widened the zone set reds here.
    /// (Measured: dropping the `Zone::Command` filter in that accessor fails the graveyard
    /// assertion below.)
    ///
    /// REVERT-PROBES: (a) delete the command-zone disjunct ⇒ the
    /// Command assertion FAILS; (b) widen the disjunct to accept any zone ⇒ the graveyard and
    /// exile assertions FAIL; (c) drop the incarnation conjunct ⇒ the CR 400.7 assertion
    /// FAILS.
    #[test]
    fn command_zone_sourced_slot_matches_and_graveyard_still_aborts() {
        use crate::types::zones::Zone;
        let mut state = GameScenario::new_n_player(2, 7).build().state().clone();
        let battlefield = place(&mut state, 900, Zone::Battlefield);
        let emblem = place(&mut state, 901, Zone::Command);
        let graveyard = place(&mut state, 902, Zone::Graveyard);
        let exiled = place(&mut state, 903, Zone::Exile);

        let pin = |id: ObjectId, inc: Option<u64>| YieldTarget::ThisObject {
            source_id: id,
            incarnation: inc,
            trigger_description: None,
        };

        // Shipped behaviour, unchanged: the battlefield arm still matches.
        assert!(
            slot_source_prompted(&state, &pin(battlefield, Some(3)), battlefield),
            "the shipped CR 608.2b battlefield arm must be untouched"
        );
        // CR 114.2 — an emblem lives in the command zone; CR 114.4 — its abilities function
        // there, which is why the slot may prompt from there.
        assert!(
            slot_source_prompted(&state, &pin(emblem, Some(3)), emblem),
            "CR 114.4: a command-zone emblem's slot must match the prompt it raised"
        );
        // Fail-closed: every other off-battlefield zone still misses.
        assert!(
            !slot_source_prompted(&state, &pin(graveyard, Some(3)), graveyard),
            "a graveyard-sourced slot must NOT match — the drive aborts to manual"
        );
        assert!(
            !slot_source_prompted(&state, &pin(exiled, Some(3)), exiled),
            "an exile-sourced slot must NOT match"
        );
        // CR 400.7: the command arm re-binds ONE incarnation, exactly like the
        // battlefield arm — a re-created emblem does not answer the old pin.
        assert!(
            !slot_source_prompted(&state, &pin(emblem, Some(2)), emblem),
            "CR 400.7: a stale incarnation must not match even in the command zone"
        );
        // A pin naming a DIFFERENT object never answers this prompt.
        assert!(
            !slot_source_prompted(&state, &pin(emblem, Some(3)), battlefield),
            "the matcher is keyed on identity, not merely on zone"
        );
    }

    /// CR 732.2a + CR 603.5: `bounded_cycle_pin_slots_for_window` publishes the per-iteration TARGET
    /// choice for a proposer-controlled player-targeting trigger, plus a second `MayChoice`
    /// point (disambiguated by `slot.point`) when that trigger is optional.
    ///
    /// MATCHED PAIRS, one variable each:
    /// * `optional` false ⇒ 1 point; true ⇒ 2 points. REVERT-PROBE: delete the `optional`
    ///   branch ⇒ the 2-point assertion FAILS.
    /// * controller == proposer ⇒ published; a bystander proposer gets nothing.
    ///   REVERT-PROBE: delete the `entry.controller != proposer` filter ⇒ the bystander
    ///   assertion FAILS.
    #[test]
    fn bounded_cycle_pin_slots_publishes_the_may_gate_of_an_optional_trigger() {
        use crate::analysis::decision_template::{ChoicePoint, DecisionPointKind, DecisionSlot};
        use crate::types::ability::{
            ControllerRef, Effect, QuantityExpr, ResolvedAbility, TargetFilter, TypedFilter,
        };

        let mut state = GameScenario::new_n_player(3, 7).build().state().clone();
        let src = place(&mut state, 910, crate::types::zones::Zone::Battlefield);

        let entry = |id: u64, controller: PlayerId, optional: bool| {
            let mut ability = ResolvedAbility::new(
                Effect::LoseLife {
                    amount: QuantityExpr::Fixed { value: 1 },
                    target: Some(TargetFilter::Typed(TypedFilter {
                        type_filters: vec![],
                        controller: Some(ControllerRef::Opponent),
                        properties: vec![],
                    })),
                },
                vec![],
                src,
                controller,
            );
            ability.optional = optional;
            StackEntry {
                id: ObjectId(id),
                source_id: src,
                controller,
                kind: StackEntryKind::TriggeredAbility {
                    source_id: src,
                    ability: Box::new(ability),
                    condition: None,
                    trigger_event: None,
                    description: None,
                    source_name: String::new(),
                    subject_match_count: None,
                    die_result: None,
                    provenance: None,
                },
            }
        };
        let live_source =
            object_decision_source(&state, src).expect("the source is on the battlefield");
        // The parameter names WHICH CHOICE, because the two callers mean different ones: the
        // CR 601.2c announcement and the CR 603.5 "may" gate on one source.
        let expected_slot = |point: ChoicePoint| DecisionSlot::first(live_source.clone(), point);

        // Mandatory: exactly one point, the target choice.
        state.stack.push_back(entry(920, P0, false));
        let mandatory = stack_pin_slots(&state, P0);
        assert_eq!(
            mandatory.len(),
            1,
            "a mandatory trigger publishes one point"
        );
        assert_eq!(
            mandatory[0].slot,
            expected_slot(ChoicePoint::AnnouncedTarget)
        );
        assert!(
            matches!(
                &mandatory[0].kind,
                DecisionPointKind::Targets { legal_targets, .. }
                    if *legal_targets == vec![TargetRef::Player(P1), TargetRef::Player(P2)]
            ),
            "the legal set comes from `find_legal_targets`, not from a declaration: {:?}",
            mandatory[0].kind
        );

        // Bystander proposer: the same board publishes nothing for a seat that controls
        // none of the entries (CR 732.2a — the proposer specifies their OWN choices).
        assert!(
            stack_pin_slots(&state, P1).is_empty(),
            "a bystander proposer controls none of these choices"
        );

        // Optional: the SAME entry with one field flipped publishes the CR 603.5 gate too.
        state.stack.clear();
        state.stack.push_back(entry(921, P0, true));
        let optional = stack_pin_slots(&state, P0);
        assert_eq!(
            optional.len(),
            2,
            "an optional trigger publishes two points"
        );
        assert_eq!(
            optional[1].slot,
            expected_slot(ChoicePoint::MayGate),
            "`slot.point` is what tells the CR 603.5 gate from the CR 601.2c announcement on \
             this one source"
        );
        assert_eq!(optional[1].kind, DecisionPointKind::MayChoice);

        // ── R9 leg 1: point IDENTITY and published ORDER both survive the move ──
        //
        // CR 601.2c + CR 603.5. Two points on ONE source: a pin built for either must not
        // validate against the other, and the two must compare in the same relative order
        // they compared in at the base — which is what `ChoicePoint`'s declaration order is
        // fixed for, since `cmp_game_actions` reads `DecisionSlot`'s derived `Ord` and a
        // `DeclareShortcut` participates in deterministic AI action ordering. Asserted on the
        // slots' `Ord`, not on their position in the published list.
        assert!(
            optional[0].slot < optional[1].slot,
            "the CR 601.2c announcement still sorts before the CR 603.5 gate on one source: \
             {:?} vs {:?}",
            optional[0].slot,
            optional[1].slot
        );
        for (pin_point, answers, refuses) in [
            (ChoicePoint::AnnouncedTarget, 0usize, 1usize),
            (ChoicePoint::MayGate, 1, 0),
        ] {
            let pin = crate::analysis::decision_template::PinnedDecision::MayChoice {
                slot: expected_slot(pin_point),
                take: crate::analysis::decision_template::MayChoiceOption::Take,
            };
            assert_ne!(
                pin.slot(),
                &optional[refuses].slot,
                "a pin built for {pin_point:?} does not address the other published point — \
                 the slot test `pin_answers_point` runs first is what refuses it"
            );
            // The paired positive on the same instrument: whole-slot equality still holds at
            // the point the pin WAS built for, so the refusal above is about the point rather
            // than about the comparison being broken.
            assert_eq!(
                pin.slot(),
                &optional[answers].slot,
                "…and it names the slot of its own published point exactly"
            );
        }

        // ── R9 leg 4: an `Order` pin still publishes NO point ──
        //
        // CR 603.3b: giving the pin a slot does not make it addressable by a declaration.
        // The `Targets` pin in the SAME list is the positive control.
        let announced = expected_slot(ChoicePoint::AnnouncedTarget);
        let published = pinned_decisions_to_points(
            &[
                crate::analysis::decision_template::PinnedDecision::Order {
                    slot: expected_slot(ChoicePoint::TriggerOrder),
                    pos: 0,
                },
                crate::analysis::decision_template::PinnedDecision::Targets {
                    slot: announced.clone(),
                    targets: vec![crate::analysis::decision_template::TargetPin::Player(P1)],
                },
            ],
            &state,
            P0,
        )
        .expect("the pin list materializes");
        assert_eq!(
            published
                .iter()
                .map(|point| point.slot.clone())
                .collect::<Vec<_>>(),
            vec![announced],
            "the ordering pin mints no point; its sibling in the same list does"
        );

        // Fail-closed: no source object ⇒ no point (never a slot that cannot re-bind).
        state.objects.remove(&src);
        assert!(
            stack_pin_slots(&state, P0).is_empty(),
            "an absent source emits nothing rather than an unbindable slot"
        );
    }

    /// Each of [`declares_opponent_player_target`]'s three conjuncts, discriminated
    /// SEPARATELY. The gross "accept any `Typed`" widening is caught by the row above; this
    /// row is what fails when ONE conjunct is dropped.
    ///
    /// Why each matters: `find_legal_targets` collapses a `Typed` filter to PLAYERS ONLY
    /// when both `type_filters` and `properties` are empty (issue
    /// #2004). A type- or property-bearing filter therefore falls through to OBJECT
    /// enumeration — publishing it would put a point whose legal set is object refs into
    /// player-pin machinery. `controller: You` does collapse to players, but to exactly ONE
    /// (the controller), which is not the per-opponent choice a bounded drain cycle pins.
    ///
    /// THE BOARD IS LOAD-BEARING, and picking the wrong one is what hollows this row out.
    /// On a head-announced board an object-shaped filter enumerates NOTHING, so
    /// `build_target_slots` returns `Err` and the caller's CARDINALITY conjunct rejects
    /// first — measured: with both arms on that board, dropping `type_filters.is_empty()` or
    /// `properties.is_empty()` left the row GREEN. Those two arms therefore run on the
    /// MIRROR shape, the one thing they alone reject: an object-shaped head at
    /// `TargetChoiceTiming::Resolution` (announces nothing) chained to a `target opponent`
    /// sub-ability (announces the one slot). Cardinality and all-`Player` both pass there.
    /// The per-arm reach-guard asserts that announced slot verbatim, so a future change that
    /// re-hollows an arm fails the reach-guard instead of passing silently.
    ///
    /// REVERT-PROBES (each measured on the boards below): drop `type_filters.is_empty()` ⇒
    /// ONLY the Creature arm publishes; drop `properties.is_empty()` ⇒ ONLY the Token arm;
    /// drop `controller == Some(Opponent)` ⇒ ONLY the `You` arm. The accepted shape is
    /// asserted to publish in the SAME row, so a constant-`false` predicate cannot pass.
    #[test]
    fn bounded_cycle_pin_slots_conjuncts_are_each_load_bearing() {
        use crate::types::ability::{
            ControllerRef, Effect, FilterProp, QuantityExpr, ResolvedAbility, TargetChoiceTiming,
            TargetFilter, TargetRef, TypeFilter, TypedFilter,
        };

        let mut base = GameScenario::new_n_player(3, 7).build().state().clone();
        let src = place(&mut base, 940, crate::types::zones::Zone::Battlefield);

        let board = |ability: ResolvedAbility| {
            let mut state = base.clone();
            state.stack.push_back(StackEntry {
                id: ObjectId(950),
                source_id: src,
                controller: P0,
                kind: StackEntryKind::TriggeredAbility {
                    source_id: src,
                    ability: Box::new(ability),
                    condition: None,
                    trigger_event: None,
                    description: None,
                    source_name: String::new(),
                    subject_match_count: None,
                    die_result: None,
                    provenance: None,
                },
            });
            state
        };
        let accepted = TypedFilter {
            type_filters: vec![],
            controller: Some(ControllerRef::Opponent),
            properties: vec![],
        };
        let head_only = |tf: TypedFilter| {
            ResolvedAbility::new(
                Effect::LoseLife {
                    amount: QuantityExpr::Fixed { value: 1 },
                    target: Some(TargetFilter::Typed(tf)),
                },
                vec![],
                src,
                P0,
            )
        };
        // The head's own choice is made on resolution, so CR 601.2c is never reached for it
        // and it announces no slot; the ONE announced slot is the chained sub-ability's
        // `target opponent` player choice (CR 603.3d). Cardinality and all-`Player` pass
        // whatever shape the head declares — which is what leaves the head-shape conjunct
        // alone to reject.
        let chained = |head: TypedFilter| {
            let mut ability = head_only(head);
            ability.target_choice_timing = TargetChoiceTiming::Resolution;
            ability.sub_ability = Some(Box::new(head_only(accepted.clone())));
            ability
        };

        // POSITIVE CONTROL, same row: the accepted "target opponent" shape publishes.
        assert_eq!(
            stack_pin_slots(&board(head_only(accepted.clone())), P0).len(),
            1,
            "the accepted CR 115.2 player shape must publish — otherwise the three zeros \
             below are vacuous"
        );

        let opponents = vec![TargetRef::Player(P1), TargetRef::Player(P2)];
        // Collected, not asserted per-arm: a revert-probe must show which arms flipped, and
        // a bare `assert!` in the loop would abort at the first and hide the rest.
        let mut still_published: Vec<&str> = Vec::new();
        for (label, ability, announced) in [
            (
                "type_filters: a creature filter enumerates OBJECTS, not players",
                chained(TypedFilter {
                    type_filters: vec![TypeFilter::Creature],
                    ..accepted.clone()
                }),
                opponents.clone(),
            ),
            (
                "properties: issue #2004 — `token` is an object characteristic",
                chained(TypedFilter {
                    properties: vec![FilterProp::Token],
                    ..accepted.clone()
                }),
                opponents.clone(),
            ),
            (
                "controller: `You` is a single forced seat, not a per-opponent choice",
                head_only(TypedFilter {
                    controller: Some(ControllerRef::You),
                    ..accepted.clone()
                }),
                vec![TargetRef::Player(P0)],
            ),
        ] {
            let state = board(ability);
            let announcement = crate::game::ability_utils::build_target_slots(
                &state,
                state.stack[0]
                    .ability()
                    .expect("the board pushes a trigger"),
            )
            .map(|slots| {
                slots
                    .iter()
                    .map(|slot| (slot.optional, slot.legal_targets.clone()))
                    .collect::<Vec<_>>()
            })
            .ok();
            assert_eq!(
                announcement,
                Some(vec![(false, announced)]),
                "reach-guard [{label}]: exactly ONE mandatory slot and every candidate a \
                 PLAYER — so the cardinality and all-`Player` conjuncts both PASS on this \
                 board and the head-shape conjunct under test is the SOLE rejector"
            );
            if !stack_pin_slots(&state, P0).is_empty() {
                still_published.push(label);
            }
        }
        assert!(
            still_published.is_empty(),
            "each conjunct must reject its own arm ALONE; these arms published anyway: \
             {still_published:?}"
        );

        // ORDERING-INPUT CONJUNCTS. The published point declares `min/max_targets: 1`, and
        // the gate-(3) relief is a bare `continue` that discharges the WHOLE of
        // `stack_entry_has_no_ordering_input` (analysis/resource.rs) — which rejects on
        // four facts, only one of which a slot answers. The three ABILITY facts must block
        // publication outright (the state-dependent fourth, `pending_trigger_entry`, is the
        // relief's). Shares the positive control above.
        {
            use crate::types::ability::MultiTargetSpec;
            use crate::types::game_state::TargetSelectionConstraint;

            fn ability_of(state: &mut GameState) -> &mut ResolvedAbility {
                let StackEntryKind::TriggeredAbility { ability, .. } = &mut state.stack[0].kind
                else {
                    unreachable!("the fixture board pushes a TriggeredAbility")
                };
                ability.as_mut()
            }

            type Mutate = fn(&mut GameState);
            let ordering_input: [(&str, Mutate); 3] = [
                ("multi_target — CR 601.2c variable target count", |s| {
                    ability_of(s).multi_target = Some(MultiTargetSpec::fixed(1, 2))
                }),
                ("distribution — CR 601.2d divide-among", |s| {
                    ability_of(s).distribution = Some(vec![(TargetRef::Player(P1), 1)])
                }),
                ("target_constraints — CR 601.2c cross-target", |s| {
                    ability_of(s).target_constraints =
                        vec![TargetSelectionConstraint::DifferentTargetPlayers]
                }),
            ];
            for (label, mutate) in ordering_input {
                let mut state = board(head_only(accepted.clone()));
                mutate(&mut state);
                assert!(
                    stack_pin_slots(&state, P0).is_empty(),
                    "{label}: announcement-time ordering input NO published slot specifies \
                     ⇒ the mint must not publish"
                );
            }
        }
    }

    /// CR 601.2c (via CR 603.3d) + CR 115.1d: the lead the declare and consumption seams read is
    /// the lead the mint reads. Blood Artist ("Whenever this creature or another creature dies,
    /// target player loses 1 life and you gain 1 life.") latched at P1 leads with P1 on both
    /// readers, as the "target opponent" head does; a bystander proposer, or Blood Artist's entry
    /// unlatched, leads with nothing on either.
    #[test]
    fn a_latched_player_aim_leads_alike_for_the_mint_and_the_declare_seams() {
        use crate::analysis::decision_template::{ConcreteDecision, ConcreteTarget};
        use crate::types::ability::{
            ControllerRef, Effect, QuantityExpr, ResolvedAbility, TargetFilter, TargetRef,
            TypedFilter,
        };

        let mut base = GameScenario::new_n_player(3, 7).build().state().clone();
        let src = place(&mut base, 940, crate::types::zones::Zone::Battlefield);
        let slot = DecisionSlot::first(
            YieldTarget::ThisObject {
                source_id: src,
                incarnation: Some(base.objects[&src].incarnation),
                trigger_description: None,
            },
            ChoicePoint::AnnouncedTarget,
        );
        let board = |head: TargetFilter, targets: Vec<TargetRef>| {
            let mut ability = ResolvedAbility::new(
                Effect::LoseLife {
                    amount: QuantityExpr::Fixed { value: 1 },
                    target: Some(head),
                },
                targets,
                src,
                P0,
            );
            ability.sub_ability = Some(Box::new(ResolvedAbility::new(
                Effect::GainLife {
                    amount: QuantityExpr::Fixed { value: 1 },
                    player: TargetFilter::Controller,
                },
                vec![],
                src,
                P0,
            )));
            let mut state = base.clone();
            state.stack.push_back(StackEntry {
                id: ObjectId(950),
                source_id: src,
                controller: P0,
                kind: StackEntryKind::TriggeredAbility {
                    source_id: src,
                    ability: Box::new(ability),
                    condition: None,
                    trigger_event: None,
                    description: None,
                    source_name: String::new(),
                    subject_match_count: None,
                    die_result: None,
                    provenance: None,
                },
            });
            state
        };
        let readers = |state: &GameState, proposer: PlayerId| {
            (
                leading_announcement_aims(state, proposer),
                lead_decisions(&leading_announcement_pairs(
                    state,
                    proposer,
                    1,
                    std::slice::from_ref(&slot),
                )),
            )
        };
        let opponent = TargetFilter::Typed(TypedFilter {
            type_filters: vec![],
            controller: Some(ControllerRef::Opponent),
            properties: vec![],
        });
        let led = vec![ConcreteDecision::Targets {
            slot: slot.clone(),
            targets: vec![ConcreteTarget::Player(P1)],
        }];
        for (label, head) in [
            ("target player", TargetFilter::Player),
            ("target opponent", opponent),
        ] {
            let latched = board(head.clone(), vec![TargetRef::Player(P1)]);
            assert_eq!(readers(&latched, P0), (led.clone(), led.clone()), "{label}");
            assert_eq!(
                readers(&latched, P1),
                (vec![], vec![]),
                "{label}: bystander"
            );
        }
        assert_eq!(
            readers(&board(TargetFilter::Player, vec![]), P0),
            (vec![], vec![]),
            "target player: unlatched"
        );
    }

    /// The real 4p acceptance board (dump B): a CR 114.2 emblem in the COMMAND zone
    /// (obj 541, incarnation 0) whose triggered ability drains `target opponent`.
    fn load_dellian_dump() -> GameState {
        use crate::types::game_state::PersistedGameState;
        use std::io::Read;
        let gz: &[u8] = include_bytes!("../../tests/fixtures/dellian_emblem_conqueror_4p.json.gz");
        let mut json = String::new();
        flate2::read::GzDecoder::new(gz)
            .read_to_string(&mut json)
            .expect("fixture inflates");
        let mut envelope: serde_json::Value = serde_json::from_str(&json).expect("envelope parses");
        // Committed pre-onset capture; onset-independent test (see record_captured_onsets).
        crate::types::game_state::record_captured_onsets(&mut envelope);
        // Cross the dump through the PRODUCTION decoder rather than a bare `GameState`
        // decode wrapped in `Raw`: `PersistedGameState`'s own `Deserialize` runs
        // `reject_legacy_raw_prompt_authority` and `decode_persisted_resolution_state`
        // first, so this helper exercises the chokepoint the server's `from_persisted`
        // and WASM's `decode_restored_game_state` actually funnel through — including
        // the CR 732.2a load-seam bound invariant.
        // The test unwraps the fallible persistence boundary after asserting this fixture decodes.
        serde_json::from_value::<PersistedGameState>(envelope["gameState"].clone())
            .expect("gameState deserializes through the production decoder")
            .into_game_state()
            .expect("persisted test snapshot satisfies the checked restore contract")
    }

    const EMBLEM: ObjectId = ObjectId(541);

    /// CR 601.2c + CR 115.1: the migrated fixture's `effect_kind` is not an assertion of
    /// taste — it is exactly what the ANNOUNCEMENT AUTHORITY builds for this ability on
    /// this board. `scripts/migrate-dump-fixture.sh` takes the value as an explicit
    /// argument precisely so the engine, and never a jq name→variant table, stays the
    /// authority for it; this row is what holds the script's operator to that.
    ///
    /// It is also the row that would have caught upstream #6718 (`0468df1f4`, which added
    /// `TargetSelectionSlot::effect_kind` with no `#[serde(default)]`) the day it landed:
    /// `TargetSelectionSlot` derives `PartialEq`/`Eq`, so this compares ALL five fields,
    /// not just the migrated one.
    ///
    /// REVERT-PROBE: re-run the migration script with `--effect-kind NoOp` ⇒ the stamped
    /// slot stops matching what `build_target_slots` derives ⇒ FAILS. This assertion is
    /// the SOLE guard on the migrated value — nothing on the drive path reads the field
    /// (its only production readers are the two `target_intent` calls in the interaction
    /// DTO projection), so a wrong value cannot move the game and must be caught by a
    /// reading test instead of by a behavioural one.
    #[test]
    fn dellian_dump_slots_are_what_the_announcement_authority_builds() {
        let state = load_dellian_dump();
        let pt = state
            .pending_trigger
            .as_ref()
            .expect("dellian dump pauses on a pending trigger");
        // `let … else` rather than `if let`: it fails LOUDLY if the dump ever restores
        // into some other prompt, which would otherwise make the assertion unreachable
        // rather than false.
        let WaitingFor::TriggerTargetSelection { target_slots, .. } = &state.waiting_for else {
            panic!(
                "dellian dump must restore into TriggerTargetSelection, got {:?}",
                state.waiting_for
            );
        };
        // Reach-guard: an empty slot vector would satisfy a total-equality assertion
        // vacuously on both sides.
        assert_eq!(
            target_slots.len(),
            1,
            "the dellian dump publishes exactly one target slot"
        );
        assert_eq!(
            &crate::game::ability_utils::build_target_slots(&state, &pt.ability)
                .expect("the emblem's drain ability builds its announcement slots"),
            target_slots,
            "the restored dump's slots must equal what the announcement authority builds"
        );

        // CR 732.2a + CR 114.2: the window enumerator publishes the command-zone emblem's
        // `target opponent` point, the same with the prompt up and at `Priority`, and nothing for
        // a bystander proposer.
        use crate::analysis::decision_template::DecisionPointKind;
        const P3: PlayerId = PlayerId(3);
        let emblem = &state.objects[&EMBLEM];
        assert_eq!(emblem.zone, crate::types::zones::Zone::Command);
        assert_eq!(
            state.stack.iter().filter(|e| e.source_id == EMBLEM).count(),
            1,
            "reach: one emblem entry"
        );
        let expected = (
            DecisionSlot {
                source: YieldTarget::ThisObject {
                    source_id: EMBLEM,
                    incarnation: Some(emblem.incarnation),
                    trigger_description: None,
                },
                point: ChoicePoint::AnnouncedTarget,
                index: 0,
            },
            DecisionPointKind::Targets {
                legal_targets: vec![
                    TargetRef::Player(P1),
                    TargetRef::Player(P2),
                    TargetRef::Player(P3),
                ],
                min_targets: 1,
                max_targets: 1,
                ordered: false,
            },
        );
        let with_prompt = stack_pin_slots(&state, P0);
        let targets: Vec<_> = with_prompt
            .iter()
            .filter(|p| matches!(p.kind, DecisionPointKind::Targets { .. }))
            .map(|p| (p.slot.clone(), p.kind.clone()))
            .collect();
        assert_eq!(targets, vec![expected]);
        let mut at_priority = state.clone();
        at_priority.waiting_for = WaitingFor::Priority { player: P0 };
        assert_eq!(stack_pin_slots(&at_priority, P0), with_prompt);
        assert!(at_priority.stack.iter().all(|e| e.controller == P0));
        for bystander in [P1, P2, P3] {
            assert!(
                stack_pin_slots(&at_priority, bystander).is_empty(),
                "{bystander:?}"
            );
        }
    }

    /// CR 732.2a: the offer publishes the SET of open per-iteration choices — one point per
    /// SOURCE, not one per stack ENTRY.
    ///
    /// `DecisionSlot`'s POINT disambiguates two choices of ONE ability instance and its
    /// INSTANCE ORDINAL disambiguates instances of one of those choices — neither disambiguates
    /// instances of the ABILITY, so N
    /// entries from one source would mint N byte-identical slots: N identical frontend
    /// pickers, and `predictability_gate` demanding N pins for a choice
    /// answered ONCE per source (`take_answer` keys on the slot's CHOICE
    /// POINT and SOURCE, and a published point carries one answer whatever its instance ordinal). Real boards reach this shape — this very dump carries 35
    /// entries on source 25, 34 on 126 and 34 on 208.
    ///
    /// Built on the LOADED 4p board plus ONE measured mutation: a byte-copy of the real
    /// emblem entry under a fresh stack-entry id, which is exactly what a second loop
    /// iteration puts there.
    ///
    /// REVERT-PROBE: drop either `points.iter().any(|p| p.slot == ..)` dedupe guard ⇒ the
    /// two-entry board publishes 2 points ⇒ FAILS.
    #[test]
    fn bounded_cycle_pin_slots_publishes_one_point_per_source_not_per_entry() {
        let mut state = load_dellian_dump();
        let emblem_entry = state
            .stack
            .iter()
            .find(|e| e.source_id == EMBLEM)
            .expect("reach-guard: the dump carries the emblem's trigger")
            .clone();
        let single = stack_pin_slots(&state, P0);
        // Reach-guard, re-derived from the loaded board rather than from a literal: the
        // mint qualifies FOUR sources here — the CR 115.2 emblem target (541) plus three
        // shape-(B) CR 603.5 may-only sources (126, 208, 274). 126 and 208 carry 34 stack
        // entries apiece, so the shipped board ALREADY exercises the dedupe: without it
        // this count would be 69, not 4.
        assert_eq!(
            single.len(),
            4,
            "reach-guard: the shipped board qualifies exactly four sources"
        );
        assert_eq!(
            single
                .iter()
                .filter(|p| matches!(
                    p.kind,
                    crate::analysis::decision_template::DecisionPointKind::Targets { .. }
                ))
                .count(),
            1,
            "reach-guard: exactly one of them is the emblem's TARGETS point"
        );

        let mut second = emblem_entry;
        second.id = ObjectId(9_001);
        state.stack.push_back(second);
        assert_eq!(
            state.stack.iter().filter(|e| e.source_id == EMBLEM).count(),
            2,
            "reach-guard: two live entries now share one source"
        );

        assert_eq!(
            stack_pin_slots(&state, P0),
            single,
            "a second entry from the SAME source is the same open choice — one published \
             point, byte-identical to the one-entry board's"
        );
    }

    // ───────────────────────── 5d U2 — the shape-(B) mint ─────────────────────────

    use crate::types::ability::ResolvedAbility;

    /// A 3-seat board plus one battlefield source object, shared by every U2 mint row so a
    /// row's verdict cannot come from board differences.
    fn u2_board() -> (GameState, ObjectId) {
        let mut state = GameScenario::new_n_player(3, 7).build().state().clone();
        let src = place(&mut state, 930, crate::types::zones::Zone::Battlefield);
        (state, src)
    }

    /// A proposer-controlled OPTIONAL, NO-TARGET triggered ability — shape (B)'s own shape.
    ///
    /// `target_choice_timing: Resolution` is what makes it shape (B), and it is the class's
    /// real rules shape rather than a test convenience: CR 601.2c announces only DECLARED
    /// targets, so Braids, Conjurer Adept — "At the beginning of each player's upkeep, that
    /// player may put an artifact, creature, or land card from their hand onto the
    /// battlefield." (CR 503.1a + CR 608.2d; text verified against Scryfall) — chooses its
    /// subject AT RESOLUTION and surfaces zero announcement slots.
    ///
    /// The `Effect::PutCounter` fixtures below are a SYNTHETIC STAND-IN, never Braids'
    /// printed effect: they exercise the same CLASS (per-player-upkeep optional,
    /// resolution-time subject, zero announcement slots) on an effect this mint's
    /// allow-list admits. The recipient branch they ride is EFFECT-AGNOSTIC (see
    /// `a_may_slot_is_minted_only_for_the_seat_the_cr_603_5_gate_will_ask`), which is what
    /// makes the substitution sound rather than a convenience. Measured on `u2_board`:
    /// `build_target_slots` returns `Ok(0)` for every fixture below (each row asserts the
    /// consequence through its own matched positive), so each really reaches the shape-(B)
    /// arm rather than falling out at an upstream conjunct.
    fn shape_b(src: ObjectId, effect: crate::types::ability::Effect) -> ResolvedAbility {
        let mut ability = ResolvedAbility::new(effect, vec![], src, P0);
        ability.optional = true;
        ability.target_choice_timing = crate::types::ability::TargetChoiceTiming::Resolution;
        ability
    }

    fn shape_b_entry(id: u64, src: ObjectId, ability: ResolvedAbility) -> StackEntry {
        StackEntry {
            id: ObjectId(id),
            source_id: src,
            controller: P0,
            kind: StackEntryKind::TriggeredAbility {
                source_id: src,
                ability: Box::new(ability),
                condition: None,
                trigger_event: None,
                description: None,
                source_name: String::new(),
                subject_match_count: None,
                die_result: None,
                provenance: None,
            },
        }
    }

    /// `Effect::PutCounter` on a `ScopedPlayer`-scoped creature filter — inside D4.3's
    /// six-arm scope filter, and the exact filter shape
    /// `filter_uses_relative_controller_scoped` keys on.
    fn scoped_put_counter() -> crate::types::ability::Effect {
        use crate::types::ability::{
            ControllerRef, Effect, QuantityExpr, TargetFilter, TypedFilter,
        };
        Effect::PutCounter {
            target: TargetFilter::Typed(TypedFilter {
                type_filters: vec![crate::types::ability::TypeFilter::Creature],
                controller: Some(ControllerRef::ScopedPlayer),
                properties: vec![],
            }),
            counter_type: crate::types::counter::CounterType::Plus1Plus1,
            count: QuantityExpr::Fixed { value: 1 },
        }
    }

    /// R23, conjuncts 1–2 — **CR 603.5: the `may` pin binds the prompt's RECIPIENT, not only
    /// the entry's OWNER.**
    ///
    /// Asserted AT THE MINT SEAM, deliberately: an offer-level negative would be satisfied by
    /// D4.3's scope filter on many boards regardless of this guard (the
    /// upstream-conjunct-dominates trap). The mint has no such upstream.
    ///
    /// `entry.controller == proposer` bounds who OWNS the entry; it does not bound who the
    /// resolver ASKS. `optional_prompt_player`'s last branch is EFFECT-AGNOSTIC — it fires on
    /// `ability.scoped_player` plus a `ScopedPlayer`-scoped `target_filter()` (CR 503.1a +
    /// CR 608.2d, the Braids, Conjurer Adept class — whose printed effect puts an artifact,
    /// creature, or land card from hand onto the battlefield, NOT a counter; `PutCounter`
    /// here is a synthetic stand-in for the class, which that branch admits precisely
    /// BECAUSE it is effect-agnostic) — so an allow-listed `PutCounter` reaches
    /// it. Without the conjunct, P0's pin would be spendable as P1's CR 603.5 choice.
    ///
    /// MATCHED POSITIVE, on the same instrument and differing in exactly `scoped_player`: it
    /// proves the fixture reaches the mint at all, so the negative is keyed to the recipient
    /// axis and not to one of the four upstream conjuncts.
    ///
    /// REVERT-PROBE: delete `&& effects::optional_prompt_player(state, ability) == proposer`
    /// from the `may` mint ⇒ the scoped-player entry publishes a `MayChoice` slot ⇒ the
    /// negative arm FLIPS TO FAIL.
    #[test]
    fn a_may_slot_is_minted_only_for_the_seat_the_cr_603_5_gate_will_ask() {
        let (mut state, src) = u2_board();

        // ── negative: the gate will ask P1, not the proposer ──
        let mut scoped = shape_b(src, scoped_put_counter());
        scoped.scoped_player = Some(P1);
        assert_eq!(
            crate::game::effects::optional_prompt_player(&state, &scoped),
            Some(P1),
            "reach-guard: the recipient authority must really route this entry to the OTHER \
             seat, or the negative below is about nothing"
        );
        let negative = shape_b_entry(940, src, scoped);
        assert!(
            entry_publishes_pin_slots(&state, &negative, P0).is_none(),
            "CR 603.5: a `may` the resolver will ask ANOTHER seat publishes no pin slot"
        );

        // ── matched positive: byte-identical except `scoped_player` ──
        let unscoped = shape_b(src, scoped_put_counter());
        assert_eq!(
            crate::game::effects::optional_prompt_player(&state, &unscoped),
            Some(P0),
            "reach-guard: with no scoped player the gate asks the controller = proposer"
        );
        let positive = shape_b_entry(941, src, unscoped);
        let published = entry_publishes_pin_slots(&state, &positive, P0)
            .expect("the matched positive must reach the mint and publish");
        assert!(
            published.may.is_some(),
            "the matched positive publishes the CR 603.5 gate"
        );
        assert!(
            published.target.is_none(),
            "shape (B): announcing it surfaces no CR 601.2c choice, so no target slot"
        );
        assert!(
            published.legal_targets.is_empty(),
            "no target slot carries no legal set"
        );

        // The published pair also reaches the point mint as ONE `MayChoice` point.
        state.stack.push_back(positive);
        let points = stack_pin_slots(&state, P0);
        assert_eq!(
            points.len(),
            1,
            "shape (B) publishes exactly the may point: {points:?}"
        );
        assert_eq!(
            points[0].kind,
            crate::analysis::decision_template::DecisionPointKind::MayChoice
        );
        assert_eq!(
            points[0].slot.point,
            crate::analysis::decision_template::ChoicePoint::MayGate,
            "CR 603.5: the slot names the MAY GATE in BOTH shapes — the property the old \
             `index == 1` read was standing in for, now stated directly"
        );
        assert_eq!(
            points[0].slot.index, 0,
            "…and it is the FIRST instance of that class on this source, the ordinal carrying \
             no part of WHICH choice it is"
        );
    }

    /// CR 608.2b: an optional addressed to a declared player nobody was announced as is asked
    /// of no one, so its `may` gate carries no recipient and the entry publishes no slot.
    #[test]
    fn a_may_slot_is_not_minted_for_an_unannounced_declared_player() {
        use crate::types::ability::{ChosenGroupId, TargetFilter};
        let (state, src) = u2_board();

        let mut unannounced = shape_b(src, scoped_put_counter());
        unannounced.optional_player = Some(TargetFilter::DeclaredPlayer {
            group: ChosenGroupId::declared_player(0),
        });
        assert_eq!(
            crate::game::effects::optional_prompt_player(&state, &unannounced),
            None,
            "reach-guard: no declared player resolves, so the gate has no recipient"
        );
        assert!(
            entry_publishes_pin_slots(&state, &shape_b_entry(942, src, unannounced), P0).is_none(),
            "a gate with no recipient mints no `may` slot for any proposer"
        );

        let addressed_to_nobody = shape_b(src, scoped_put_counter());
        assert_eq!(
            crate::game::effects::optional_prompt_player(&state, &addressed_to_nobody),
            Some(P0),
            "reach-guard: the same entry with no `optional_player` asks the controller"
        );
        let published =
            entry_publishes_pin_slots(&state, &shape_b_entry(943, src, addressed_to_nobody), P0)
                .expect("the matched positive must reach the mint and publish");
        assert!(published.may.is_some(), "the matched positive mints `may`");
    }

    /// The CR 603.5 prompt sites in ONE source text: `(producers, readers, in_test)`.
    ///
    /// A producer's key is `file::fn {fields}` — its enclosing column-0 `fn` plus the
    /// whitespace-stripped field text of the construction minted there, so a REPLACEMENT
    /// inside an already-pinned function moves the key. A reader keys as `file::fn`.
    fn cr_603_5_sites(rel: &str, text: &str) -> (Vec<String>, Vec<String>, usize) {
        use crate::source_census::code as code_of;

        /// The `#[cfg(test)]`-attributed column-0 `mod … {` … column-0 `}` spans.
        fn cfg_test_spans(lines: &[&str]) -> Vec<(usize, usize)> {
            let mut spans = Vec::new();
            let mut i = 0;
            while i < lines.len() {
                if lines[i].trim() == "#[cfg(test)]" {
                    let mut j = i + 1;
                    while j < lines.len()
                        && (lines[j].trim_start().starts_with("#[") || lines[j].trim().is_empty())
                    {
                        j += 1;
                    }
                    let is_mod = j < lines.len()
                        && lines[j].starts_with(['m', 'p'])
                        && lines[j].contains("mod ")
                        && lines[j].trim_end().ends_with('{');
                    if is_mod {
                        let mut k = j + 1;
                        while k < lines.len() && lines[k] != "}" {
                            k += 1;
                        }
                        spans.push((j, k));
                        i = k;
                    }
                }
                i += 1;
            }
            spans
        }

        /// The construction's field text, brace-matched over the CODE half from `after` —
        /// just past its opening `{` on line `n` — to the matching `}`, with ALL whitespace
        /// removed so re-indenting or re-breaking a field expression cannot move it.
        /// Unbalanced input runs to EOF and yields a key nothing matches: red, never a
        /// silent pass.
        fn fields(lines: &[&str], n: usize, after: usize) -> String {
            let mut body = String::new();
            let mut depth = 1usize;
            let mut rest = &code_of(lines[n])[after..];
            let mut i = n;
            loop {
                for ch in rest.chars() {
                    match ch {
                        '{' => depth += 1,
                        '}' => {
                            depth -= 1;
                            if depth == 0 {
                                return body;
                            }
                        }
                        _ => {}
                    }
                    if !ch.is_whitespace() {
                        body.push(ch);
                    }
                }
                i += 1;
                let Some(line) = lines.get(i) else {
                    return body;
                };
                rest = code_of(line);
            }
        }

        let lines: Vec<&str> = text.lines().collect();
        let spans = cfg_test_spans(&lines);
        // A whole file whose stem ends `_tests` is test-only (its parent declares it under
        // `#[cfg(test)]`).
        let test_file = rel.trim_end_matches(".rs").ends_with("_tests");

        // The needle is ASSEMBLED so this row's own source cannot be counted by its own
        // instrument. `..` excludes multi-line READ destructures whose rest-pattern sits on
        // a later line — the inflation the raw grep suffers from.
        let needle = format!("WaitingFor::{}Choice {{", "OptionalEffect");
        let (mut producers, mut readers, mut in_test) = (Vec::new(), Vec::new(), 0usize);
        // Enclosing-function tracker for this file: `enclosing` names each site and
        // `fn_start` bounds the qualifying look-back below, so no coordinate is minted.
        // Column-0 `fn` headers only — a producer inside an `impl` method would take the
        // preceding free function's name; all five producers today are free functions.
        let (mut enclosing, mut fn_start) = (String::new(), 0usize);
        for (n, line) in lines.iter().enumerate() {
            let code = code_of(line);
            if !line.starts_with([' ', '\t']) {
                let tokens: Vec<&str> = code.split_whitespace().collect();
                if let Some(at) = tokens.iter().position(|token| *token == "fn") {
                    enclosing = tokens
                        .get(at + 1)
                        .and_then(|token| token.split(['(', '<']).next())
                        .unwrap_or_default()
                        .to_string();
                    fn_start = n;
                }
            }
            let Some(open) = code.find(&needle) else {
                continue;
            };
            if code.contains("..") {
                continue;
            }
            if test_file || spans.iter().any(|(a, b)| (*a..=*b).contains(&n)) {
                in_test += 1;
            } else if code.contains("waiting_for = ")
                || code.contains("Ok(Some(")
                // `install_direct_choice_frame` owns the actual `state.waiting_for`
                // write, so its typed prompt argument is a mint, not a read. The
                // window is the enclosing fn; `code_of` keeps prose out of it.
                || lines[fn_start..n]
                    .iter()
                    .any(|prior| code_of(prior).contains(".install_direct_choice_frame("))
            {
                let body = fields(&lines, n, open + needle.len());
                let trimmed = body.trim_end_matches(',');
                producers.push(format!("{rel}::{enclosing} {{{trimmed}}}"));
            } else {
                readers.push(format!("{rel}::{enclosing}"));
            }
        }
        (producers, readers, in_test)
    }

    /// **The PRODUCER census, so a new producer is a COUNTED event.** What bounds the mint
    /// conjunct's reach is how many things PRODUCE `WaitingFor::OptionalEffectChoice`: the
    /// conjunct is a fail-closed pre-filter on ONE of them. Exactly one of the four sits
    /// inside the CR 603.5 gate that consults the recipient authority (the repeated-payment
    /// offer consults it too, but mints no may-trigger key), so if a fifth appears this row
    /// fails and whoever added it must decide where its recipient is bound.
    ///
    /// A producer is identified by its ENCLOSING FUNCTION and the CONSTRUCTION it mints
    /// (`file::fn {fields}`, whitespace stripped), and the qualifying
    /// `.install_direct_choice_frame(` look-back is bounded by that same function. NO line
    /// coordinate is asserted, so movement above a producer is not an event and a REPLACEMENT
    /// inside a pinned function is. The pin is a sorted MULTISET, so a sixth mint in one of them
    /// still fails here; comment text is never a site (`source_census::code`).
    #[test]
    fn the_cr_603_5_prompt_census_is_pinned_so_a_sixth_producer_is_a_counted_event() {
        /// Every `.rs` under the crate's `src`.
        fn rs_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("readable source dir") {
                let path = entry.expect("readable dir entry").path();
                if path.is_dir() {
                    rs_files(&path, out);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    out.push(path);
                }
            }
        }

        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = Vec::new();
        rs_files(&root, &mut files);
        files.sort();
        assert!(files.len() > 100, "reach-guard: the walker found the crate");

        let (mut producers, mut readers, mut in_test) = (Vec::new(), Vec::new(), 0usize);
        for path in &files {
            let text = std::fs::read_to_string(path).expect("readable source file");
            let rel = path
                .strip_prefix(&root)
                .expect("under src")
                .display()
                .to_string()
                // Canonicalize to forward slashes so the census pins below are
                // platform-independent: `Path::display()` emits the OS-native
                // separator (backslash on Windows), but the pins are written in
                // the crate's forward-slash convention. No-op on Unix/CI.
                .replace('\\', "/");
            let (file_producers, file_readers, file_in_test) = cr_603_5_sites(&rel, &text);
            producers.extend(file_producers);
            readers.extend(file_readers);
            in_test += file_in_test;
        }
        producers.sort();

        assert_eq!(
            producers.len() + readers.len() + in_test,
            54,
            "CR 603.5 prompt census drifted. A new PRODUCER must have its recipient bound \
             somewhere — the mint's conjunct (a) covers exactly ONE of them. A new READER is \
             the benign case (U4's own consumption arm was one).\n\
             producers={producers:#?}\nreaders={readers:#?}"
        );
        assert_eq!(
            (producers.len(), readers.len(), in_test),
            (4, 9, 41),
            "the partition, not just the total: four PRODUCTION producers, nine PRODUCTION \
             readers (including the two optional-subject projection reads), and 41 \
             `#[cfg(test)]` lines, including the ChooseOneOf, retained optional/outer, \
             and retained repeat/choice restore fixtures.\nproducers={producers:#?}\n\
             readers={readers:#?}"
        );
        assert_eq!(
            producers,
            vec![
                "game/effects/mod.rs::offer_repeated_payment {player,decision_subject_id:None,source_id:payment_unit.source_id,description:payment_unit.description.clone(),may_trigger_key:None,same_card_may_trigger_choice_available:false}".to_string(),
                "game/effects/mod.rs::resolve_chain_body {player:prompt_player,decision_subject_id,source_id:ability.source_id,description,may_trigger_key,same_card_may_trigger_choice_available}".to_string(),
                "game/effects/scoped_library_search.rs::advance_acceptance {player,decision_subject_id:None,source_id,description,may_trigger_key:None,same_card_may_trigger_choice_available:false}".to_string(),
                "game/engine.rs::begin_pending_trigger_target_selection {player,decision_subject_id:None,source_id,description:trigger_description,may_trigger_key,same_card_may_trigger_choice_available}".to_string(),
            ],
            "the four production producers, each keyed by its ENCLOSING FUNCTION and the \
             CONSTRUCTION it mints, compared as a sorted MULTISET, so a fifth mint inside one \
             of these functions still fails here. Two of the four choose `player` WITHOUT \
             consulting the recipient authority, which is exactly why the mint conjunct is a \
             fail-closed pre-filter and not a soundness proof. A CR 603.5 producer's \
             construction changed — if that was intended, update this literal; if it was not, \
             you changed who or how the optional choice is offered."
        );

        // Exactly ONE of them routes through the recipient authority: the CR 603.5 gate.
        let effects_src = std::fs::read_to_string(root.join("game/effects/mod.rs"))
            .expect("readable effects module");
        let authority = format!("{}_prompt_player", "optional");
        // Counted over the CODE HALF of each line, via `crate::source_census::code`: a prose
        // mention of the authority is not a call. A real second call still trips this, because
        // a call cannot live in comment text.
        let authority_code_hits = effects_src
            .lines()
            .map(crate::source_census::code)
            .filter(|l| l.contains(&authority))
            .count();
        assert_eq!(
            authority_code_hits, 3,
            "one definition + two calls — the CR 603.5 gate's `let prompt_player = ..` and the \
             repeated-payment offer, which asks the named player per iteration. A third call \
             inside `effects/mod.rs` means another producer started consulting the authority \
             and this row's partition needs re-deriving"
        );
    }

    /// The producer key's discrimination, on PLANTED input: the real tree cannot exhibit both
    /// polarities at once, so a repo-scanning assertion for this property is vacuous BY
    /// CONSTRUCTION. Each arm feeds `cr_603_5_sites` a synthetic source and states what the
    /// key must and must not move with. The mint spelling is ASSEMBLED, so none of these
    /// sources is itself a census site.
    #[test]
    fn a_producer_key_moves_with_the_construction_and_not_with_its_position() {
        let mint = format!("WaitingFor::{}Choice {{", "OptionalEffect");
        let rel = "game/planted.rs";
        let keys = |lines: &[&str]| cr_603_5_sites(rel, &lines.join("\n")).0;
        let base_key = format!(
            "{rel}::mint_one {{player:prompt_player,source_id:ability.source_id,may_trigger_key}}"
        );
        let assign = format!("    state.waiting_for = {mint}");

        // BASELINE — the paired positive for the bare negative below: the same scanner,
        // through the same helpers, returns exactly one key for one construction.
        let baseline = keys(&[
            "fn mint_one() {",
            assign.as_str(),
            "        player: prompt_player,",
            "        source_id: ability.source_id,",
            "        may_trigger_key,",
            "    };",
            "}",
        ]);
        assert_eq!(
            baseline,
            vec![base_key.clone()],
            "one construction in one function keys as `file::fn {{fields}}`"
        );

        let moved = keys(&[
            "// text above the producer",
            "// more text above the producer",
            "// and more",
            "fn mint_one() {",
            "    let _ = ();",
            assign.as_str(),
            "        player: prompt_player,",
            "        source_id: ability.source_id,",
            "        may_trigger_key,",
            "    };",
            "}",
        ]);
        assert_eq!(
            moved, baseline,
            "inserting lines above a producer must not move its key"
        );

        let nested_assign = format!("        state.waiting_for = {mint}");
        let renested = keys(&[
            "fn mint_one() {",
            "    if gate {",
            nested_assign.as_str(),
            "            player: prompt_player,",
            "            source_id: ability",
            "                .source_id,",
            "            may_trigger_key,",
            "        };",
            "    }",
            "}",
        ]);
        assert_eq!(
            renested, baseline,
            "re-indenting the construction and breaking a field expression across lines is \
             what `rustfmt` does; neither may move the key"
        );

        let twice = keys(&[
            "fn mint_one() {",
            assign.as_str(),
            "        player: prompt_player,",
            "        source_id: ability.source_id,",
            "        may_trigger_key,",
            "    };",
            assign.as_str(),
            "        player: prompt_player,",
            "        source_id: ability.source_id,",
            "        may_trigger_key,",
            "    };",
            "}",
        ]);
        assert_eq!(
            twice,
            vec![base_key.clone(), base_key.clone()],
            "a second mint inside an already-pinned function is a counted event: the keys are \
             a MULTISET, not a set"
        );

        let removed = keys(&["fn mint_one() {", "    let _ = ();", "}"]);
        assert!(
            removed.is_empty(),
            "a function that mints nothing yields no key, got {removed:?}"
        );

        let rebound = keys(&[
            "fn mint_one() {",
            assign.as_str(),
            "        player: ability.controller,",
            "        source_id: ability.source_id,",
            "        may_trigger_key,",
            "    };",
            "}",
        ]);
        assert_eq!(
            rebound,
            vec![format!(
                "{rel}::mint_one {{player:ability.controller,source_id:ability.source_id,may_trigger_key}}"
            )],
            "the recipient expression is part of the key"
        );

        let second_authority = keys(&[
            "fn mint_one() {",
            assign.as_str(),
            "        player: prompt_player,",
            "        source_id: ability.source_id,",
            "        may_trigger_key: None,",
            "    };",
            "}",
        ]);
        assert_eq!(
            second_authority,
            vec![format!(
                "{rel}::mint_one {{player:prompt_player,source_id:ability.source_id,may_trigger_key:None}}"
            )],
            "the stored-choice authority is part of the key, with the recipient HELD"
        );

        assert!(
            rebound != baseline && second_authority != baseline,
            "a construction REPLACED inside an already-pinned function must move its key — \
             recipient rebound: {rebound:?}; stored-choice authority changed: \
             {second_authority:?}; unchanged construction: {baseline:?}"
        );
    }

    /// R25 — **a stored `may` auto-choice is a SECOND authority on the same CR 603.5
    /// question, and the mint must refuse to it.**
    ///
    /// Without the conjunct the pin is minted, then the gate consumes the stored choice and
    /// **returns before setting any prompt**. The declared `Take` would be silently replaced by
    /// the stored `Decline`. `MayTriggerAutoChoiceKey`/`Record` are `Serialize + Deserialize`, so a real
    /// dump can carry one.
    ///
    /// MATCHED POSITIVE, differing ONLY in the seeded record, so no upstream conjunct can
    /// dominate.
    ///
    /// REVERT-PROBE: delete the `ability.may_trigger_origin.as_ref().is_none_or(…is_none())`
    /// conjunct from the `may` mint ⇒ the seeded entry publishes a `MayChoice` slot ⇒ the
    /// negative arm FLIPS TO FAIL.
    #[test]
    fn a_stored_may_auto_choice_is_a_second_authority_the_mint_refuses_to() {
        use crate::types::ability::{
            Effect, QuantityExpr, TargetFilter, TriggerBaseSetInstanceRef,
            TriggerDefinitionOccurrenceRef, TriggerDefinitionRef,
        };
        use crate::types::game_state::{AutoMayChoice, MayTriggerAutoChoiceKey, MayTriggerOrigin};
        use crate::types::identifiers::ObjectIncarnationRef;

        let (mut state, src) = u2_board();
        // The production shape: `triggers.rs` mints `Definition { definition_ref }` from the
        // source's own incarnation plus the printed occurrence — built here identically.
        let origin = MayTriggerOrigin::Definition {
            definition_ref: TriggerDefinitionRef {
                source: ObjectIncarnationRef::of(src, 3),
                occurrence: TriggerDefinitionOccurrenceRef::Printed {
                    base_set: TriggerBaseSetInstanceRef::INITIAL,
                    printed_index: 0,
                },
            },
        };
        let with_origin = |src: ObjectId| {
            let mut ability = shape_b(
                src,
                Effect::Draw {
                    count: QuantityExpr::Fixed { value: 1 },
                    target: TargetFilter::Controller,
                },
            );
            ability.may_trigger_origin = Some(origin.clone());
            ability
        };

        // ── matched positive: no stored record ⇒ the gate WILL prompt ⇒ mint publishes ──
        let entry = shape_b_entry(950, src, with_origin(src));
        assert!(
            state.may_trigger_auto_choices.is_empty(),
            "reach-guard: the positive arm runs with NO stored record"
        );
        assert!(
            entry_publishes_pin_slots(&state, &entry, P0)
                .expect("the positive arm publishes")
                .may
                .is_some(),
            "with no stored answer the CR 603.5 gate really asks, so the pin is spendable"
        );

        // ── negative: the SAME board with one record seeded ──
        state.set_may_trigger_auto_choice(
            MayTriggerAutoChoiceKey {
                player: P0,
                source_id: src,
                origin: origin.clone(),
            },
            AutoMayChoice::Decline,
        );
        assert_eq!(
            state.may_trigger_auto_choice(&MayTriggerAutoChoiceKey {
                player: P0,
                source_id: src,
                origin,
            }),
            Some(AutoMayChoice::Decline),
            "reach-guard: the mint's key must be the key the seed stored, or the negative \
             passes for the wrong reason"
        );
        assert!(
            entry_publishes_pin_slots(&state, &entry, P0).is_none(),
            "CR 603.5: a stored auto-choice already answers this may, so a minted pin would \
             be silently unused — refuse it at the mint. Shape (B) has no other slot, so the \
             whole entry publishes nothing"
        );
    }

    /// R30 — **one published `MayChoice` slot stands for exactly ONE CR 603.5 prompt.**
    ///
    /// CR 732.2a requires the shortcut to describe *the* sequence of choices; a schema point
    /// is a choice SURFACE, so a slot that answers one prompt while the resolution opens N is
    /// a schema that under-describes its own sequence. Production suppresses the single
    /// up-front CR 603.5 gate for three `repeat_for` shapes and re-fires optionality PER
    /// ITERATION (CR 608.2c + CR 608.2d) instead. The mint asks production's own three
    /// predicates rather than re-deriving them — re-deriving is the drift defect one symbol
    /// over.
    ///
    /// THREE ARMS, one per predicate, each with its matched positive on the same instrument:
    /// * **(a) kind-driven — the reachable one.** `has_kind_driven_repeat` matches on
    ///   `repeat_for` and on NOTHING else (no `Effect` restriction), so an allow-listed
    ///   optional `PutCounter` of that shape reaches it. **(a′)** differs only in
    ///   `repeat_for: None`.
    /// * **(b) member-driven — live for an allow-listed effect.** `Effect::Token` with
    ///   `attach_to: Some(ParentTarget)` (Asinine Antics' shape, named in
    ///   `effect_parent_ref_slots`' own doc) is inside the allow list and reaches
    ///   `effect_iterates_over_parent_target`. **(b′)** differs in exactly the predicate's
    ///   own deciding leaf: `attach_to: Some(LastCreated)` is ALSO a context ref, so the head
    ///   filter is still `owner`, the shape is still (B) and the `repeat_for` is still
    ///   `ObjectCount` — only `filter_refs_parent_target` flips. Without (b′) a blanket
    ///   "refuse every `ObjectCount`" would pass, which is coarser than production and a mint
    ///   cost.
    /// * **(c) repeated optional payment — DISCLOSED as not independently reachable.** It
    ///   requires `Effect::PayCost`, which D4.3's scope filter refuses at conjunct (6), so no
    ///   certifiable offer carries such an entry. The arm asserts the mint's refusal only and
    ///   claims NO closed hole; it ships so the mint asks the same three questions production
    ///   asks.
    ///
    /// REVERT-PROBE: delete the three sub-conjuncts from the `may` mint ⇒ (a) and (b) FLIP TO
    /// FAIL while (a′)/(b′) stay green — the pairs discriminate the conjunct, not the fixture.
    #[test]
    fn one_published_may_slot_stands_for_exactly_one_cr_603_5_prompt() {
        use crate::types::ability::{
            AbilityCondition, AbilityCost, Effect, PtValue, QuantityExpr, QuantityRef, TargetFilter,
        };

        let (state, src) = u2_board();
        let publishes_may = |ability: ResolvedAbility, id: u64| -> bool {
            let entry = shape_b_entry(id, src, ability);
            entry_publishes_pin_slots(&state, &entry, P0)
                .and_then(|p| p.may)
                .is_some()
        };

        // ── (a) kind-driven, and (a′) its matched positive ──
        let kind_driven = || {
            let mut a = shape_b(src, scoped_put_counter());
            a.repeat_for = Some(QuantityExpr::Ref {
                qty: QuantityRef::DistinctCounterKindsAmong {
                    filter: TargetFilter::Controller,
                },
            });
            a
        };
        assert!(
            crate::game::effects::has_kind_driven_repeat(&kind_driven()),
            "reach-guard: production's own predicate must say TRUE for arm (a)'s fixture"
        );
        assert!(
            !publishes_may(kind_driven(), 960),
            "(a) CR 608.2c/608.2d: a `DistinctCounterKindsAmong` repeat fires ONE prompt PER \
             ITERATION, so a single slot would under-describe the CR 732.2a sequence"
        );
        let mut kind_positive = kind_driven();
        kind_positive.repeat_for = None;
        assert!(
            publishes_may(kind_positive, 961),
            "(a′) byte-identical except `repeat_for: None` ⇒ published, so (a) keys on the \
             repeat axis and not on `optional`, the recipient or the auto-choice conjunct"
        );

        // ── (b) member-driven, and (b′) the one-leaf matched positive ──
        let token_attached = |attach: TargetFilter| {
            let mut a = shape_b(
                src,
                Effect::Token {
                    name: "Cursed Role".to_string(),
                    power: PtValue::Fixed(1),
                    toughness: PtValue::Fixed(1),
                    types: vec!["Enchantment".to_string()],
                    colors: vec![],
                    keywords: vec![],
                    tapped: false,
                    count: QuantityExpr::Fixed { value: 1 },
                    owner: TargetFilter::Controller,
                    attach_to: Some(attach),
                    enters_attacking: false,
                    attack_destination:
                        crate::types::ability::TokenAttackDestination::ControllerChooses,
                    supertypes: vec![],
                    static_abilities: vec![],
                    enter_with_counters: vec![],
                },
            );
            a.repeat_for = Some(QuantityExpr::Ref {
                qty: QuantityRef::ObjectCount {
                    filter: TargetFilter::Controller,
                },
            });
            a
        };
        assert!(
            crate::game::effects::has_member_driven_repeat_after_hydration(
                &state,
                &token_attached(TargetFilter::ParentTarget)
            ),
            "reach-guard: the `ParentTarget` fixture must really reach \
             `effect_iterates_over_parent_target`"
        );
        assert!(
            !publishes_may(token_attached(TargetFilter::ParentTarget), 962),
            "(b) CR 608.2c/608.2d: an `ObjectCount` repeat over a parent-target ref fires one \
             prompt per iterated member"
        );
        assert!(
            !crate::game::effects::has_member_driven_repeat_after_hydration(
                &state,
                &token_attached(TargetFilter::LastCreated)
            ),
            "reach-guard: `LastCreated` is also a context ref, so (b′) differs from (b) in \
             the predicate's own deciding leaf and in nothing else"
        );
        assert!(
            publishes_may(token_attached(TargetFilter::LastCreated), 963),
            "(b′) a blanket `refuse every ObjectCount` would be coarser than production and \
             would fail here"
        );

        // ── (c) repeated optional payment — refusal asserted, reach DISCLOSED as closed ──
        let repeated_payment = || {
            let mut a = shape_b(
                src,
                Effect::PayCost {
                    cost: AbilityCost::Mana {
                        cost: crate::types::mana::ManaCost::Cost {
                            shards: vec![],
                            generic: 1,
                        },
                    },
                    scale: None,
                    payer: TargetFilter::Controller,
                },
            );
            a.repeat_for = Some(QuantityExpr::Fixed { value: 2 });
            let mut sub = ResolvedAbility::new(
                Effect::Draw {
                    count: QuantityExpr::Fixed { value: 1 },
                    target: TargetFilter::Controller,
                },
                vec![],
                src,
                P0,
            );
            sub.condition = Some(AbilityCondition::WhenYouDo);
            a.sub_ability = Some(Box::new(sub));
            a
        };
        assert!(
            crate::game::effects::is_repeated_optional_payment(&repeated_payment()),
            "reach-guard: production's own predicate must say TRUE for arm (c)'s fixture"
        );
        assert!(
            !publishes_may(repeated_payment(), 964),
            "(c) CR 603.12a: the payment process offers its `may` PER iteration. This arm \
             asserts the mint's refusal only — `Effect::PayCost` is outside D4.3's six-arm \
             allow list, so no certifiable offer carries such an entry and NO closed hole is \
             claimed here"
        );
    }

    // ────────── 5d U4 — the `OptionalEffectChoice` arm and its two TOTAL head guards ──────────

    /// Life the shared U4 fixture's suspended optional ability gains when its CR 603.5 choice
    /// is TAKEN. Named rather than inlined so every "the pin was APPLIED" assertion below is
    /// keyed to the fixture instead of to a literal.
    const U4_MAY_LIFE: i32 = 5;

    /// A board parked on a REAL CR 603.5 resolution-time prompt. `asked` is the seat the
    /// resolver is asking, and the suspended optional ability is THAT seat's, so taking the
    /// choice gains `asked` exactly `U4_MAY_LIFE` life.
    ///
    /// The pinned source is a BATTLEFIELD object because `slot_source_prompted` asks
    /// `resolve_ability_instance`, whose zone set is {Battlefield, Command} at the pinned
    /// CR 400.7 incarnation — on a graveyard / exile / hand source it would refuse every arm
    /// below for a reason none of them is about. (A command-zone source would be admitted;
    /// the battlefield one is chosen because these rows are not about the zone at all.)
    fn u4_may_board(asked: PlayerId) -> (GameState, ObjectId) {
        use crate::types::ability::{Effect, QuantityExpr, TargetFilter};
        let mut state = GameScenario::new_n_player(3, 7).build().state().clone();
        let src = place(&mut state, 970, Zone::Battlefield);
        let mut optional = ResolvedAbility::new(
            Effect::GainLife {
                amount: QuantityExpr::Fixed { value: U4_MAY_LIFE },
                player: TargetFilter::Controller,
            },
            vec![],
            src,
            asked,
        );
        optional.optional = true;
        state.push_optional_effect_frame(crate::types::resolution::OptionalEffectFrame {
            ability: Box::new(optional),
            trigger_event: None,
            trigger_events: Vec::new(),
            trigger_match_count: None,
            return_result_occurrence: None,
        });
        state.waiting_for = WaitingFor::OptionalEffectChoice {
            player: asked,
            decision_subject_id: None,
            source_id: src,
            description: None,
            may_trigger_key: None,
            same_card_may_trigger_choice_available: false,
        };
        (state, src)
    }

    /// A template carrying exactly one CR 603.5 `MayChoice` pin for `src` (slot index 1 — the
    /// may slot in both mint shapes), declared by `owner`.
    fn u4_may_template(
        src: ObjectId,
        owner: PlayerId,
        take: crate::analysis::decision_template::MayChoiceOption,
    ) -> DecisionTemplate {
        let source = this_object(src);
        DecisionTemplate {
            owner,
            decisions: vec![PinnedDecision::MayChoice {
                slot: DecisionSlot {
                    source: source.clone(),
                    point: ChoicePoint::MayGate,
                    index: 0,
                },
                take,
            }],
            replay: ReplayMode::Scheduled {
                count: IterationCount::Fixed(1),
            },
            key: DecisionGroupKey::from_sources(&[source], DecisionKind::LoopChoice),
        }
    }

    /// A live `LoopShortcut` offer proposed by P0 on `state`, publishing the one CR 603.5
    /// `MayChoice` point [`u4_may_template`] pins.
    ///
    /// CR 732.2a: a declaration may pin only choices the offer published, so an offer exposing
    /// no point refuses a template carrying any SLOT-ADDRESSING pin — which would take the
    /// `owner` axis out of the measurement below rather than isolate it.
    fn u4_park_on_offer(state: &mut GameState, src: ObjectId) {
        use crate::analysis::decision_template::{
            DecisionPoint, DecisionPointKind, ShortcutDecisionSchema,
        };
        park_on_shortcut_offer(
            state,
            ShortcutDecisionSchema {
                points: vec![DecisionPoint {
                    slot: DecisionSlot {
                        source: this_object(src),
                        point: ChoicePoint::MayGate,
                        index: 0,
                    },
                    kind: DecisionPointKind::MayChoice,
                }],
                ..ShortcutDecisionSchema::default()
            },
        );
    }

    /// CR 732.2a + CR 603.5: a declaration whose client-supplied `template.owner` is not the
    /// engine-issued proposer is refused into the manual handback; the matched positive, differing
    /// only in `owner`, opens APNAP with the engine-bound owner.
    #[test]
    fn r28_b_the_declare_firewall_binds_the_template_owner_to_the_proposer() {
        use crate::analysis::decision_template::{IterationCount, MayChoiceOption};

        for owner in [P1, P0] {
            let (mut state, src) = u4_may_board(P0);
            u4_park_on_offer(&mut state, src);
            apply_action(
                &mut state,
                P0,
                GameAction::DeclareShortcut {
                    count: IterationCount::Fixed(1),
                    template: Some(u4_may_template(src, owner, MayChoiceOption::Take)),
                },
                None,
            )
            .expect("the declaration is dispatched either way — refusal is a HANDBACK");

            if owner == P1 {
                assert!(
                    matches!(state.waiting_for, WaitingFor::Priority { .. }),
                    "(b2) CR 732.2a + CR 603.5: a declaration whose `owner` is not \
                     the engine-issued proposer hands priority back; got {:?}",
                    state.waiting_for
                );
                assert!(
                    !matches!(state.waiting_for, WaitingFor::RespondToShortcut { .. }),
                    "(b2) no `ShortcutProposal` carrying the hostile owner may exist"
                );
            } else {
                let WaitingFor::RespondToShortcut { proposal, .. } = &state.waiting_for else {
                    panic!(
                        "(b2) matched positive: the honest declaration must open APNAP, so the \
                         refusal above is keyed to `owner` and not to this constructed offer \
                         refusing everything; got {:?}",
                        state.waiting_for
                    );
                };
                assert_eq!(
                    proposal.template.as_ref().map(|t| t.owner),
                    Some(P0),
                    "(b2) the proposal that IS built carries the engine-bound owner"
                );
            }
        }
    }

    // ── R5 — a second prompt occurrence of one class gets its OWN recorded answer ──────────
}

/// FIX-1 interruptibility (memory: combo-interruptibility-acceptance-criterion) — the Kilo loop's
/// CR 732.2a offer must FLIP off when the loop is defused. Driven from the REAL 4p dump through the
/// public `apply()` boundary (recording live), then the offer is re-derived at the private
/// `try_offer_object_growth_shortcut` seam (the plan's sanctioned private-fn revert-probe form).
#[cfg(test)]
mod kilo_interruptibility_tests {
    use super::*;
    use crate::analysis::decision_template::{PinnedDecision, TargetPin};
    use crate::types::ability::TargetRef;
    use crate::types::game_state::{ManaChoice, PayCostKind, YieldTarget};
    use crate::types::mana::ManaType;

    const P0: PlayerId = PlayerId(0);
    const KILO: ObjectId = ObjectId(402);
    const FREED: ObjectId = ObjectId(403);
    const RELIC: ObjectId = ObjectId(404);
    const PENTAD: ObjectId = ObjectId(405);
    const RELIC_TAP_MANA: usize = 1;
    const FREED_UNTAP: usize = 1;

    /// The trace-fed producer's offer at `state`'s priority window, asked every offerable span the
    /// trace names.
    fn offer_at(
        state: &GameState,
    ) -> Option<(
        crate::analysis::loop_check::LoopCertificate,
        crate::analysis::decision_template::ShortcutDecisionSchema,
        crate::game::period_confirm::ConfirmedPeriod,
    )> {
        let (_, spans) = partition_named(crate::game::play_trace::current_named(state));
        try_offer_object_growth_shortcut(&mut state.clone(), &spans)
            .map(|(parts, period)| (parts.certificate, parts.schema, period))
    }

    /// A mandatory recurrence goes to the mandatory consumer and every other cause to the
    /// recorded offers.
    #[test]
    fn each_naming_cause_reaches_exactly_one_consumer() {
        use crate::game::play_trace::{NamedSpan, NamingCause, PeriodReach, SpanSource};
        let span = |cause| NamedSpan {
            start: 0,
            end: 1,
            cause,
            source: SpanSource::Window,
            reach: PeriodReach::InStep,
        };
        let causes = [
            NamingCause::Repeat,
            NamingCause::TriggerTop,
            NamingCause::Restored,
            NamingCause::LegalNow,
            NamingCause::MandatoryRecurrence,
        ];
        let (mandatory, offerable) = partition_named(causes.map(span).to_vec());
        assert_eq!(mandatory, vec![span(NamingCause::MandatoryRecurrence)]);
        assert_eq!(
            offerable,
            causes[..4].iter().copied().map(span).collect::<Vec<_>>()
        );
    }

    fn load_migrated_dump() -> GameState {
        use crate::types::game_state::PersistedGameState;
        use std::io::Read;
        let gz: &[u8] = include_bytes!("../../tests/fixtures/kilo_freed_relic_pentad_4p.json.gz");
        let mut json = String::new();
        flate2::read::GzDecoder::new(gz)
            .read_to_string(&mut json)
            .expect("fixture inflates");
        let mut envelope: serde_json::Value = serde_json::from_str(&json).expect("envelope parses");
        // Committed pre-onset capture; onset-independent test (see record_captured_onsets).
        crate::types::game_state::record_captured_onsets(&mut envelope);
        // Route through the REAL production restore chokepoint, exactly as the integration helper
        // does. Decoding AS `PersistedGameState` (rather than decoding a bare `GameState` and
        // wrapping it) routes the dump through
        // `reject_legacy_raw_prompt_authority` + `decode_persisted_resolution_state`.
        // The test unwraps the fallible persistence boundary after asserting this fixture decodes.
        serde_json::from_value::<PersistedGameState>(envelope["gameState"].clone())
            .expect("gameState deserializes through the production decoder")
            .into_game_state()
            .expect("persisted test snapshot satisfies the checked restore contract")
    }

    fn beat_actor(state: &GameState) -> PlayerId {
        match &state.waiting_for {
            WaitingFor::Priority { player }
            | WaitingFor::PayCost { player, .. }
            | WaitingFor::ChooseManaColor { player, .. }
            | WaitingFor::ProliferateChoice { player, .. } => *player,
            WaitingFor::LoopShortcut { proposer, .. } => *proposer,
            other => panic!("unexpected beat: {other:?}"),
        }
    }

    /// Drive ONE full live cycle via the public boundary, recording the pinned period; the state,
    /// actor and action of the beat whose `apply` made an offer, if one did.
    fn drive_one_live_cycle(state: &mut GameState) -> Option<(GameState, PlayerId, GameAction)> {
        let mut beat = (
            P0,
            GameAction::ActivateAbility {
                source_id: RELIC,
                ability_index: RELIC_TAP_MANA,
                payment_mode: crate::types::game_state::CastPaymentMode::Auto,
            },
        );
        let mut freed_activated = false;
        for _ in 0..200 {
            let before = state.clone();
            apply(state, beat.0, beat.1.clone())
                .unwrap_or_else(|error| panic!("{:?}: {error:?}", beat.1));
            if matches!(state.waiting_for, WaitingFor::LoopShortcut { .. }) {
                return Some((before, beat.0, beat.1));
            }
            let actor = beat_actor(state);
            beat = match state.waiting_for.clone() {
                WaitingFor::PayCost {
                    kind: PayCostKind::TapCreatures { .. },
                    ..
                } => (actor, GameAction::SelectCards { cards: vec![KILO] }),
                WaitingFor::ChooseManaColor { .. } => (
                    actor,
                    GameAction::ChooseManaColor {
                        choice: ManaChoice::SingleColor(ManaType::Blue),
                        count: 1,
                    },
                ),
                WaitingFor::ProliferateChoice { .. } => (
                    actor,
                    GameAction::SelectTargets {
                        targets: vec![TargetRef::Object(PENTAD)],
                    },
                ),
                WaitingFor::Priority { .. } if !state.stack.is_empty() => {
                    (actor, GameAction::PassPriority)
                }
                WaitingFor::Priority { .. } if freed_activated => return None,
                WaitingFor::Priority { .. } => {
                    freed_activated = true;
                    (
                        P0,
                        GameAction::ActivateAbility {
                            source_id: FREED,
                            ability_index: FREED_UNTAP,
                            payment_mode: crate::types::game_state::CastPaymentMode::Auto,
                        },
                    )
                }
                other => panic!("unexpected beat: {other:?}"),
            };
        }
        panic!("drive did not settle");
    }

    /// CR 732.2a: the first cycle's offer, re-probed at its own window, is latched; declining it
    /// discards P0's plays, so a second live cycle is a fresh detection. Returns the second cycle's
    /// offering beat.
    fn redriven_offer_beat() -> (GameState, PlayerId, GameAction) {
        use crate::game::play_trace::{offer_latched, play_trace_view, WindowKey};
        let mut driven = load_migrated_dump();
        drive_one_live_cycle(&mut driven).expect("the first cycle is offered");
        let reprobe = at_priority_window(driven.clone());
        let offered = play_trace_view(&reprobe)
            .and_then(|view| view.offered)
            .expect("the offered span");
        assert_eq!(WindowKey::of(&reprobe), WindowKey::of(&driven));
        assert!(offer_latched(&reprobe, offered));
        assert!(offer_at(&reprobe).is_none(), "the same window is latched");
        apply(&mut driven, P0, GameAction::DeclineShortcut).expect("decline the offer");
        drive_one_live_cycle(&mut driven).expect("the second cycle is offered")
    }

    /// The beat's outcome: whether applying `action` to `before` offers the loop.
    fn offers_after(mut before: GameState, actor: PlayerId, action: GameAction) -> bool {
        apply(&mut before, actor, action).expect("the offering beat applies");
        matches!(before.waiting_for, WaitingFor::LoopShortcut { .. })
    }

    /// Matched pair at the second cycle's offering beat, Kilo untapped in both as the Freed untap
    /// resolving there leaves it: intact, the loop is offered; with Freed removed, the confirmer
    /// cannot replay the recorded Freed activation, so nothing is offered.
    #[test]
    fn freed_removed_defuses_the_offer() {
        let (mut before, actor, beat) = redriven_offer_beat();
        before.objects.get_mut(&KILO).expect("Kilo").tapped = false;
        assert!(
            offers_after(before.clone(), actor, beat.clone()),
            "undefused: the intact loop re-derives the CR 732.2a offer"
        );
        let mut defused = before;
        defused.objects.remove(&FREED);
        defused.battlefield.retain(|id| *id != FREED);
        apply(&mut defused, actor, beat).expect("the offering beat applies");
        assert!(
            !defused.objects[&KILO].tapped,
            "reach: the defused board is at its loop state"
        );
        assert!(
            !matches!(defused.waiting_for, WaitingFor::LoopShortcut { .. }),
            "defused (Freed removed): the re-drive aborts ⇒ NO offer — the outcome flips"
        );
    }

    /// Reset a driven state (which settles at `LoopShortcut`) back to the empty-stack priority
    /// window the offer re-derives from, so `try_offer_object_growth_shortcut` can be probed
    /// directly (the plan's sanctioned private-fn revert-probe form). The board is the valid
    /// post-cycle loop state (Kilo untapped, mana-neutral).
    fn at_priority_window(mut state: GameState) -> GameState {
        state.waiting_for = WaitingFor::Priority { player: P0 };
        assert!(
            state.stack.is_empty(),
            "the driven cycle settled to an empty stack"
        );
        state
    }

    /// [LOW-1] declined-axis ∞ lifecycle — characterization/regression guard (memory:
    /// combo-interruptibility-acceptance-criterion). A declined `Counters`/`Life` axis leaves its
    /// ∞ capability marker in `unbounded_resources` intentionally (CR 732.2b never forces a
    /// shortcut). This test guards the MEASURED retirement path (a) documented at the boundary
    /// seam: the empty-stack offer hook `try_offer_object_growth_shortcut` is NOT
    /// gated by existing ∞ marks, so a later genuine re-detection RE-OFFERS the loop and can
    /// re-collapse the declined axis once the observer is gone.
    ///
    /// DISCRIMINATING LEG (the re-offer assertion): with a pre-existing declined ∞ mark injected
    /// for P0, the offer STILL fires. If a future regression ∞-gated the offer hook (e.g. to
    /// suppress re-offering a declined axis), this flips to `None`. Positive control / reach-guard:
    /// the SAME state WITHOUT the mark also offers (proving the mark is what the assertion
    /// isolates).
    #[test]
    fn declined_infinity_mark_does_not_suppress_reoffer() {
        use crate::analysis::resource::ResourceAxis;

        let (before, actor, beat) = redriven_offer_beat();
        assert!(
            !before.unbounded_resources.contains_key(&P0),
            "reach-guard: the unmarked beat carries no ∞ mark"
        );
        // Positive control: without any ∞ mark the intact loop re-derives the offer.
        assert!(
            offers_after(before.clone(), actor, beat.clone()),
            "positive control: the intact loop offers when no ∞ mark is present"
        );

        // Inject a pre-existing DECLINED ∞ axis for P0 (as if an earlier boundary declined the life
        // axis and left it ∞-marked for manual play). The offer hook never reads
        // `unbounded_resources`, so the mark must NOT suppress the re-offer.
        let mut marked = before;
        marked.mark_unbounded_loop(P0, &[ResourceAxis::Life(P0)], &[ResourceAxis::Life(P0)]);
        assert!(
            marked
                .unbounded_resources
                .get(&P0)
                .is_some_and(|axes| axes.contains(&ResourceAxis::Life(P0))),
            "reach-guard: the declined ∞ Life mark is present on the probed state"
        );
        assert!(
            offers_after(marked, actor, beat),
            "the empty-stack offer hook is NOT ∞-gated: a persisted declined ∞ axis does not \
             suppress a genuine re-detection re-offering the loop (CR 732.2a / CR 732.2b)"
        );
    }

    /// Plant ONE extra `Targets` pin into the recorded period's first step, on a slot that
    /// no prompt in the replay answers. That is what makes these three rows isolate the
    /// OFFER-BUILDER: the drive never consults the planted pin, while
    /// `pinned_decisions_to_points` always does.
    fn plant_offer_pin(
        state: &GameState,
        pin: TargetPin,
    ) -> Option<Vec<crate::analysis::decision_template::DecisionPoint>> {
        let pins = [PinnedDecision::Targets {
            slot: crate::analysis::decision_template::DecisionSlot {
                source: YieldTarget::ThisObject {
                    source_id: KILO,
                    incarnation: None,
                    trigger_description: None,
                },
                // An index no live prompt publishes, so only the point-builder reads it.
                point: crate::analysis::decision_template::ChoicePoint::AnnouncedTarget,
                index: 99,
            },
            targets: vec![pin],
        }];
        pinned_decisions_to_points(&pins, state, P0)
    }

    /// R4b — CR 732.2a: *"a sequence of game choices ... that may be legally taken based on
    /// the current game state"*. If a pinned target no longer resolves, there IS no such
    /// sequence, so the offer must be WITHDRAWN — not published with a short legal set.
    ///
    /// Before the fix, `pinned_decisions_to_points` `filter_map`ped the unresolvable pin out
    /// of `legal_targets` while keeping `min_targets = targets.len()`, publishing a point
    /// that no legal declaration could satisfy: the player is offered a shortcut they cannot
    /// take, and the failure surfaces later as `IllegalPinValue` instead of as "no offer".
    ///
    /// MATCHED PAIR on one board, one variable — the planted pin's identity:
    ///   * live object  ⇒ the point resolves ⇒ the offer FIRES (the reach-guard: it proves
    ///     the plant itself does not break the drive, so the negative arm's `None` is the
    ///     withdrawal and not a broken fixture);
    ///   * absent object ⇒ the offer is WITHDRAWN.
    ///
    /// REVERT-PROBE: restore the `filter_map` (drop the `?`) ⇒ the negative arm publishes an
    /// undeclarable point instead of withdrawing ⇒ FAILS. Reachable TODAY and independent of
    /// item 1: this arm's pin is `ByIdentity`, and no player legality is involved.
    #[test]
    fn an_unresolvable_identity_pin_withdraws_the_offer() {
        let mut driven = load_migrated_dump();
        drive_one_live_cycle(&mut driven);
        let base = at_priority_window(driven);

        let live = plant_offer_pin(
            &base,
            TargetPin::ByIdentity(YieldTarget::ThisObject {
                source_id: KILO,
                incarnation: None,
                trigger_description: None,
            }),
        );
        assert!(
            live.is_some(),
            "reach-guard: a planted pin that RESOLVES leaves the offer intact, so the \
             negative arm below is the withdrawal and not the plant"
        );

        assert!(
            !base.objects.contains_key(&ObjectId(999_999)),
            "setup: the planted identity must genuinely be absent from the board"
        );
        let dangling = plant_offer_pin(
            &base,
            TargetPin::ByIdentity(YieldTarget::ThisObject {
                source_id: ObjectId(999_999),
                incarnation: None,
                trigger_description: None,
            }),
        );
        assert!(
            dangling.is_none(),
            "CR 732.2a: a pin that cannot resolve withdraws the offer"
        );
    }

    /// R4d — the same withdrawal, on the OTHER end of the invariant: a `TargetPin::Player`
    /// aimed at a seat that has left the game (CR 800.4 + CR 102.1) no longer resolves, so
    /// the offer is withdrawn rather than ratifying its own pin.
    ///
    /// This is the offer-builder half of the pair whose MINT half is
    /// `effects::proliferate`'s R4a row: the two ends of the invariant that a Player pin
    /// must never reach materialization validated only against a legal set derived from the
    /// pins themselves. `pinned_decisions_to_points` derives its legal sets FROM the pins,
    /// so on this route the seat's existence check inside `resolve_target` is the only
    /// authority there is.
    ///
    /// MATCHED PAIR, one variable (`is_eliminated`): live seat ⇒ offer fires; departed seat
    /// ⇒ offer withdrawn. REVERT-PROBE: drop the existence conjunct in
    /// `players::player_exists_for_choice` ⇒ the departed seat resolves ⇒ the offer is
    /// published ⇒ FAILS.
    #[test]
    fn a_departed_player_pin_withdraws_the_offer() {
        let mut driven = load_migrated_dump();
        drive_one_live_cycle(&mut driven);
        let base = at_priority_window(driven);
        let victim = PlayerId(1);

        assert!(
            !base.players[1].is_eliminated,
            "reach-guard: the seat starts in the game"
        );
        assert!(
            plant_offer_pin(&base, TargetPin::Player(victim)).is_some(),
            "reach-guard: a Player pin on a LIVE seat leaves the offer intact"
        );
        let mut departed = base.clone();
        departed.players[1].is_eliminated = true;
        assert!(
            plant_offer_pin(&departed, TargetPin::Player(victim)).is_none(),
            "a Player pin aimed at a departed seat withdraws the offer (CR 732.2a)"
        );
    }

    /// R2b — the CR 115.10a boundary, enforced at the OFFER level rather than explained in a
    /// comment. A shrouded seat (CR 702.18a) is un-TARGETable, and this row proves the
    /// offer-builder still publishes it as a CHOICE: the point carries it in
    /// `legal_targets`, and the offer FIRES.
    ///
    /// This is the enforcement half of the pair whose explanation half is the site-4 comment
    /// and whose seam-level half is
    /// `analysis::decision_template::tests::a_shrouded_seat_is_untargetable_yet_still_
    /// choosable_at_the_pin_recheck`. Without it, re-introducing target-scoped conjuncts at
    /// site 4 would silently restore the over-veto at the one seam that publishes an offer.
    ///
    /// REVERT-PROBE: route `resolve_target`'s `TargetPin::Player` arm through
    /// `targeting::player_is_legal_target` ⇒ the shrouded seat stops resolving ⇒ the offer is
    /// WITHDRAWN ⇒ both assertions FAIL. The paired positive that keeps this from passing on
    /// an un-shrouded board is the shroud reach-guard asserted first.
    #[test]
    fn a_shrouded_player_pin_is_still_published_by_the_offer_builder() {
        use crate::types::statics::StaticMode;

        let mut driven = load_migrated_dump();
        drive_one_live_cycle(&mut driven);
        let mut base = at_priority_window(driven);
        let victim = PlayerId(1);

        // P1 gains shroud, through the single TCE construction authority — the same route
        // a resolved "target player gains shroud until end of turn" effect takes.
        base.add_transient_continuous_effect(
            KILO,
            P0,
            crate::types::ability::Duration::UntilEndOfTurn,
            crate::types::ability::TargetFilter::SpecificPlayer { id: victim },
            vec![
                crate::types::ability::ContinuousModification::AddStaticMode {
                    mode: StaticMode::Shroud,
                },
            ],
            None,
        );
        crate::game::layers::flush_layers(&mut base);

        // Reach-guard, and the paired positive: the shroud actually bites at the TARGET
        // seam. Without this the row would pass on a board with no shroud at all.
        assert!(
            crate::game::static_abilities::player_cannot_be_targeted_by(&base, victim, KILO, P0),
            "CR 702.18a: the planted shroud must make the seat un-targetable"
        );

        let points = plant_offer_pin(&base, TargetPin::Player(victim))
            .expect("CR 115.10a: a shrouded seat is still CHOOSABLE, so the offer fires");
        assert!(
            points.iter().any(|point| matches!(
                &point.kind,
                crate::analysis::decision_template::DecisionPointKind::Targets { legal_targets, .. }
                    if legal_targets.contains(&TargetRef::Player(victim))
            )),
            "the published point carries the shrouded seat: exclusion belongs to the TARGET \
             seam, not to this one"
        );
    }
}

/// Census rows for the CR 603.5 conjunct set.
#[cfg(test)]
mod bounded_offer_conjunct_tests {
    /// F2c — **NO FOURTH COPY OF THE CR 603.5 CONJUNCT SET IS BUILT OUT OF THESE FIVE
    /// PREDICATES, AND EVERY SURVIVING PRODUCTION CALLER IS INSIDE `game/effects/`.**
    ///
    /// CR 603.5 + CR 608.2c + CR 608.2d + CR 603.12a. Three places used to answer *"does this
    /// ability open ONE up-front optional gate?"* — production's own branch, the mint's guard
    /// (b), and `analysis::resource::auto_may_answer_for` — and the latter two omitted
    /// conjuncts the first has. After adoption, `effects::upfront_optional_gate` is the only
    /// place the set is assembled, and the census is what keeps it that way.
    ///
    /// MEASURED counts, not derived ones. The plan's derivation predicted `2 / 2 / 2 / 1 / 2`
    /// and the tree measures `2 / 2 / 2 / 1 / 2`; if these ever disagree the MEASURED value is
    /// what belongs here.
    ///
    /// | predicate | production sites | where |
    /// |---|---|---|
    /// | `has_kind_driven_repeat` | 2 | `upfront_optional_gate` + `repeat_for_outermost_with_scope_or_unless` |
    /// | `has_member_driven_repeat_after_hydration` | 2 | `upfront_optional_gate` + `resolve_chain_body`'s driver guard |
    /// | `is_repeated_optional_payment` | 2 | `upfront_optional_gate` + `resolve_chain_body`'s driver dispatch |
    /// | `optional_prompt_player` | 2 | `upfront_optional_gate` + `offer_repeated_payment` (names who is asked each CR 603.12a payment offer; opens no up-front window) |
    /// | `optional_effect_is_infeasible` | 2 | `upfront_optional_gate` + `resolve_chain_body`'s `CastFromZone` decline |
    ///
    /// **THE NON-AUTHORITY SITES ARE NOT COPIES, AND FOLDING THEM IN WOULD BE WRONG.**
    /// They consume these predicates to decide WHICH DRIVER RUNS — whether a counted repeat
    /// has to wrap scoped/unless-pay instructions (CR 608.2c), which repeat driver takes the
    /// ability, and the CR 603.12a repeated-payment dispatch that fires *because* the up-front
    /// gate suppressed itself. That is a different question from "does one up-front window
    /// open", and it is asked after the gate has already declined.
    ///
    /// **HONEST GUARANTEE.** This enforces that no fourth copy is built OUT OF THESE FIVE
    /// PREDICATES. A copy that re-derives the same conjunct from `ability.repeat_for` (or from
    /// `optional_for`, or from the effect discriminant) inline is NOT caught, and no census
    /// over these five tokens can catch it — `has_kind_driven_repeat` is itself exactly such a
    /// re-derivation.
    ///
    /// The zero-outside-`game/effects/` assertion carries its own POSITIVE CONTROL, because a
    /// zero census with a dead instrument is indistinguishable from a passing one.
    ///
    /// REVERT-PROBE: re-introduce any one predicate call in `analysis/resource.rs` or in
    /// `entry_publishes_pin_slots` ⇒ that predicate's count rises AND the outside-set becomes
    /// non-empty ⇒ FLIPS on two independent assertions.
    #[test]
    fn f2c_the_cr_603_5_conjunct_set_has_one_production_assembler() {
        /// Every `.rs` under the crate's `src`. A whole file whose stem ends `_tests` is
        /// test-only (its parent declares it under `#[cfg(test)]`).
        fn rs_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("readable source dir") {
                let path = entry.expect("readable dir entry").path();
                if path.is_dir() {
                    rs_files(&path, out);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    out.push(path);
                }
            }
        }
        /// The `#[cfg(test)]`-attributed column-0 `mod … {` … column-0 `}` spans, so the
        /// census cannot count its own harness. Same shape as the CR 603.5 prompt census.
        fn cfg_test_spans(lines: &[&str]) -> Vec<(usize, usize)> {
            let mut spans = Vec::new();
            let mut i = 0;
            while i < lines.len() {
                if lines[i].trim() == "#[cfg(test)]" {
                    let mut j = i + 1;
                    while j < lines.len()
                        && (lines[j].trim_start().starts_with("#[") || lines[j].trim().is_empty())
                    {
                        j += 1;
                    }
                    let is_mod = j < lines.len()
                        && lines[j].starts_with(['m', 'p'])
                        && lines[j].contains("mod ")
                        && lines[j].trim_end().ends_with('{');
                    if is_mod {
                        let mut k = j + 1;
                        while k < lines.len() && lines[k] != "}" {
                            k += 1;
                        }
                        spans.push((j, k));
                        i = k;
                    }
                }
                i += 1;
            }
            spans
        }

        // ASSEMBLED needles, so this row's own source cannot be counted by its own instrument.
        let predicates: [(String, usize); 5] = [
            (format!("has_kind_driven{}repeat(", '_'), 2),
            (
                format!("has_member_driven_repeat_after{}hydration(", '_'),
                3,
            ),
            (format!("is_repeated_optional{}payment(", '_'), 2),
            (format!("optional_prompt{}player(", '_'), 2),
            (format!("optional_effect_is{}infeasible(", '_'), 2),
        ];

        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = Vec::new();
        rs_files(&root, &mut files);
        files.sort();
        assert!(files.len() > 100, "reach-guard: the walker found the crate");

        let mut sites: Vec<(usize, String)> = Vec::new();
        let mut control_hits = 0usize;
        for path in &files {
            let text = std::fs::read_to_string(path).expect("readable source file");
            let lines: Vec<&str> = text.lines().collect();
            let spans = cfg_test_spans(&lines);
            let rel = path
                .strip_prefix(&root)
                .expect("under src")
                .display()
                .to_string()
                // Canonicalize to forward slashes so the census pins below are
                // platform-independent: `Path::display()` emits the OS-native
                // separator (backslash on Windows), but the pins are written in
                // the crate's forward-slash convention. No-op on Unix/CI.
                .replace('\\', "/");
            let test_file = rel.trim_end_matches(".rs").ends_with("_tests");
            for (n, line) in lines.iter().enumerate() {
                // The shared comment rule, not a private one: comment text declares no
                // predicate and calls none.
                let line = crate::source_census::code(line);
                if test_file || spans.iter().any(|(a, b)| (*a..=*b).contains(&n)) {
                    continue;
                }
                // POSITIVE CONTROL for the zero census below: a token that IS present in
                // production, counted by this very walker under this very filter.
                if line.contains("fn resolve_chain_body(") {
                    control_hits += 1;
                }
                for (i, (needle, _)) in predicates.iter().enumerate() {
                    // The DEFINITION is not a call site.
                    if line.contains(needle) && !line.contains(&format!("fn {needle}")) {
                        sites.push((i, format!("{rel}:{}", n + 1)));
                    }
                }
            }
        }

        assert_eq!(
            control_hits, 1,
            "POSITIVE CONTROL: the walker+filter must find `fn resolve_chain_body(` exactly \
             once in production source. A zero below is only meaningful with a live instrument"
        );

        let counted: Vec<(String, usize)> = predicates
            .iter()
            .enumerate()
            .map(|(i, (needle, _))| {
                (
                    needle.clone(),
                    sites.iter().filter(|(j, _)| *j == i).count(),
                )
            })
            .collect();
        let expected: Vec<(String, usize)> = predicates
            .iter()
            .map(|(needle, want)| (needle.clone(), *want))
            .collect();
        assert_eq!(
            counted, expected,
            "the CR 603.5 conjunct set gained or lost a production consumer. The surviving \
             non-authority sites are `repeat_for_outermost_with_scope_or_unless` (does a \
             counted repeat wrap scoped/unless-pay instructions), `resolve_chain_body`'s \
             repeat-driver guard, its per-member unless-payment gate, and its CR 603.12a \
             driver dispatch, and \
             `resolve_chain_body`'s `CastFromZone` decline probe — every one of them selects a \
             DRIVER rather than opening an up-front window — plus `offer_repeated_payment`, \
             which only names who is asked a driver's per-iteration offer, so a NEW site is a \
             decision to adjudicate here and not a number to move.\nsites={sites:#?}"
        );

        let outside: Vec<&String> = sites
            .iter()
            .filter(|(_, site)| !site.starts_with("game/effects/"))
            .map(|(_, site)| site)
            .collect();
        assert!(
            outside.is_empty(),
            "SINGLE ASSEMBLER: every production consumer of these five predicates lives in \
             `game/effects/`, next to the authority that assembles them. A caller in another \
             module is by construction re-deriving the gate's conjunct set from outside it — \
             which is exactly what `analysis::resource::auto_may_answer_for` and \
             `engine::entry_publishes_pin_slots` used to do, each with a DIFFERENT omission. \
             Found {outside:#?}"
        );
    }
}

/// Separation of the settle gate's two questions: *has this resolution
/// finished?* (readiness, `resolving_stack_entry_can_settle`) and *is the
/// carrier well-formed?* (`resolving_carrier_parity_is_coherent`).
///
/// These live inline because `resolving_trigger_firing` is `pub(crate)` and
/// both settle wrappers are `pub(super)`, so no external test crate can reach
/// the surface under test.
#[cfg(test)]
mod resolving_carrier_settle_tests {
    use super::{
        apply, resolving_carrier_parity_is_coherent, resolving_stack_entry_can_settle,
        settle_resolving_stack_entry_after_continuation_resume,
        take_transition_deferred_probe_for_test,
    };
    use crate::game::zones::create_object;
    use crate::types::ability::{Effect, QuantityExpr, ResolvedAbility, TargetFilter};
    use crate::types::actions::GameAction;
    use crate::types::events::GameEvent;
    use crate::types::game_state::{
        GameState, InsertedPhaseResume, PendingContinuation, StackEntry, StackEntryKind, WaitingFor,
    };
    use crate::types::identifiers::{CardId, ExtraPhaseId, ObjectId, TriggerFiring};
    use crate::types::phase::{Phase, PhaseGroup, TurnSegment};
    use crate::types::player::PlayerId;
    use crate::types::zones::Zone;

    const SOURCE: ObjectId = ObjectId(60);

    fn trivial_ability() -> Box<ResolvedAbility> {
        Box::new(ResolvedAbility::new(
            Effect::TargetOnly {
                target: TargetFilter::Any,
            },
            vec![],
            SOURCE,
            PlayerId(0),
        ))
    }

    fn carrier(kind: StackEntryKind) -> StackEntry {
        StackEntry {
            id: ObjectId(500),
            source_id: SOURCE,
            controller: PlayerId(0),
            kind,
        }
    }

    fn triggered_kind() -> StackEntryKind {
        StackEntryKind::TriggeredAbility {
            source_id: SOURCE,
            ability: trivial_ability(),
            condition: None,
            trigger_event: None,
            description: None,
            source_name: "Test Trigger".to_string(),
            subject_match_count: None,
            die_result: None,
            provenance: None,
        }
    }

    fn activated_kind() -> StackEntryKind {
        StackEntryKind::ActivatedAbility {
            source_id: SOURCE,
            ability: trivial_ability(),
        }
    }

    /// A state at a priority boundary with every resolution hold clear.
    fn settled_priority_state() -> GameState {
        let mut state = GameState::new_two_player(42);
        state.waiting_for = WaitingFor::Priority {
            player: PlayerId(0),
        };
        state
    }

    /// Test 1 (discriminating). A triggered carrier whose firing classification
    /// is absent is malformed, but its resolution is nonetheless finished. The
    /// sweep must be able to do its job on that input; while the readiness gate
    /// also tested well-formedness, this input read as "not finished" and the
    /// wrapper no-opped.
    #[test]
    fn a_triggered_carrier_missing_its_firing_still_settles_at_the_priority_boundary() {
        let mut state = settled_priority_state();
        state.resolving_stack_entry = Some(carrier(triggered_kind()));
        state.resolving_trigger_firing = None;

        // Fixture guard: this is the desynchronized shape, not a well-formed one.
        assert!(
            !resolving_carrier_parity_is_coherent(&state),
            "fixture must actually be the incoherent pairing under test"
        );

        settle_resolving_stack_entry_after_continuation_resume(&mut state);

        assert!(
            state.resolving_stack_entry.is_none(),
            "a finished resolution's carrier must settle even when its firing \
             classification is absent"
        );
        assert!(
            state.resolving_trigger_firing.is_none(),
            "settling clears both halves of the carrier"
        );
    }

    /// Test 2 (non-vacuity). Removing the well-formedness conjunct must not
    /// have weakened readiness: a carrier whose resolution is still suspended
    /// stays put, for the well-formed and malformed pairing alike.
    ///
    /// Scope of the pin, stated precisely: `park_ability_continuation` also
    /// pushes onto `resolution_stack`, which `resolution_completion_can_settle`
    /// rejects independently. So this fixture falsifies TWO readiness conjuncts
    /// at once and does not hold either one down on its own — deleting only the
    /// `active_ability_continuation()` conjunct would leave it green. It pins
    /// what the change needs pinned (readiness survived, and A1 did not make
    /// settling unconditional); it is not a single-conjunct probe, and the name
    /// says "suspended" rather than naming a conjunct for that reason.
    #[test]
    fn a_suspended_resolution_still_blocks_settling_for_either_pairing() {
        for firing in [Some(TriggerFiring::Ordinary), None] {
            let mut state = settled_priority_state();
            state.resolving_stack_entry = Some(carrier(triggered_kind()));
            state.resolving_trigger_firing = firing;
            let pending = PendingContinuation::new(trivial_ability(), &state);
            state.park_ability_continuation(pending);

            // Probe guard: the suspension the fixture claims is actually installed.
            assert!(
                state.active_ability_continuation().is_some(),
                "fixture must actually park a live continuation ({firing:?})"
            );
            assert!(
                !resolving_stack_entry_can_settle(&state),
                "a suspended resolution is not finished ({firing:?})"
            );

            settle_resolving_stack_entry_after_continuation_resume(&mut state);

            assert!(
                state.resolving_stack_entry.is_some(),
                "an unfinished resolution's carrier must survive the sweep ({firing:?})"
            );
        }
    }

    /// Test 3 (non-vacuity). The leading conjunct is intact: with no carrier
    /// there is nothing to settle, even if a stray firing classification is
    /// present.
    #[test]
    fn no_carrier_means_nothing_to_settle() {
        let mut state = settled_priority_state();
        assert!(state.resolving_stack_entry.is_none());
        assert!(
            !resolving_stack_entry_can_settle(&state),
            "an absent carrier is not a settleable one"
        );

        state.resolving_trigger_firing = Some(TriggerFiring::Ordinary);
        assert!(
            !resolving_stack_entry_can_settle(&state),
            "a stray firing classification does not conjure a carrier to settle"
        );
    }

    /// Test 4. Direct coverage of the extracted well-formedness predicate
    /// across every carrier/firing pairing.
    #[test]
    fn parity_predicate_classifies_every_carrier_pairing() {
        let cases = [
            (Some(triggered_kind()), Some(TriggerFiring::Ordinary), true),
            (Some(triggered_kind()), None, false),
            (Some(activated_kind()), None, true),
            (Some(activated_kind()), Some(TriggerFiring::Ordinary), false),
            (None, None, true),
            (None, Some(TriggerFiring::Ordinary), false),
        ];

        for (kind, firing, expected) in cases {
            let mut state = settled_priority_state();
            let described = format!("{kind:?} paired with {firing:?}");
            state.resolving_stack_entry = kind.map(carrier);
            state.resolving_trigger_firing = firing;

            assert_eq!(
                resolving_carrier_parity_is_coherent(&state),
                expected,
                "{described}"
            );
        }
    }

    /// Production-path regression for the #9194 shape: a triggered ability has
    /// already popped from the stack, its next two instructions are parked as
    /// a continuation, and the final Cleanup pass must drain both instructions
    /// before the turn interpreter is allowed to call `start_next_turn`.
    #[test]
    fn cleanup_priority_pass_drains_triggered_multistep_carrier_before_turn_wrap() {
        let mut state = GameState::new_two_player(0x9194);
        state.phase = Phase::Cleanup;
        state.active_player = PlayerId(0);
        state.priority_player = PlayerId(0);
        state.waiting_for = WaitingFor::Priority {
            player: PlayerId(0),
        };
        state.priority_passes.insert(PlayerId(1));
        state.priority_pass_count = 1;

        state.resolving_stack_entry = Some(carrier(triggered_kind()));
        state.resolving_trigger_firing = Some(TriggerFiring::Ordinary);

        let gain_life = |amount| {
            ResolvedAbility::new(
                Effect::GainLife {
                    amount: QuantityExpr::Fixed { value: amount },
                    player: TargetFilter::Controller,
                },
                vec![],
                SOURCE,
                PlayerId(0),
            )
        };
        let chain = gain_life(1).sub_ability(gain_life(1));
        state.park_ability_continuation(PendingContinuation::new(Box::new(chain), &state));

        let starting_turn = state.turn_number;
        let starting_life = state.players[0].life;
        let _ = take_transition_deferred_probe_for_test();
        let result = apply(&mut state, PlayerId(0), GameAction::PassPriority)
            .expect("the final Cleanup pass must settle the continuation");

        assert!(
            take_transition_deferred_probe_for_test(),
            "the production priority pipeline must observe Cleanup deferral before retrying the boundary"
        );
        assert_eq!(state.turn_number, starting_turn + 1);
        assert_eq!(state.active_player, PlayerId(1));
        assert!(matches!(state.phase, Phase::Untap | Phase::Upkeep));
        assert_eq!(state.players[0].life, starting_life + 2);
        assert!(state.stack.is_empty());
        assert!(state.resolution_stack.is_empty());
        assert!(state.resolving_stack_entry.is_none());
        assert!(state.resolving_trigger_firing.is_none());
        assert_eq!(
            result
                .events
                .iter()
                .filter(|event| matches!(event, GameEvent::TurnStarted { .. }))
                .count(),
            1,
            "the settled continuation must cross exactly one turn boundary"
        );
    }

    /// CR 514.3a: when every player passes on an empty stack in the cleanup
    /// step, "another cleanup step begins". If a live carrier defers that pass,
    /// the pipeline's retry runs the new cleanup step, so the retry counts it.
    /// Nine cards in hand make the retried step stop at its discard prompt
    /// (CR 514.1), before the turn wrap would clear the tally.
    #[test]
    fn deferred_cleanup_retry_counts_the_cleanup_step_it_begins() {
        let mut state = GameState::new_two_player(0x9194);
        state.phase = Phase::Cleanup;
        state.active_player = PlayerId(0);
        state.priority_player = PlayerId(0);
        state.waiting_for = WaitingFor::Priority {
            player: PlayerId(0),
        };
        state.priority_passes.insert(PlayerId(1));
        state.priority_pass_count = 1;
        for i in 0..9 {
            create_object(
                &mut state,
                CardId(900 + i),
                PlayerId(0),
                format!("Card {i}"),
                Zone::Hand,
            );
        }
        state.resolving_stack_entry = Some(carrier(triggered_kind()));
        state.resolving_trigger_firing = Some(TriggerFiring::Ordinary);
        let gain_life = ResolvedAbility::new(
            Effect::GainLife {
                amount: QuantityExpr::Fixed { value: 1 },
                player: TargetFilter::Controller,
            },
            vec![],
            SOURCE,
            PlayerId(0),
        );
        state.park_ability_continuation(PendingContinuation::new(Box::new(gain_life), &state));
        let starting_turn = state.turn_number;

        let _ = take_transition_deferred_probe_for_test();
        apply(&mut state, PlayerId(0), GameAction::PassPriority)
            .expect("the final Cleanup pass must settle the continuation");

        assert!(
            take_transition_deferred_probe_for_test(),
            "reach guard: the pass must take the deferred-Cleanup retry"
        );
        assert_eq!(state.turn_number, starting_turn);
        assert_eq!(state.phase, Phase::Cleanup);
        assert!(matches!(
            state.waiting_for,
            WaitingFor::DiscardToHandSize {
                player: PlayerId(0),
                ..
            }
        ));
        assert_eq!(state.steps_started_this_turn.count(Phase::Cleanup), 1);
    }

    /// CR 500.1 + CR 500.8 + CR 117.4: the end of combat step of a combat added
    /// after the cleanup step is the turn's last step, so the final pass there
    /// crosses the turn boundary. A live carrier defers that crossing; the
    /// pipeline drains the continuation, then retries leaving the step without
    /// beginning it again.
    #[test]
    fn final_pass_in_a_unit_added_after_cleanup_drains_the_carrier_before_turn_wrap() {
        let mut state = GameState::new_two_player(0x9332);
        state.phase = Phase::EndCombat;
        state.extra_phase_resume = vec![InsertedPhaseResume {
            anchor: Phase::Cleanup,
            segment: TurnSegment::Phase(PhaseGroup::Combat),
            entry: ExtraPhaseId::default(),
        }];
        state.active_player = PlayerId(0);
        state.priority_player = PlayerId(0);
        state.waiting_for = WaitingFor::Priority {
            player: PlayerId(0),
        };
        state.priority_passes.insert(PlayerId(1));
        state.priority_pass_count = 1;

        state.resolving_stack_entry = Some(carrier(triggered_kind()));
        state.resolving_trigger_firing = Some(TriggerFiring::Ordinary);
        let gain_life = |amount| {
            ResolvedAbility::new(
                Effect::GainLife {
                    amount: QuantityExpr::Fixed { value: amount },
                    player: TargetFilter::Controller,
                },
                vec![],
                SOURCE,
                PlayerId(0),
            )
        };
        let chain = gain_life(1).sub_ability(gain_life(1));
        state.park_ability_continuation(PendingContinuation::new(Box::new(chain), &state));

        let starting_turn = state.turn_number;
        let starting_life = state.players[0].life;
        let _ = take_transition_deferred_probe_for_test();
        let result = apply(&mut state, PlayerId(0), GameAction::PassPriority)
            .expect("the final pass must settle the continuation");

        assert!(
            take_transition_deferred_probe_for_test(),
            "reach guard: the pass must defer the turn boundary before retrying it"
        );
        assert_eq!(state.turn_number, starting_turn + 1);
        assert_eq!(state.active_player, PlayerId(1));
        assert_eq!(state.players[0].life, starting_life + 2);
        assert!(state.resolving_stack_entry.is_none());
        assert!(state.extra_phase_resume.is_empty());
        assert!(matches!(state.phase, Phase::Untap | Phase::Upkeep));
        assert_eq!(
            result
                .events
                .iter()
                .filter(|event| matches!(event, GameEvent::TurnStarted { .. }))
                .count(),
            1,
            "the settled continuation must cross exactly one turn boundary"
        );
    }

    /// CR 608.2n + CR 514.3a: a sorcery whose paused instructions are done
    /// still owes its final part when a transition deferred at the cleanup
    /// step is settled. The final part runs there and its own move triggers
    /// ("Whenever a card is put into your graveyard from anywhere"); the retry
    /// reaches the cleanup step's actions, whose tail puts that trigger on the
    /// stack and gives the active player priority, so the turn does not end.
    #[test]
    fn a_deferred_cleanup_transition_puts_the_final_parts_trigger_on_the_stack_before_the_turn_ends(
    ) {
        use crate::game::scenario::{GameScenario, P0};
        use crate::game::zones::move_to_zone;
        use crate::types::game_state::{CastingVariant, OwedSpellFinalPart};

        let mut scenario = GameScenario::new();
        scenario.at_phase(Phase::End);
        let archivist = scenario
            .add_enchantment_from_oracle(
                P0,
                "Graveyard Archivist",
                "Whenever a card is put into your graveyard from anywhere, you gain 1 life.",
            )
            .id();
        let spell = scenario
            .add_spell_to_hand_from_oracle(P0, "Plain Draw", false, "Draw a card.")
            .id();
        let mut runner = scenario.build();
        let state = runner.state_mut();
        move_to_zone(state, spell, Zone::Stack, &mut Vec::new());
        state.phase = Phase::Cleanup;
        state.active_player = P0;
        state.resolving_stack_entry = Some(StackEntry {
            id: spell,
            source_id: spell,
            controller: P0,
            kind: StackEntryKind::Spell {
                card_id: CardId(spell.0),
                ability: None,
                casting_variant: CastingVariant::Normal,
                actual_mana_spent: 0,
            },
        });
        state.resolving_spell_final_part = Some(OwedSpellFinalPart { spell });
        state.waiting_for = WaitingFor::Priority { player: P0 };
        let starting_turn = state.turn_number;

        let mut events = Vec::new();
        let waiting_for = super::settle_deferred_phase_transition(state, &mut events);

        // Reach guard: the final part ran.
        assert_eq!(state.objects[&spell].zone, Zone::Graveyard);
        assert!(state.resolving_stack_entry.is_none());
        assert!(state.resolving_spell_final_part.is_none());

        assert_eq!(waiting_for, WaitingFor::Priority { player: P0 });
        assert_eq!(state.phase, Phase::Cleanup);
        assert_eq!(state.turn_number, starting_turn, "the turn does not end");
        assert_eq!(
            state
                .stack
                .iter()
                .filter(
                    |entry| matches!(entry.kind, StackEntryKind::TriggeredAbility { .. })
                        && entry.source_id == archivist
                )
                .count(),
            1,
            "the final part's trigger is on the stack"
        );
        assert!(state.deferred_triggers.is_empty());
    }
    fn nonactive_completion_choice() -> crate::types::ability::AbilityDefinition {
        use crate::types::ability::{
            AbilityDefinition, AbilityKind, ChooseOneOfKind, PlayerFilter,
        };
        let gain = |value| Effect::GainLife {
            amount: QuantityExpr::Fixed { value },
            player: TargetFilter::Controller,
        };
        AbilityDefinition::new(
            AbilityKind::Spell,
            Effect::ChooseOneOf {
                chooser: PlayerFilter::Controller,
                branches: vec![AbilityDefinition::new(AbilityKind::Spell, gain(1))],
                kind: ChooseOneOfKind::Ordinary,
            },
        )
        .sub_ability(AbilityDefinition::new(AbilityKind::Spell, gain(11)))
    }

    fn nonactive_priority_window(runner: &mut crate::game::scenario::GameRunner) {
        for player in [PlayerId(0), PlayerId(1)] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        assert_eq!(
            runner.state().waiting_for,
            WaitingFor::Priority {
                player: PlayerId(2)
            }
        );
    }

    fn resolve_from_nonactive_window(
        runner: &mut crate::game::scenario::GameRunner,
    ) -> Vec<GameEvent> {
        let mut events = Vec::new();
        for player in [PlayerId(2), PlayerId(0), PlayerId(1)] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            events.extend(runner.act(GameAction::PassPriority).unwrap().events);
        }
        events
    }

    /// The target answer naming `object`. Built here, apart from the prompt
    /// assertions it answers, so the `loop_shortcut` source census of
    /// `apply_action`'s `TriggerTargetSelection` reducer arms counts only the
    /// production arms.
    fn choose_object_target(object: ObjectId) -> GameAction {
        GameAction::ChooseTarget {
            target: Some(crate::types::ability::TargetRef::Object(object)),
        }
    }

    fn assert_nonactive_completion(state: &GameState, turn: u32) {
        // CR 117.3b: a completed nonmana stack carrier returns priority to AP.
        assert_eq!(
            state.waiting_for,
            WaitingFor::Priority {
                player: PlayerId(0)
            }
        );
        assert_eq!(state.priority_player, PlayerId(0));
        assert!(state.priority_passes.is_empty());
        assert_eq!(state.phase, Phase::PreCombatMain);
        assert_eq!(state.turn_number, turn);
        assert!(state.resolving_stack_entry.is_none());
        let mut accepted = state.clone();
        assert!(apply(&mut accepted, PlayerId(0), GameAction::PassPriority).is_ok());
        for wrong in [PlayerId(1), PlayerId(2)] {
            let mut rejected = state.clone();
            assert!(apply(&mut rejected, wrong, GameAction::PassPriority).is_err());
            assert_eq!(rejected.turn_number, turn);
            assert_eq!(rejected.phase, Phase::PreCombatMain);
            assert_eq!(rejected.players[2].life, state.players[2].life);
        }
    }

    #[test]
    fn paused_nonpayment_resolution_returns_to_active_player() {
        use crate::game::scenario::GameScenario;
        use crate::types::ability::{
            AbilityDefinition, AbilityKind, QuantityRef, ReplacementDefinition, TriggerDefinition,
        };
        use crate::types::counter::CounterType;
        use crate::types::mana::ManaCost;
        use crate::types::replacements::ReplacementEvent;
        use crate::types::zones::EtbTapState;
        use crate::types::TriggerMode;
        let p2 = PlayerId(2);
        // Ordinary activated choice and unpaused activation are independent
        // siblings of the staged PayCost regression.
        for paused in [true, false] {
            let mut scenario = GameScenario::new_n_player(3, 42);
            scenario.at_phase(Phase::PreCombatMain);
            let mut ability = nonactive_completion_choice();
            ability.kind = AbilityKind::Activated;
            if !paused {
                ability = AbilityDefinition::new(
                    AbilityKind::Activated,
                    Effect::GainLife {
                        amount: QuantityExpr::Fixed { value: 12 },
                        player: TargetFilter::Controller,
                    },
                );
            }
            let source = scenario
                .add_creature(p2, "Ordinary completion", 1, 1)
                .with_ability_definition(ability)
                .id();
            // CR 603.3b: each firing puts its own occurrence's amount of
            // counters, so firings off distinct life gains are distinguishable
            // and their controller orders them; identical commuting firings
            // would be announced without a choice.
            let observer = scenario
                .add_creature(p2, "Ordinary completion observer", 1, 1)
                .with_trigger_definition(TriggerDefinition::new(TriggerMode::LifeGained).execute(
                    AbilityDefinition::new(
                        AbilityKind::Spell,
                        Effect::PutCounter {
                            counter_type: CounterType::Plus1Plus1,
                            count: QuantityExpr::Ref {
                                qty: QuantityRef::EventContextAmount,
                            },
                            target: TargetFilter::SelfRef,
                        },
                    ),
                ))
                .id();
            let lower = scenario
                .add_spell_to_hand(PlayerId(0), "Unresolved lower instant", true)
                .with_mana_cost(ManaCost::zero())
                .with_ability_definition(AbilityDefinition::new(AbilityKind::Spell, Effect::NoOp))
                .id();
            let mut runner = scenario.build();
            let turn = runner.state().turn_number;
            runner.cast(lower).commit();
            assert_eq!(runner.state().objects[&lower].zone, Zone::Stack);
            assert_eq!(runner.state().stack.len(), 1);
            nonactive_priority_window(&mut runner);
            runner
                .act(GameAction::ActivateAbility {
                    source_id: source,
                    ability_index: 0,
                    payment_mode: crate::types::game_state::CastPaymentMode::Auto,
                })
                .unwrap();
            let mut events = resolve_from_nonactive_window(&mut runner);
            if paused {
                assert!(
                    matches!(runner.state().waiting_for, WaitingFor::ChooseOneOfBranch { player, .. } if player == p2)
                );
                assert!(runner.state().resolving_stack_entry.is_some());
                assert_eq!(runner.state().stack.len(), 1);
                assert_eq!(runner.state().stack[0].id, lower);
                events.extend(
                    runner
                        .act(GameAction::ChooseBranch { index: 0 })
                        .unwrap()
                        .events,
                );
                for amount in [1, 11] {
                    assert_eq!(events.iter().filter(|event| matches!(event,
                        GameEvent::LifeChanged { player_id, amount: actual, .. } if *player_id == p2 && *actual == amount)).count(), 1);
                }
                assert!(runner.state().resolving_stack_entry.is_none());
                assert_eq!(runner.state().stack.len(), 1);
                assert_eq!(runner.state().stack[0].id, lower);
                assert_eq!(runner.state().objects[&lower].zone, Zone::Stack);
                // CR 117.5 + CR 603.3b: the whole due group is announced before
                // priority, above the unrelated spell that has not resolved.
                assert!(matches!(runner.state().waiting_for,
                    WaitingFor::OrderTriggers { player, .. } if player == p2));
                let groups = &runner
                    .state()
                    .pending_trigger_order
                    .as_ref()
                    .unwrap()
                    .groups;
                assert_eq!(groups.len(), 1);
                assert_eq!(groups[0].triggers.len(), 2, "FIRST whole completed group");
                for amount in [1, 11] {
                    assert_eq!(groups[0].triggers.iter().filter(|context| {
                        context.pending.source_id == observer && matches!(
                            context.pending.trigger_event.as_ref(),
                            Some(GameEvent::LifeChanged { player_id, amount: actual, .. })
                                if *player_id == p2 && *actual == amount
                        )
                    }).count(), 1);
                }
                let selected: Vec<_> = [1, 0]
                    .into_iter()
                    .map(|index| {
                        groups[0].triggers[index]
                            .pending
                            .trigger_event
                            .clone()
                            .unwrap()
                    })
                    .collect();
                events.extend(
                    runner
                        .act(GameAction::OrderTriggers { order: vec![1, 0] })
                        .unwrap()
                        .events,
                );
                let announced: Vec<_> = runner
                    .state()
                    .stack
                    .iter()
                    .skip(1)
                    .map(|entry| {
                        let StackEntryKind::TriggeredAbility { trigger_event, .. } = &entry.kind
                        else {
                            panic!("expected completed observer: {entry:?}");
                        };
                        trigger_event.clone().unwrap()
                    })
                    .collect();
                assert_eq!(announced, selected);
            } else {
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| matches!(event,
                    GameEvent::LifeChanged { player_id, amount: 12, .. } if *player_id == p2))
                        .count(),
                    1
                );
            }
            assert_eq!(runner.state().players[2].life, 32);
            assert!(runner.state().payment_transaction.is_none());
            let observer_count = if paused { 2 } else { 1 };
            assert_eq!(runner.state().stack.len(), observer_count + 1);
            assert_eq!(runner.state().stack[0].id, lower);
            assert!(matches!(
                runner.state().stack[0].kind,
                StackEntryKind::Spell { .. }
            ));
            assert!(runner.state().stack.iter().skip(1).all(|entry| {
                entry.source_id == observer
                    && matches!(entry.kind, StackEntryKind::TriggeredAbility { .. })
            }));
            assert_eq!(runner.state().objects[&lower].zone, Zone::Stack);
            assert!(!events.iter().any(|event| matches!(event,
                GameEvent::StackResolved { object_id, .. } if *object_id == lower)));
            let observer_counters = |state: &GameState| {
                state.objects[&observer]
                    .counters
                    .get(&CounterType::Plus1Plus1)
                    .copied()
                    .unwrap_or(0)
            };
            let mut placed = 0;
            for remaining in (1..=observer_count).rev() {
                // Each announced firing resolves once, with its own occurrence.
                let StackEntryKind::TriggeredAbility {
                    trigger_event: Some(GameEvent::LifeChanged { amount, .. }),
                    ..
                } = &runner.state().stack[remaining].kind
                else {
                    panic!("expected the top completed observer");
                };
                placed += u32::try_from(*amount).expect("a life gain is positive");
                runner.resolve_top();
                assert_eq!(runner.state().stack.len(), remaining);
                assert_eq!(runner.state().objects[&lower].zone, Zone::Stack);
                assert_eq!(observer_counters(runner.state()), placed);
            }
            assert_eq!(runner.state().stack[0].id, lower);
            // Paused +1 and +11, or the synchronous +12, each resolved once.
            assert_eq!(observer_counters(runner.state()), 12);
            assert_nonactive_completion(runner.state(), turn);
        }
        // Synthetic {0} instant: successful final move and a real final-move
        // replacement question exercise Completed and Parked separately.
        for parked in [false, true] {
            let mut scenario = GameScenario::new_n_player(3, 42);
            scenario.at_phase(Phase::PreCombatMain);
            let spell = scenario
                .add_spell_to_hand(p2, "Ordinary paused instant", true)
                .with_mana_cost(ManaCost::zero())
                .with_ability_definition(nonactive_completion_choice())
                .id();
            if parked {
                for name in ["Final move replacement A", "Final move replacement B"] {
                    scenario
                        .add_creature(p2, name, 1, 1)
                        .with_replacement_definition(
                            ReplacementDefinition::new(ReplacementEvent::Moved)
                                .destination_zone(Zone::Graveyard)
                                .execute(AbilityDefinition::new(
                                    AbilityKind::Spell,
                                    Effect::ChangeZone {
                                        library_shuffle: Default::default(),
                                        destination: Zone::Exile,
                                        origin: None,
                                        target: TargetFilter::SelfRef,
                                        owner_library: false,
                                        enter_transformed: false,
                                        enters_under: None,
                                        enter_tapped: EtbTapState::Unspecified,
                                        enters_attacking: false,
                                        up_to: false,
                                        enter_with_counters: vec![],
                                        conditional_enter_with_counters: vec![],
                                        face_down_profile: None,
                                        enters_modified_if: None,
                                    },
                                )),
                        );
                }
            }
            let mut runner = scenario.build();
            let turn = runner.state().turn_number;
            nonactive_priority_window(&mut runner);
            runner.cast(spell).commit();
            let mut events = resolve_from_nonactive_window(&mut runner);
            assert!(
                matches!(runner.state().waiting_for, WaitingFor::ChooseOneOfBranch { player, .. } if player == p2)
            );
            assert!(runner.state().resolving_spell_final_part.is_some());
            events.extend(
                runner
                    .act(GameAction::ChooseBranch { index: 0 })
                    .unwrap()
                    .events,
            );
            if parked {
                assert!(matches!(
                    runner.state().waiting_for,
                    WaitingFor::ReplacementChoice { .. }
                ));
                assert!(runner.state().resolving_stack_entry.is_some());
                events.extend(
                    runner
                        .act(GameAction::ChooseReplacement { index: 0 })
                        .unwrap()
                        .events,
                );
            }
            assert_eq!(runner.state().players[2].life, 32);
            assert_eq!(
                runner.state().objects[&spell].zone,
                if parked { Zone::Exile } else { Zone::Graveyard }
            );
            assert!(runner.state().resolving_spell_final_part.is_none());
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event,
                GameEvent::StackResolved { object_id, .. } if *object_id == spell))
                    .count(),
                1
            );
            assert_eq!(events.iter().filter(|event| matches!(event,
                GameEvent::ZoneChanged { object_id, from: Some(Zone::Stack), .. } if *object_id == spell)).count(), 1);
            assert_nonactive_completion(runner.state(), turn);
        }
    }

    #[test]
    fn nonactive_mana_ability_retains_its_priority_window() {
        use crate::game::scenario::GameScenario;
        use crate::types::ability::{
            AbilityCost, AbilityDefinition, AbilityKind, ManaProduction, QuantityModification,
            ReplacementDefinition,
        };
        use crate::types::game_state::{
            ManaAbilityCostResolutionMode, ManaAbilityResume, PendingCostMoveResume,
        };
        use crate::types::replacements::ReplacementEvent;
        let p2 = PlayerId(2);
        for paused in [true, false] {
            let mut scenario = GameScenario::new_n_player(3, 42);
            scenario.at_phase(Phase::PreCombatMain);
            let ability = AbilityDefinition::new(
                AbilityKind::Activated,
                Effect::Mana {
                    produced: ManaProduction::Colorless {
                        count: QuantityExpr::Fixed { value: 1 },
                    },
                    target: None,
                    restrictions: vec![],
                    grants: vec![],
                    expiry: None,
                },
            )
            .cost(AbilityCost::PayLife {
                amount: QuantityExpr::Fixed { value: 1 },
            });
            let source = scenario
                .add_creature(p2, "Direct mana completion", 1, 1)
                .with_ability_definition(ability)
                .id();
            if paused {
                let mut replacement = nonactive_completion_choice();
                replacement.sub_ability = None;
                scenario
                    .add_creature(p2, "Mana life replacement", 1, 1)
                    .with_replacement_definition(
                        ReplacementDefinition::new(ReplacementEvent::LoseLife)
                            .quantity_modification(QuantityModification::Plus { value: 0 })
                            .execute(replacement),
                    );
            }
            let mut runner = scenario.build();
            let turn = runner.state().turn_number;
            nonactive_priority_window(&mut runner);
            let mut events = runner
                .act(GameAction::ActivateAbility {
                    source_id: source,
                    ability_index: 0,
                    payment_mode: crate::types::game_state::CastPaymentMode::Auto,
                })
                .unwrap()
                .events;
            if paused {
                assert!(
                    matches!(runner.state().waiting_for, WaitingFor::ChooseOneOfBranch { player, .. } if player == p2)
                );
                // CR 605.3b + CR 119.4 + CR 614.1: paying the life is a life
                // loss its replacement modifies, so the direct activation's
                // typed cost cursor — not an effect-payment deferred-life root —
                // owns the unpaid remainder and returns to P2's own window.
                let Some(PendingCostMoveResume::ManaAbilityPayment { pending, cursor }) =
                    runner.state().pending_cost_move_resume.as_ref()
                else {
                    panic!("direct mana activation owns its paused life payment");
                };
                assert_eq!(pending.player, p2);
                assert_eq!(pending.source_id, source);
                assert_eq!(pending.ability_index, Some(0));
                assert!(matches!(pending.resume, ManaAbilityResume::Priority));
                assert!(pending.cost_move_resume.is_none());
                assert!(cursor.remaining.is_empty());
                assert!(cursor.remaining_life_payments.is_empty());
                assert!(matches!(
                    cursor.resolution_mode,
                    ManaAbilityCostResolutionMode::Interactive
                ));
                assert!(cursor.parent.is_none());
                assert!(runner.state().pending_deferred_life_cost_resume.is_none());
                assert!(runner.state().stack.is_empty());
                assert!(runner.state().resolving_stack_entry.is_none());
                events.extend(
                    runner
                        .act(GameAction::ChooseBranch { index: 0 })
                        .unwrap()
                        .events,
                );
            }
            assert_eq!(runner.state().players[2].life, if paused { 20 } else { 19 });
            assert_eq!(runner.state().players[2].mana_pool.total(), 1);
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event,
                GameEvent::LifeChanged { player_id, amount: -1, .. } if *player_id == p2))
                    .count(),
                1
            );
            assert!(runner.state().resolving_stack_entry.is_none());
            assert!(runner.state().pending_deferred_life_cost_resume.is_none());
            assert!(runner.state().pending_cost_move_resume.is_none());
            // CR 117.3c + CR 605.3b: this nonstack mana root keeps P2's window.
            assert_eq!(
                runner.state().waiting_for,
                WaitingFor::Priority { player: p2 }
            );
            assert_eq!(runner.state().priority_player, p2);
            assert_eq!(runner.state().turn_number, turn);
            assert_eq!(runner.state().phase, Phase::PreCombatMain);
        }
    }
    #[test]
    fn ripple_terminal_completion_returns_to_active_player_without_stack_growth() {
        use crate::game::scenario::GameScenario;
        use crate::types::ability::{
            AbilityDefinition, AbilityKind, TargetRef, TriggerDefinition, TypedFilter,
        };
        use crate::types::actions::CastChoice;
        use crate::types::counter::CounterType;
        use crate::types::keywords::Keyword;
        use crate::types::mana::{ManaCost, ManaType, ManaUnit};
        use crate::types::TriggerMode;
        // Exact pinned Oracle, plus the explicit keyword metadata used in
        // production. Ripple's trigger resolves separately from the spell.
        const ORACLE: &str = "Ripple 4 (When you cast this spell, you may reveal the top four cards of your library. You may cast spells with the same name as this spell from among those cards without paying their mana costs. Put the rest on the bottom of your library.)\nSurging Flame deals 2 damage to any target.";
        let p2 = PlayerId(2);
        for accept_hit in [false, true] {
            let mut scenario = GameScenario::new_n_player(3, 42);
            scenario.at_phase(Phase::PreCombatMain);
            scenario.with_mana_pool(
                p2,
                vec![
                    ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]),
                    ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]),
                ],
            );
            let original = scenario
                .add_spell_to_hand_from_oracle(p2, "Surging Flame", true, ORACLE)
                .with_mana_cost(ManaCost::Cost {
                    shards: vec![crate::types::mana::ManaCostShard::Red],
                    generic: 1,
                })
                .with_keyword(Keyword::Ripple(4))
                .id();
            let observer = if accept_hit {
                let observer = scenario
                    .add_creature(p2, "Cast observer target", 1, 1)
                    .with_trigger_definition(
                        TriggerDefinition::new(TriggerMode::SpellCast).execute(
                            AbilityDefinition::new(
                                AbilityKind::Spell,
                                Effect::PutCounter {
                                    counter_type: CounterType::Plus1Plus1,
                                    count: QuantityExpr::Fixed { value: 1 },
                                    target: TargetFilter::Typed(TypedFilter::creature()),
                                },
                            ),
                        ),
                    )
                    .id();
                scenario.add_creature(p2, "Other cast observer target", 1, 1);
                Some(observer)
            } else {
                None
            };
            let deep = scenario.add_card_to_library_top(p2, "Deep card");
            let misses: Vec<_> = (0..if accept_hit { 3 } else { 4 })
                .map(|index| scenario.add_card_to_library_top(p2, &format!("Ripple miss {index}")))
                .collect();
            let hit = accept_hit.then(|| {
                scenario
                    .add_spell_to_library_top(p2, "Surging Flame", true)
                    .from_oracle_text(ORACLE)
                    .with_mana_cost(ManaCost::Cost {
                        shards: vec![crate::types::mana::ManaCostShard::Red],
                        generic: 1,
                    })
                    .with_keyword(Keyword::Ripple(4))
                    .id()
            });
            let mut runner = scenario.build();
            let turn = runner.state().turn_number;
            nonactive_priority_window(&mut runner);
            let card_id = runner.state().objects[&original].card_id;
            runner
                .act(GameAction::CastSpell {
                    object_id: original,
                    card_id,
                    targets: vec![],
                    payment_mode: crate::types::game_state::CastPaymentMode::Auto,
                })
                .unwrap();
            assert!(matches!(
                runner.state().waiting_for,
                WaitingFor::TargetSelection { .. }
            ));
            runner
                .act(GameAction::ChooseTarget {
                    target: Some(TargetRef::Player(PlayerId(1))),
                })
                .unwrap();
            assert_eq!(runner.state().players[2].mana_pool.total(), 0);
            if let Some(observer) = observer {
                // First cast's two observers are announced and its ordinary
                // observer resolves before entering the selected Ripple.
                let order_state = runner.state().pending_trigger_order.as_ref().unwrap();
                let contexts = &order_state.groups[0].triggers;
                assert_eq!(contexts.len(), 2);
                let ripple = contexts
                    .iter()
                    .position(|context| context.pending.source_id == original)
                    .unwrap();
                let ordinary = contexts
                    .iter()
                    .position(|context| context.pending.source_id == observer)
                    .unwrap();
                runner
                    .act(GameAction::OrderTriggers {
                        order: vec![ripple, ordinary],
                    })
                    .unwrap();
                assert!(matches!(
                    runner.state().waiting_for,
                    WaitingFor::TriggerTargetSelection { .. }
                ));
                runner.act(choose_object_target(observer)).unwrap();
                assert_eq!(runner.state().stack.len(), 3);
                // No lower spell is resolved to obtain the intended window.
                resolve_from_nonactive_window(&mut runner);
                assert_eq!(
                    runner.state().objects[&observer]
                        .counters
                        .get(&CounterType::Plus1Plus1),
                    Some(&1)
                );
                assert_eq!(runner.state().stack.len(), 2);
                // CR 117.3b + CR 117.4: the observer's resolution returned
                // priority to active P0. P0 and P1 pass, so caster P2's pass
                // closes this round and resolves the Ripple trigger.
                nonactive_priority_window(&mut runner);
                runner.act(GameAction::PassPriority).unwrap();
            } else {
                resolve_from_nonactive_window(&mut runner);
            }
            assert!(
                matches!(runner.state().waiting_for, WaitingFor::RippleRevealChoice { player, count: 4, .. } if player == p2)
            );
            assert_eq!(runner.state().stack.len(), 1);
            assert_eq!(runner.state().objects[&original].zone, Zone::Stack);
            let mut events = runner
                .act(GameAction::RippleChoice {
                    choice: CastChoice::Cast,
                })
                .unwrap()
                .events;
            if let Some(hit) = hit {
                assert!(matches!(
                    runner.state().waiting_for,
                    WaitingFor::CastOffer { .. }
                ));
                events.extend(
                    runner
                        .act(GameAction::RippleChoice {
                            choice: CastChoice::Cast,
                        })
                        .unwrap()
                        .events,
                );
                assert!(matches!(
                    runner.state().waiting_for,
                    WaitingFor::TargetSelection { .. }
                ));
                events.extend(
                    runner
                        .act(GameAction::ChooseTarget {
                            target: Some(TargetRef::Player(PlayerId(1))),
                        })
                        .unwrap()
                        .events,
                );
                assert_eq!(runner.state().objects[&hit].zone, Zone::Stack);
            }
            let offered = match &runner.state().waiting_for {
                WaitingFor::RippleBottomOrder { player, cards, .. } => {
                    assert_eq!(*player, p2);
                    let mut actual = cards.clone();
                    actual.sort();
                    let mut expected = misses.clone();
                    expected.sort();
                    assert_eq!(actual, expected);
                    cards.clone()
                }
                other => panic!("actual bottom-order prompt required: {other:?}"),
            };
            let ordered: Vec<_> = offered.iter().rev().copied().collect();
            assert_ne!(ordered, offered);
            events.extend(
                runner
                    .act(GameAction::SelectCards {
                        cards: ordered.clone(),
                    })
                    .unwrap()
                    .events,
            );
            let library: Vec<_> = runner.state().players[2].library.iter().copied().collect();
            assert_eq!(library[0], deep);
            assert_eq!(
                &library[library.len() - ordered.len()..],
                ordered.as_slice()
            );
            assert!(runner.state().pending_resolution_completion.is_none());
            assert!(runner.state().resolving_stack_entry.is_none());
            assert_eq!(runner.state().objects[&original].zone, Zone::Stack);
            if let (Some(hit), Some(observer)) = (hit, observer) {
                let groups = &runner
                    .state()
                    .pending_trigger_order
                    .as_ref()
                    .unwrap()
                    .groups;
                assert_eq!(groups.len(), 1);
                let contexts = &groups[0].triggers;
                assert_eq!(
                    contexts.len(),
                    2,
                    "accepted cast gets one whole terminal observer batch"
                );
                for context in contexts {
                    assert!(
                        matches!(context.pending.trigger_event, Some(GameEvent::SpellCast { object_id, .. }) if object_id == hit)
                    );
                }
                let ripple = contexts
                    .iter()
                    .position(|context| context.pending.source_id == hit)
                    .unwrap();
                let ordinary = contexts
                    .iter()
                    .position(|context| context.pending.source_id == observer)
                    .unwrap();
                events.extend(
                    runner
                        .act(GameAction::OrderTriggers {
                            order: vec![ripple, ordinary],
                        })
                        .unwrap()
                        .events,
                );
                let WaitingFor::TriggerTargetSelection { target_slots, .. } =
                    &runner.state().waiting_for
                else {
                    panic!("accepted cast observer must construct its real target");
                };
                assert!(target_slots[0].legal_targets.len() >= 2);
                events.extend(runner.act(choose_object_target(observer)).unwrap().events);
                assert_eq!(runner.state().stack.len(), 4);
                assert_eq!(runner.state().stack[0].id, original);
                assert_eq!(runner.state().stack[1].id, hit);
                assert_eq!(runner.state().stack[2].source_id, hit);
                assert_eq!(runner.state().stack[3].source_id, observer);
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| matches!(event,
                    GameEvent::SpellCast { object_id, .. } if *object_id == hit))
                        .count(),
                    1
                );
            } else {
                assert_eq!(
                    runner.state().stack.len(),
                    1,
                    "no-hit completion has no stack growth"
                );
            }
            // CR 117.3b + CR 702.60a: completing Ripple grants AP priority
            // immediately, while both damage spells remain unresolved below.
            assert_nonactive_completion(runner.state(), turn);
        }
    }

    /// CR 117.3b + CR 117.5 + CR 800.4a + CR 800.4j: the early final-part
    /// completion recipient is read before this pass's state-based actions. When
    /// those actions remove the active player, the trigger construction the
    /// completed batch opens hands priority to the next player in turn order
    /// still in the game, never to the departed seat.
    #[test]
    fn early_final_part_completion_recipient_skips_an_eliminated_active_player() {
        use crate::game::scenario::GameScenario;
        use crate::types::ability::TargetRef;
        use crate::types::mana::{ManaCost, ManaCostShard, ManaType, ManaUnit};
        // Exact pinned Oracle text.
        const HYMN: &str = "Surveil 1, then you draw a card and lose 1 life. (To surveil 1, look at the top card of your library. You may put it into your graveyard.)\nVoid \u{2014} If a nonland permanent left the battlefield this turn or a spell was warped this turn, draw another card.";
        const BOWMASTERS: &str = "Flash\nWhen this creature enters and whenever an opponent draws a card except the first one they draw in each of their draw steps, this creature deals 1 damage to any target. Then amass Orcs 1.";
        let (p0, p1, p2) = (PlayerId(0), PlayerId(1), PlayerId(2));
        let mut scenario = GameScenario::new_n_player(3, 42);
        scenario.at_phase(Phase::PreCombatMain);
        scenario.with_life(p0, 1);
        scenario.with_mana_pool(
            p0,
            vec![
                ManaUnit::new(ManaType::Black, ObjectId(0), false, vec![]),
                ManaUnit::new(ManaType::Black, ObjectId(0), false, vec![]),
            ],
        );
        let hymn = scenario
            .add_spell_to_hand(p0, "Hymn of the Faller", false)
            .from_oracle_text_with_keywords(&["Surveil", "Void"], HYMN)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Black],
                generic: 1,
            })
            .id();
        let bowmasters = scenario
            .add_creature(p2, "Orcish Bowmasters", 1, 1)
            .from_oracle_text_with_keywords(&["Amass", "Flash"], BOWMASTERS)
            .id();
        scenario.add_card_to_library_top(p0, "Library filler");
        let surveilled = scenario.add_card_to_library_top(p0, "Surveilled card");
        let mut runner = scenario.build();
        let turn = runner.state().turn_number;
        // CR 101.4: turn order runs P0 -> P1 -> P2.
        assert_eq!(runner.state().seat_order, [p0, p1, p2]);
        assert_eq!(
            runner.state().turn_direction,
            crate::types::phase::TurnDirection::Normal
        );

        runner.cast(hymn).commit();
        for player in [p0, p1, p2] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        // Reach guard: the sorcery paused on its surveil while still owing its
        // final part, and no in-resolution cast installed a terminal marker,
        // so its completion can only come from the pass-top final part.
        assert!(matches!(
            &runner.state().waiting_for,
            WaitingFor::SurveilChoice { player, cards } if *player == p0 && *cards == [surveilled]
        ));
        assert_eq!(
            runner
                .state()
                .resolving_stack_entry
                .as_ref()
                .map(|entry| entry.id),
            Some(hymn)
        );
        assert!(runner.state().resolving_spell_final_part.is_some());
        assert!(runner.state().pending_resolution_completion.is_none());
        assert!(runner
            .state()
            .pending_trigger_construction_priority_recipient
            .is_none());

        let events = runner
            .act(GameAction::SelectCards {
                cards: vec![surveilled],
            })
            .unwrap()
            .events;
        // Reach guards: the draw and the life loss happened once, the final
        // part ran in this action, and the active player then lost the game to
        // the state-based action (CR 704.5a) in a game that continues.
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::CardDrawn { player_id, object_id, .. }
                        if *player_id == p0 && *object_id == surveilled))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::CardDrawn { player_id, .. } if *player_id == p0))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::LifeChanged { player_id, amount: -1, .. } if *player_id == p0))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::StackResolved { object_id } if *object_id == hymn))
                .count(),
            1
        );
        assert!(runner.state().resolving_stack_entry.is_none());
        assert!(runner.state().resolving_spell_final_part.is_none());
        assert!(runner.state().pending_resolution_completion.is_none());
        assert!(runner.state().players[0].is_eliminated);
        assert!(!runner.state().players[1].is_eliminated);
        assert!(!runner.state().players[2].is_eliminated);
        assert!(runner.state().game_end.is_none());
        assert_eq!(runner.state().active_player, p0);
        // Reach guard: the Bowmasters trigger is under real construction, with
        // more than one legal target and none of them the departed player.
        let WaitingFor::TriggerTargetSelection {
            player,
            source_id,
            target_slots,
            ..
        } = &runner.state().waiting_for
        else {
            panic!(
                "Bowmasters' trigger must construct its real target: {:?}",
                runner.state().waiting_for
            );
        };
        assert_eq!(*player, p2);
        assert_eq!(*source_id, Some(bowmasters));
        assert!(target_slots[0].legal_targets.len() >= 2);
        assert!(target_slots[0]
            .legal_targets
            .contains(&TargetRef::Player(p1)));
        assert!(!target_slots[0]
            .legal_targets
            .contains(&TargetRef::Player(p0)));
        // Reach guard: the completed resolution's recipient was persisted
        // across this construction prompt.
        assert!(runner
            .state()
            .pending_trigger_construction_priority_recipient
            .is_some());

        runner
            .act(GameAction::ChooseTarget {
                target: Some(TargetRef::Player(p1)),
            })
            .unwrap();
        assert_eq!(runner.state().stack.len(), 1);
        assert_eq!(runner.state().stack[0].source_id, bowmasters);
        assert!(matches!(
            runner.state().stack[0].kind,
            StackEntryKind::TriggeredAbility { .. }
        ));
        assert!(runner
            .state()
            .pending_trigger_construction_priority_recipient
            .is_none());
        // CR 117.3b + CR 800.4j: the departed active player would have received
        // priority, so the next player in turn order (P0 -> P1) receives it.
        assert_eq!(
            runner.state().waiting_for,
            WaitingFor::Priority { player: p1 }
        );
        assert_eq!(runner.state().priority_player, p1);
        assert_eq!(runner.state().phase, Phase::PreCombatMain);
        assert_eq!(runner.state().turn_number, turn);
        let mut accepted = runner.state().clone();
        assert!(apply(&mut accepted, p1, GameAction::PassPriority).is_ok());
        for wrong in [p0, p2] {
            let mut rejected = runner.state().clone();
            assert!(apply(&mut rejected, wrong, GameAction::PassPriority).is_err());
            assert_eq!(rejected.stack.len(), 1);
        }
    }

    /// Exact pinned Oracle text of Hymn of the Faller.
    const HYMN_OF_THE_FALLER: &str = "Surveil 1, then you draw a card and lose 1 life. (To surveil 1, look at the top card of your library. You may put it into your graveyard.)\nVoid \u{2014} If a nonland permanent left the battlefield this turn or a spell was warped this turn, draw another card.";

    /// Stages active P0 at 1 life with a funded Hymn of the Faller in hand and
    /// a known card on top of its library for the surveil and the draw.
    /// Returns `(hymn, surveilled)`.
    fn stage_lethal_hymn(
        scenario: &mut crate::game::scenario::GameScenario,
    ) -> (ObjectId, ObjectId) {
        use crate::types::mana::{ManaCost, ManaCostShard, ManaType, ManaUnit};
        let p0 = PlayerId(0);
        scenario.with_life(p0, 1);
        scenario.with_mana_pool(
            p0,
            vec![
                ManaUnit::new(ManaType::Black, ObjectId(0), false, vec![]),
                ManaUnit::new(ManaType::Black, ObjectId(0), false, vec![]),
            ],
        );
        let hymn = scenario
            .add_spell_to_hand(p0, "Hymn of the Faller", false)
            .from_oracle_text_with_keywords(&["Surveil", "Void"], HYMN_OF_THE_FALLER)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Black],
                generic: 1,
            })
            .id();
        scenario.add_card_to_library_top(p0, "Library filler");
        let surveilled = scenario.add_card_to_library_top(p0, "Surveilled card");
        (hymn, surveilled)
    }

    /// CR 704.5a + CR 800.4a + CR 800.4j: active P0 casts the staged Hymn, every
    /// player passes, and P0 answers its surveil. The draw and the life loss
    /// leave P0 at 0 life, so the state-based action removes P0 in its own
    /// action. The game continues in P0's turn without an active player, and the
    /// priority P0 would have received goes to P1, the next player in turn
    /// order.
    fn resolve_lethal_hymn(
        runner: &mut crate::game::scenario::GameRunner,
        hymn: ObjectId,
        surveilled: ObjectId,
    ) {
        let (p0, p1, p2) = (PlayerId(0), PlayerId(1), PlayerId(2));
        // Turn order runs P0 -> P1 -> P2.
        assert_eq!(runner.state().seat_order, [p0, p1, p2]);
        assert_eq!(
            runner.state().turn_direction,
            crate::types::phase::TurnDirection::Normal
        );
        runner.cast(hymn).commit();
        for player in [p0, p1, p2] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        assert!(matches!(
            &runner.state().waiting_for,
            WaitingFor::SurveilChoice { player, cards } if *player == p0 && *cards == [surveilled]
        ));
        let events = runner
            .act(GameAction::SelectCards {
                cards: vec![surveilled],
            })
            .unwrap()
            .events;
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::CardDrawn { player_id, object_id, .. }
                        if *player_id == p0 && *object_id == surveilled))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::LifeChanged { player_id, amount: -1, .. } if *player_id == p0))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::StackResolved { object_id } if *object_id == hymn))
                .count(),
            1
        );
        assert!(runner.state().stack.is_empty());
        assert!(runner.state().resolving_stack_entry.is_none());
        assert!(runner.state().players[0].is_eliminated);
        assert!(!runner.state().players[1].is_eliminated);
        assert!(!runner.state().players[2].is_eliminated);
        assert!(runner.state().game_end.is_none());
        assert_eq!(runner.state().active_player, p0);
        assert_eq!(
            runner.state().waiting_for,
            WaitingFor::Priority { player: p1 }
        );
        assert_eq!(runner.state().priority_player, p1);
    }

    /// CR 117.3b + CR 800.4j: the departed active player is replaced by the
    /// next player in turn order still in the game. P1 holds priority, no
    /// other seat may act, and the turn is unchanged.
    fn assert_priority_skips_the_departed_active_player(state: &GameState, turn: u32) {
        let (p0, p1, p2) = (PlayerId(0), PlayerId(1), PlayerId(2));
        assert!(state.players[0].is_eliminated);
        assert!(state.game_end.is_none());
        assert_eq!(state.active_player, p0);
        assert_eq!(state.waiting_for, WaitingFor::Priority { player: p1 });
        assert_eq!(state.priority_player, p1);
        assert!(state.priority_passes.is_empty());
        assert_eq!(state.phase, Phase::PreCombatMain);
        assert_eq!(state.turn_number, turn);
        let mut accepted = state.clone();
        assert!(apply(&mut accepted, p1, GameAction::PassPriority).is_ok());
        for wrong in [p0, p2] {
            let mut rejected = state.clone();
            assert!(apply(&mut rejected, wrong, GameAction::PassPriority).is_err());
            assert_eq!(rejected.stack.len(), state.stack.len());
            assert_eq!(rejected.phase, Phase::PreCombatMain);
            assert_eq!(rejected.turn_number, turn);
        }
    }

    /// CR 117.3b + CR 608.2n + CR 800.4j: the active player left the game in an
    /// EARLIER action, and the turn continues. A spell another player casts
    /// later in that turn pauses, and its final part completes it at the pass
    /// top after the answer, with no state-based action or trigger in that
    /// pass. The active player would receive priority, so the next player in
    /// turn order still in the game receives it instead.
    #[test]
    fn completion_after_the_active_player_left_gives_priority_to_the_next_living_seat() {
        use crate::game::scenario::GameScenario;
        use crate::types::mana::{ManaCost, ManaCostShard, ManaType, ManaUnit};
        // Exact pinned Oracle text.
        const CONSIDER: &str = "Surveil 1. (Look at the top card of your library. You may put it into your graveyard.)\nDraw a card.";
        let (p1, p2) = (PlayerId(1), PlayerId(2));
        let mut scenario = GameScenario::new_n_player(3, 42);
        scenario.at_phase(Phase::PreCombatMain);
        let (hymn, hymn_surveilled) = stage_lethal_hymn(&mut scenario);
        scenario.with_mana_pool(
            p1,
            vec![ManaUnit::new(ManaType::Blue, ObjectId(0), false, vec![])],
        );
        let consider = scenario
            .add_spell_to_hand(p1, "Consider", true)
            .from_oracle_text_with_keywords(&["Surveil"], CONSIDER)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Blue],
                generic: 0,
            })
            .id();
        scenario.add_card_to_library_top(p1, "P1 library filler");
        let surveilled = scenario.add_card_to_library_top(p1, "P1 surveilled card");
        let mut runner = scenario.build();
        let turn = runner.state().turn_number;
        resolve_lethal_hymn(&mut runner, hymn, hymn_surveilled);

        runner.cast(consider).commit();
        // CR 117.3c: the caster receives priority. P1 and P2 pass in turn
        // order past the departed seat, so Consider resolves.
        for player in [p1, p2] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        // Reach guard: Consider paused on its surveil while still owing its
        // final part, and no terminal marker is installed, so its completion
        // comes from the pass-top final part.
        assert!(matches!(
            &runner.state().waiting_for,
            WaitingFor::SurveilChoice { player, cards } if *player == p1 && *cards == [surveilled]
        ));
        assert_eq!(
            runner
                .state()
                .resolving_stack_entry
                .as_ref()
                .map(|entry| entry.id),
            Some(consider)
        );
        assert!(runner.state().resolving_spell_final_part.is_some());
        assert!(runner.state().pending_resolution_completion.is_none());

        let events = runner
            .act(GameAction::SelectCards {
                cards: vec![surveilled],
            })
            .unwrap()
            .events;
        // Reach guards: P1 drew the surveilled card once, and Consider
        // resolved exactly once into its owner's graveyard in this action.
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::CardDrawn { player_id, object_id, .. }
                        if *player_id == p1 && *object_id == surveilled))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::CardDrawn { player_id, .. } if *player_id == p1))
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event,
                    GameEvent::StackResolved { object_id } if *object_id == consider))
                .count(),
            1
        );
        assert_eq!(runner.state().objects[&consider].zone, Zone::Graveyard);
        assert!(runner.state().stack.is_empty());
        assert!(runner.state().resolving_stack_entry.is_none());
        assert!(runner.state().resolving_spell_final_part.is_none());
        assert!(runner.state().pending_resolution_completion.is_none());
        assert!(runner
            .state()
            .pending_trigger_construction_priority_recipient
            .is_none());
        assert_priority_skips_the_departed_active_player(runner.state(), turn);
    }

    /// CR 117.3b + CR 702.60a + CR 800.4j: the same entitlement at the late
    /// terminal completion site. After the active player left the game in an
    /// earlier action, P2 casts Surging Flame. Its Ripple trigger reveals no
    /// hit, and completing the bottom order retires that trigger. The active
    /// player would receive priority, so the next player in turn order still
    /// in the game receives it, not the departed seat and not the trigger's
    /// controller.
    #[test]
    fn late_terminal_completion_after_the_active_player_left_gives_priority_to_the_next_living_seat(
    ) {
        use crate::game::scenario::GameScenario;
        use crate::types::ability::TargetRef;
        use crate::types::actions::CastChoice;
        use crate::types::keywords::Keyword;
        use crate::types::mana::{ManaCost, ManaCostShard, ManaType, ManaUnit};
        // Exact pinned Oracle, plus the explicit keyword metadata used in
        // production.
        const SURGING_FLAME: &str = "Ripple 4 (When you cast this spell, you may reveal the top four cards of your library. You may cast spells with the same name as this spell from among those cards without paying their mana costs. Put the rest on the bottom of your library.)\nSurging Flame deals 2 damage to any target.";
        let (p1, p2) = (PlayerId(1), PlayerId(2));
        let mut scenario = GameScenario::new_n_player(3, 42);
        scenario.at_phase(Phase::PreCombatMain);
        let (hymn, hymn_surveilled) = stage_lethal_hymn(&mut scenario);
        scenario.with_mana_pool(
            p2,
            vec![
                ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]),
                ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]),
            ],
        );
        let flame = scenario
            .add_spell_to_hand_from_oracle(p2, "Surging Flame", true, SURGING_FLAME)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Red],
                generic: 1,
            })
            .with_keyword(Keyword::Ripple(4))
            .id();
        let deep = scenario.add_card_to_library_top(p2, "Deep card");
        let misses: Vec<_> = (0..4)
            .map(|index| scenario.add_card_to_library_top(p2, &format!("Ripple miss {index}")))
            .collect();
        let mut runner = scenario.build();
        let turn = runner.state().turn_number;
        resolve_lethal_hymn(&mut runner, hymn, hymn_surveilled);

        // P1 passes on the empty stack, so P2 receives priority and casts.
        runner.act(GameAction::PassPriority).unwrap();
        assert_eq!(
            runner.state().waiting_for,
            WaitingFor::Priority { player: p2 }
        );
        let card_id = runner.state().objects[&flame].card_id;
        runner
            .act(GameAction::CastSpell {
                object_id: flame,
                card_id,
                targets: vec![],
                payment_mode: crate::types::game_state::CastPaymentMode::Auto,
            })
            .unwrap();
        assert!(matches!(
            runner.state().waiting_for,
            WaitingFor::TargetSelection { .. }
        ));
        runner
            .act(GameAction::ChooseTarget {
                target: Some(TargetRef::Player(p1)),
            })
            .unwrap();
        assert_eq!(runner.state().players[2].mana_pool.total(), 0);
        // CR 117.3c: the caster receives priority. P2 and P1 pass past the
        // departed seat, which resolves only the Ripple trigger.
        assert_eq!(runner.state().stack.len(), 2);
        for player in [p2, p1] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        assert!(
            matches!(runner.state().waiting_for, WaitingFor::RippleRevealChoice { player, count: 4, .. } if player == p2)
        );
        assert_eq!(runner.state().stack.len(), 1);
        assert_eq!(runner.state().objects[&flame].zone, Zone::Stack);
        runner
            .act(GameAction::RippleChoice {
                choice: CastChoice::Cast,
            })
            .unwrap();
        // Reach guard: the real bottom-order prompt for exactly the misses.
        let offered = match &runner.state().waiting_for {
            WaitingFor::RippleBottomOrder { player, cards, .. } => {
                assert_eq!(*player, p2);
                let mut actual = cards.clone();
                actual.sort();
                let mut expected = misses.clone();
                expected.sort();
                assert_eq!(actual, expected);
                cards.clone()
            }
            other => panic!("actual bottom-order prompt required: {other:?}"),
        };
        let ordered: Vec<_> = offered.iter().rev().copied().collect();
        assert_ne!(ordered, offered);
        runner
            .act(GameAction::SelectCards {
                cards: ordered.clone(),
            })
            .unwrap();
        // Reach guards: the pile is on the library bottom in the requested
        // order, the terminal marker was consumed, the Ripple carrier retired,
        // and Surging Flame is still on the stack with no stack growth.
        let library: Vec<_> = runner.state().players[2].library.iter().copied().collect();
        assert_eq!(library[0], deep);
        assert_eq!(
            &library[library.len() - ordered.len()..],
            ordered.as_slice()
        );
        assert!(runner.state().pending_resolution_completion.is_none());
        assert!(runner.state().resolving_stack_entry.is_none());
        assert_eq!(runner.state().stack.len(), 1);
        assert_eq!(runner.state().stack[0].id, flame);
        assert_eq!(runner.state().objects[&flame].zone, Zone::Stack);
        assert_priority_skips_the_departed_active_player(runner.state(), turn);
    }

    /// CR 117.3c + CR 603.12 + CR 608.2n: a reflexive trigger is put on the
    /// stack, choosing its target, while the ability that created it is still
    /// resolving (CR 603.3d), so that ability's carrier outlives the target
    /// answer. Kitt Kanto is controlled by non-active P1: in P0's turn its
    /// beginning-of-combat trigger resolves, P1 taps two creatures, and P1
    /// answers the reflexive's target. P1 then holds priority, nobody has
    /// passed, and the finished carrier is still installed. P1 casts Shock, a
    /// targeted instant. That resolution ended before P1's window opened, so
    /// retiring its carrier during the cast grants no priority: P1 had
    /// priority when casting Shock and receives priority afterward.
    #[test]
    fn a_finished_lagging_carrier_does_not_take_priority_from_a_nonactive_caster() {
        use crate::game::scenario::GameScenario;
        use crate::types::mana::{ManaCost, ManaCostShard, ManaType, ManaUnit};
        // Exact pinned Oracle.
        const KITT_KANTO: &str = "When Kitt Kanto enters, create a 1/1 green and white Citizen creature token.\nAt the beginning of combat on each player's turn, you may tap two untapped creatures you control. When you do, target creature that player controls gets +2/+2 and gains trample until end of turn. Goad that creature.";
        const SHOCK: &str = "Shock deals 2 damage to any target.";
        let (p0, p1, p2) = (PlayerId(0), PlayerId(1), PlayerId(2));
        let mut scenario = GameScenario::new_n_player(3, 42);
        scenario.at_phase(Phase::PreCombatMain);
        let kitt = scenario
            .add_creature_from_oracle(p1, "Kitt Kanto, Mayhem Diva", 3, 3, KITT_KANTO)
            .id();
        let tapped_for_kitt = [
            scenario.add_creature(p1, "Grizzly Bears", 2, 2).id(),
            scenario.add_creature(p1, "Grizzly Bears", 2, 2).id(),
        ];
        // Two creatures of the active player, so the reflexive's target and
        // Shock's target are each a real choice.
        let reflexive_target = scenario.add_creature(p0, "Grizzly Bears", 2, 2).id();
        let shock_target = scenario.add_creature(p0, "Grizzly Bears", 2, 2).id();
        let shock = scenario
            .add_spell_to_hand_from_oracle(p1, "Shock", true, SHOCK)
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Red],
                generic: 0,
            })
            .id();
        let mut runner = scenario.build();
        let turn = runner.state().turn_number;

        // CR 117.4: all players pass on the empty stack, so the main phase
        // ends; Kitt Kanto's trigger goes on the stack (CR 603.3).
        for player in [p0, p1, p2] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        assert_eq!(runner.state().phase, Phase::BeginCombat);
        assert_eq!(runner.state().active_player, p0);
        assert_eq!(runner.state().stack.len(), 1);
        assert_eq!(runner.state().stack[0].source_id, kitt);
        assert_eq!(runner.state().stack[0].controller, p1);
        let kitt_trigger = runner.state().stack[0].id;

        // CR 117.4: all players pass, so the trigger resolves; P1 accepts the
        // optional tap and taps two creatures (CR 608.2c).
        for player in [p0, p1, p2] {
            assert_eq!(runner.state().waiting_for, WaitingFor::Priority { player });
            runner.act(GameAction::PassPriority).unwrap();
        }
        assert!(matches!(
            runner.state().waiting_for,
            WaitingFor::OptionalEffectChoice { player, .. } if player == p1
        ));
        runner
            .act(GameAction::DecideOptionalEffect { accept: true })
            .unwrap();
        assert!(matches!(
            &runner.state().waiting_for,
            WaitingFor::PayCost { player, choices, count: 2, .. }
                if *player == p1 && tapped_for_kitt.iter().all(|id| choices.contains(id))
        ));
        runner
            .act(GameAction::SelectCards {
                cards: tapped_for_kitt.to_vec(),
            })
            .unwrap();
        assert!(tapped_for_kitt
            .iter()
            .all(|id| runner.state().objects[id].tapped));
        // Reach guard: the reflexive's target prompt opens while Kitt Kanto's
        // trigger is still the installed resolving carrier.
        assert!(matches!(
            &runner.state().waiting_for,
            WaitingFor::TriggerTargetSelection { player, .. } if *player == p1
        ));
        assert_eq!(
            runner
                .state()
                .resolving_stack_entry
                .as_ref()
                .map(|entry| entry.id),
            Some(kitt_trigger)
        );
        runner.act(choose_object_target(reflexive_target)).unwrap();

        // Reach guards for the lagging carrier. The reflexive is on the stack
        // and P1 holds this window: that is the construction seam's existing
        // recipient for the trigger's controller, which this test relies on
        // only to give P1 the window, not as the rules-derived recipient.
        // Kitt Kanto's trigger has finished resolving, yet its carrier is
        // still installed, and nobody has passed since.
        let state = runner.state();
        assert_eq!(state.waiting_for, WaitingFor::Priority { player: p1 });
        assert!(state.priority_passes.is_empty());
        assert_eq!(state.stack.len(), 1);
        assert_eq!(state.stack[0].source_id, kitt);
        assert_ne!(state.stack[0].id, kitt_trigger);
        assert_eq!(
            state.resolving_stack_entry.as_ref().map(|entry| entry.id),
            Some(kitt_trigger)
        );
        assert!(resolving_stack_entry_can_settle(state));

        // P1 casts Shock while holding priority, choosing its target as a
        // cast step.
        runner.state_mut().players[1].mana_pool.add(ManaUnit::new(
            ManaType::Red,
            ObjectId(0),
            false,
            vec![],
        ));
        let card_id = runner.state().objects[&shock].card_id;
        runner
            .act(GameAction::CastSpell {
                object_id: shock,
                card_id,
                targets: vec![],
                payment_mode: crate::types::game_state::CastPaymentMode::Auto,
            })
            .unwrap();
        assert!(matches!(
            runner.state().waiting_for,
            WaitingFor::TargetSelection { .. }
        ));
        runner.act(choose_object_target(shock_target)).unwrap();

        // Reach guards: Shock is paid for and on the stack above the
        // reflexive, and the finished carrier has settled during the cast.
        let state = runner.state();
        assert_eq!(state.players[1].mana_pool.total(), 0);
        assert_eq!(state.stack.len(), 2);
        assert_eq!(state.stack.last().map(|entry| entry.id), Some(shock));
        assert_eq!(state.objects[&shock].zone, Zone::Stack);
        assert!(state.resolving_stack_entry.is_none());
        // CR 117.3c: P1 had priority when casting Shock, so P1 receives
        // priority afterward; active P0 does not.
        assert_eq!(state.waiting_for, WaitingFor::Priority { player: p1 });
        assert_eq!(state.priority_player, p1);
        assert_eq!(state.phase, Phase::BeginCombat);
        assert_eq!(state.turn_number, turn);
        let mut accepted = state.clone();
        assert!(apply(&mut accepted, p1, GameAction::PassPriority).is_ok());
        for wrong in [p0, p2] {
            let mut rejected = state.clone();
            assert!(apply(&mut rejected, wrong, GameAction::PassPriority).is_err());
            assert_eq!(rejected.stack.len(), 2);
        }
    }

    /// CR 117.3b + CR 800.4j: the restore-boundary recovery of a bare
    /// permanent-spell rest (one `SpellResolution` frame over its finished
    /// `Spell` carrier, priority frozen on another seat) gives the recovered
    /// priority to the active player. Once the active player has left the game
    /// earlier in the turn, the next player in turn order still in the game
    /// receives it instead. The living-active row is the control.
    #[test]
    fn restore_recovery_of_a_spell_rest_skips_a_departed_active_player() {
        use crate::game::scenario::GameScenario;
        use crate::types::game_state::{CastingVariant, PendingSpellResolution};
        let (p0, p1, p2) = (PlayerId(0), PlayerId(1), PlayerId(2));
        for active_left in [false, true] {
            let mut scenario = GameScenario::new_n_player(3, 42);
            scenario.at_phase(Phase::PreCombatMain);
            let mut runner = scenario.build();
            let state = runner.state_mut();
            // Turn order runs P0 -> P1 -> P2, and it is P0's turn.
            assert_eq!(state.active_player, p0);
            assert_eq!(state.seat_order, [p0, p1, p2]);
            assert_eq!(
                state.turn_direction,
                crate::types::phase::TurnDirection::Normal
            );
            if active_left {
                // CR 800.4a: P0 leaves through the engine's elimination
                // authority; the turn continues without an active player.
                crate::game::elimination::eliminate_player(state, p0, &mut Vec::new());
                assert!(state.players[0].is_eliminated);
                assert!(state.game_end.is_none());
                assert_eq!(state.active_player, p0);
            }
            // The rest: P2's permanent spell has resolved onto the battlefield,
            // and only its completion frame and carrier remain.
            let spell = create_object(
                state,
                CardId(9_201),
                p2,
                "Resolved permanent".to_string(),
                Zone::Battlefield,
            );
            state.push_spell_resolution(PendingSpellResolution {
                object_id: spell,
                controller: p2,
                casting_variant: CastingVariant::Normal,
                cast_from_zone: None,
                cast_controller: None,
                cast_timing_permission: None,
                spell_targets: Vec::new(),
                actual_mana_spent: 0,
                kickers_paid: Vec::new(),
                additional_cost_payment_count: 0,
                additional_cost_payments: Vec::new(),
                convoked_creatures: Vec::new(),
            });
            state.resolving_stack_entry = Some(StackEntry {
                id: spell,
                source_id: spell,
                controller: p2,
                kind: StackEntryKind::Spell {
                    card_id: CardId(9_201),
                    ability: None,
                    casting_variant: CastingVariant::Normal,
                    actual_mana_spent: 0,
                },
            });
            state.waiting_for = WaitingFor::Priority { player: p2 };
            state.priority_player = p2;
            // Reach guard: the shape is the exact bare spell rest this
            // recovery retires.
            assert!(state.stack.is_empty());
            assert!(super::is_orphaned_spell_resolution_at_priority_boundary(
                state
            ));

            assert!(super::recover_terminal_resolution_rest_on_restore(state)
                .expect("the bare spell rest recovers"));
            assert!(state.resolving_stack_entry.is_none());
            assert!(state.resolution_stack.is_empty());
            let seat = if active_left { p1 } else { p0 };
            assert_eq!(
                state.waiting_for,
                WaitingFor::Priority { player: seat },
                "active player left: {active_left}"
            );
            assert_eq!(state.priority_player, seat);
            assert!(state.priority_passes.is_empty());
        }
    }
}

#[cfg(test)]
mod cost_move_drain_priority_boundary_tests {
    use super::{drain_pending_cost_move_resume, CostMoveDrainBoundary};
    use crate::types::ability::{AbilityCost, Effect, EffectKind, ResolvedAbility, TargetFilter};
    use crate::types::counter::CounterType;
    use crate::types::game_state::{
        GameState, PausedCounterCostRemoval, PendingCostMoveCompletion, PendingCostMoveResume,
        PendingCounterRemoval, PendingCounterRemovalInFlight, PendingCounterRemovalQueue,
        ReplacementSubtreeBoundary, WaitingFor,
    };
    use crate::types::identifiers::ObjectId;
    use crate::types::mana::ManaCost;
    use crate::types::player::PlayerId;

    /// `engine_payment_choices::resume_counter_addition_unless_payment` maps
    /// `CostMoveDrainBoundary::PriorityBoundary` to `unreachable!`, and nothing but
    /// this eligibility table makes that true: it admits only a Delve-commit `Cast`,
    /// `ManaAbilityPayment`, and a counter-cost root whose replacement subtree has
    /// retired at that boundary. Nothing else in the crate pinned that
    /// premise, so widening the table would leave the suite green and abort a live
    /// session instead.
    ///
    /// This pins the guard, not the panic. A `#[should_panic]` row would assert the
    /// panic is *reachable*, which is the inverse of the invariant. Admitting
    /// `CounterAdditionUnlessPayment` at `PriorityBoundary` turns this row red: the
    /// root takes the parked continuation and panics before it can return `Ok(None)`.
    #[test]
    fn a_parked_counter_addition_unless_payment_is_never_drained_at_the_priority_boundary() {
        let mut state = GameState::new_two_player(42);
        state.pending_cost_move_resume =
            Some(PendingCostMoveResume::CounterAdditionUnlessPayment {
                cost: AbilityCost::Mana {
                    cost: ManaCost::generic(2),
                },
                pending_effect: Box::new(ResolvedAbility::new(
                    Effect::TargetOnly {
                        target: TargetFilter::Any,
                    },
                    vec![],
                    ObjectId(60),
                    PlayerId(0),
                )),
                trigger_event: None,
                effect_description: None,
                remaining: Vec::new(),
            });
        let mut events = Vec::new();

        let drained = drain_pending_cost_move_resume(
            &mut state,
            &mut events,
            CostMoveDrainBoundary::PriorityBoundary,
        );

        assert!(
            matches!(drained, Ok(None)),
            "the priority boundary must not drain a counter-addition unless-payment"
        );
        assert!(
            matches!(
                state.pending_cost_move_resume,
                Some(PendingCostMoveResume::CounterAdditionUnlessPayment { .. })
            ),
            "the continuation must stay parked for the replacement boundary that owns it"
        );
        assert!(events.is_empty(), "an ineligible drain must emit no events");
    }

    /// CR 616.1 + CR 608.2c: a counter-cost root recorded at an empty stack is
    /// not resumable at any boundary while a frame its replacement installed
    /// (here an effect removal queue) is live, and is resumable at the priority
    /// boundary once that frame retires.
    #[test]
    fn a_counter_cost_root_waits_for_its_subtree_at_every_boundary() {
        let mut state = GameState::new_two_player(42);
        let removal = PendingCounterRemoval {
            object_id: ObjectId(61),
            counter_type: CounterType::Generic("charge".to_string()),
            count: 1,
        };
        state.pending_cost_move_resume = Some(PendingCostMoveResume::CounterCostRemovalPayment {
            player: PlayerId(0),
            pending: None,
            removal: Box::new(PausedCounterCostRemoval {
                in_flight: PendingCounterRemovalInFlight {
                    removal: removal.clone(),
                    counter_count_before: 1,
                },
                remaining: Vec::new(),
                replacement_subtree: ReplacementSubtreeBoundary::at(&state.resolution_stack),
            }),
            cost_paid_object: None,
            completion: PendingCostMoveCompletion::FinishPending,
        });
        state.push_counter_removals(PendingCounterRemovalQueue {
            remaining: vec![removal],
            effect_kind: EffectKind::RemoveCounter,
            source_ability_id: ObjectId(62),
            total: 1,
            applied_total: 0,
            in_flight: None,
        });

        for boundary in [
            CostMoveDrainBoundary::ReplacementDelivered {
                action_event_start: 0,
            },
            CostMoveDrainBoundary::ReplacementPrevented {
                action_event_start: 0,
            },
            CostMoveDrainBoundary::PriorityBoundary,
        ] {
            let mut events = Vec::new();
            let drained = drain_pending_cost_move_resume(&mut state, &mut events, boundary);
            assert!(
                matches!(drained, Ok(None)),
                "{boundary:?}: a live subtree keeps the root parked"
            );
            assert!(
                matches!(
                    state.pending_cost_move_resume,
                    Some(PendingCostMoveResume::CounterCostRemovalPayment { .. })
                ),
                "{boundary:?}: the root stays parked"
            );
            assert!(events.is_empty(), "{boundary:?}: no events while parked");
        }

        state
            .take_active_counter_removals()
            .expect("the queue is the top frame")
            .expect("the queue is present");
        let mut events = Vec::new();
        let drained = drain_pending_cost_move_resume(
            &mut state,
            &mut events,
            CostMoveDrainBoundary::PriorityBoundary,
        );
        assert!(
            matches!(drained, Ok(Some(WaitingFor::Priority { .. }))),
            "a retired subtree lets the priority boundary resume the root: {drained:?}"
        );
        assert!(
            state.pending_cost_move_resume.is_none(),
            "the resume took the root"
        );
    }
}

/// CR 111.1 vs CR 400.7: the mint / arrival split that `derived_fodder_class` publishes a class
/// from. `zones::move_to_zone` carries the existing `ObjectId`, so an ARRIVED object is keyed in
/// BOTH frames' `objects` while a MINTED one is keyed only in `after`'s — the single fact the
/// boundary mint's promise rests on, and the one an `after.battlefield − before.battlefield`
/// difference alone cannot see.
#[cfg(test)]
mod minted_battlefield_set_tests {
    use super::{derived_fodder_class, minted_battlefield_ids};
    use crate::game::game_object::GameObject;
    use crate::types::game_state::GameState;
    use crate::types::identifiers::{CardId, ObjectId};
    use crate::types::player::PlayerId;
    use crate::types::zones::Zone;

    fn put(state: &mut GameState, id: u64, name: &str, zone: Zone) -> ObjectId {
        let oid = ObjectId(id);
        state.objects.insert(
            oid,
            GameObject::new(oid, CardId(id), PlayerId(0), name.into(), zone),
        );
        if zone == Zone::Battlefield {
            state.battlefield.push_back(oid);
        }
        oid
    }

    /// Move `id` onto the battlefield with its `ObjectId` PRESERVED.
    fn arrive(state: &mut GameState, id: ObjectId) {
        state
            .objects
            .get_mut(&id)
            .expect("the arriving object is live")
            .zone = Zone::Battlefield;
        state.battlefield.push_back(id);
    }

    /// **The minted set is `after.battlefield` minus everything `before` KNEW, not minus
    /// everything `before` had on the battlefield.**
    ///
    /// The two halves move the same id onto the same battlefield and differ only in whether
    /// `before.objects` holds it, so the `!before.objects.contains_key` conjunct is the sole
    /// discriminator — a row that only added a battlefield id would pass with that conjunct
    /// deleted.
    #[test]
    fn minted_battlefield_ids_excludes_an_id_preserving_arrival() {
        let mut before = GameState::new_two_player(7);
        put(&mut before, 1, "Engine", Zone::Battlefield);
        let arrival = put(&mut before, 3, "Library Card", Zone::Library);

        let mut after = before.clone();
        put(&mut after, 2, "Saproling", Zone::Battlefield);
        arrive(&mut after, arrival);

        assert_eq!(
            minted_battlefield_ids(&before, &after),
            vec![ObjectId(2)],
            "only the id `before` never knew is MINTED"
        );

        // PAIRED CONTROL: the same id arriving on the same battlefield IS minted when `before`
        // does not know it. Same id, same zone, one field of the fixture flipped.
        let mut unknown_before = before.clone();
        unknown_before.objects.remove(&arrival);
        unknown_before
            .players
            .iter_mut()
            .for_each(|p| p.library.retain(|x| *x != arrival));
        let mut minted = minted_battlefield_ids(&unknown_before, &after);
        minted.sort();
        assert_eq!(
            minted,
            vec![ObjectId(2), ObjectId(3)],
            "the same arrival counts as MINTED once `before` no longer knows the id"
        );
    }

    /// CR 111.7 + CR 111.3: a token made in place of one that ceased to exist is not a mint; a
    /// second one, one of another name, one of another tapped status, and one with other
    /// copiable values each are.
    #[test]
    fn a_token_made_again_is_not_minted() {
        let mut before = GameState::new_two_player(7);
        put(&mut before, 1, "Engine", Zone::Battlefield);
        let spent = put(&mut before, 2, "Treasure", Zone::Battlefield);
        let mut ceased = before.clone();
        ceased.objects.remove(&spent);
        ceased.battlefield.retain(|id| *id != spent);
        let made = |name: &str| {
            let mut after = ceased.clone();
            let id = put(&mut after, 3, name, Zone::Battlefield);
            (after, id)
        };

        let (remade, twin) = made("Treasure");
        assert_eq!(minted_battlefield_ids(&before, &remade), vec![]);

        let mut two = remade.clone();
        let second = put(&mut two, 4, "Treasure", Zone::Battlefield);
        assert_eq!(minted_battlefield_ids(&before, &two), vec![second]);

        let (renamed, gold) = made("Gold");
        assert_eq!(minted_battlefield_ids(&before, &renamed), vec![gold]);

        let mut tapped = remade.clone();
        tapped
            .objects
            .get_mut(&twin)
            .expect("the made token is live")
            .tapped = true;
        assert_eq!(minted_battlefield_ids(&before, &tapped), vec![twin]);

        let mut keyworded = remade.clone();
        keyworded
            .objects
            .get_mut(&twin)
            .expect("the made token is live")
            .base_keywords
            .push(crate::types::keywords::Keyword::Flying);
        assert_eq!(minted_battlefield_ids(&before, &keyworded), vec![twin]);

        let mut moved = remade.clone();
        put(&mut moved, spent.0, "Treasure", Zone::Graveyard);
        assert_eq!(minted_battlefield_ids(&before, &moved), vec![twin]);
    }

    /// **`derived_fodder_class` reports `k` over the MINTED members only.**
    ///
    /// CR 732.2a: `PersistentAxisMaterialization::Tokens` reproduces `k` members per cycle by
    /// MINTING them, so counting an id-preserving arrival into `k` publishes a per-cycle delta the
    /// collapse cannot deliver. The arrival here is content-identical to the minted member, so an
    /// implementation counting battlefield-difference would find a homogeneous class of TWO and
    /// return `k == 2`.
    #[test]
    fn derived_fodder_class_counts_minted_members_and_not_arrivals() {
        let mut before = GameState::new_two_player(7);
        put(&mut before, 700, "Saproling", Zone::Battlefield);
        let arrival = put(&mut before, 900, "Saproling", Zone::Library);

        let mut after = before.clone();
        put(&mut after, 701, "Saproling", Zone::Battlefield);
        arrive(&mut after, arrival);

        let (class, k) = derived_fodder_class(&before, &after).expect("one minted class");
        assert_eq!(class.name, "Saproling");
        assert_eq!(
            k, 1,
            "the arrival is not a member of a class the mint reproduces"
        );

        // PAIRED CONTROL: mint the second member instead of moving it, and `k` rises to 2 — the
        // same content, the same battlefield, only the provenance changed.
        let mut minted_both = before.clone();
        minted_both.objects.remove(&arrival);
        minted_both
            .players
            .iter_mut()
            .for_each(|p| p.library.retain(|x| *x != arrival));
        let (_, k2) = derived_fodder_class(&minted_both, &after).expect("one minted class");
        assert_eq!(k2, 2, "two MINTED members of one class report k = 2");
    }
}

#[cfg(test)]
mod legacy_copy_announcement_tests {
    use super::*;
    use crate::game::scenario::{GameRunner, GameScenario, P0, P1};
    use crate::types::ability::TargetRef;
    use crate::types::mana::ManaCost;
    use crate::types::phase::Phase;

    const MIZZIXS_MASTERY: &str = "Exile target card that's an instant or sorcery from your graveyard. For each card exiled this way, copy it, and you may cast the copy without paying its mana cost. Exile Mizzix's Mastery.";
    const VOLCANIC_OFFERING: &str = "Destroy target nonbasic land you don't control and target nonbasic land of an opponent's choice you don't control.\nVolcanic Offering deals 7 damage to target creature you don't control and 7 damage to target creature of an opponent's choice you don't control.";
    const YOUNG_PYROMANCER: &str =
        "Whenever you cast an instant or sorcery spell, create a 1/1 red Elemental creature token.";

    fn elementals(r: &GameRunner) -> usize {
        r.state()
            .battlefield
            .iter()
            .filter(|id| {
                r.state().objects[id]
                    .card_types
                    .subtypes
                    .iter()
                    .any(|s| s == "Elemental")
            })
            .count()
    }

    /// CR 601.2e + CR 733.1 (restored legacy save): a copy announcement saved
    /// before casts were committed at announcement completion is already
    /// stamped as cast, with its cast observers parked. When the copy is
    /// abandoned (P2, who owns the only nonbasic land P0 announced, concedes
    /// mid-announcement), those observers are retracted: Young Pyromancer
    /// makes no token for it. Control: the same legacy state with the
    /// retraction disabled is checked by the revert leg.
    #[test]
    fn abandoning_a_legacy_committed_copy_retracts_its_parked_observers() {
        let p2 = crate::types::player::PlayerId(2);
        let mut s = GameScenario::new_n_player(3, 7);
        s.at_phase(Phase::PreCombatMain);
        s.add_creature_from_oracle(P0, "Young Pyromancer", 2, 1, YOUNG_PYROMANCER);
        let a = s.add_land_from_oracle(p2, "Nonbasic A", "").id();
        s.add_creature(P1, "P1 Creature A", 3, 12);
        s.add_creature(P1, "P1 Creature B", 3, 12);
        let offering = s
            .add_spell_to_graveyard(P0, "Volcanic Offering", true)
            .from_oracle_text(VOLCANIC_OFFERING)
            .id();
        let mastery = s
            .add_spell_to_hand(P0, "Mizzix's Mastery", false)
            .from_oracle_text(MIZZIXS_MASTERY)
            .with_mana_cost(ManaCost::zero())
            .id();
        let mut r = s.build();
        r.cast(mastery).target_object(offering).commit();
        for _ in 0..32 {
            if !matches!(r.state().waiting_for, WaitingFor::Priority { .. }) {
                break;
            }
            r.act(GameAction::PassPriority).expect("pass");
        }
        assert_eq!(elementals(&r), 1, "reach: Mastery's Elemental");
        r.act(GameAction::SelectCards {
            cards: vec![offering],
        })
        .expect("cast the copy");
        let WaitingFor::CopyRetarget { copy_id: copy, .. } = r.state().waiting_for else {
            panic!("expected the copy walk, got {:?}", r.state().waiting_for);
        };
        for electee in [p2, P1] {
            r.act(GameAction::ChooseAnnouncingOpponent { opponent: electee })
                .expect("elect");
        }
        r.act(GameAction::ChooseTarget {
            target: Some(TargetRef::Object(a)),
        })
        .expect("P0 announces A");
        // The legacy state: the copy was cast before its walk, so it is
        // stamped and its cast observers are parked.
        let mut cast_events = Vec::new();
        crate::game::casting_costs::commit_copy_cast(r.state_mut(), copy, P0, &mut cast_events)
            .expect("legacy commit");
        crate::game::triggers::collect_triggers_into_deferred(r.state_mut(), &cast_events);
        assert!(
            r.state().deferred_triggers.iter().any(|parked| parked
                .trigger_events
                .iter()
                .any(|event| matches!(event, GameEvent::SpellCast { object_id, .. } if *object_id == copy))),
            "reach: the legacy copy's Pyromancer trigger is parked"
        );
        r.act(GameAction::Concede { player_id: p2 })
            .expect("P2 concedes");
        assert!(
            !r.state().stack.iter().any(|entry| entry.id == copy),
            "the copy is gone"
        );
        for _ in 0..64 {
            if r.state().stack.is_empty() && r.state().deferred_triggers.is_empty() {
                break;
            }
            r.act(GameAction::PassPriority).expect("resolve");
        }
        assert_eq!(elementals(&r), 1, "no Elemental for the abandoned copy");
    }
}

#[cfg(test)]
mod loop_decision_record_tests {
    use super::*;
    use crate::game::scenario::{GameRunner, GameScenario, P0};
    use crate::types::game_state::{AutoMayChoice, LoopDecisionTally};

    const SHADRIX_SILVERQUILL: &str = "Flying, double strike\n\
At the beginning of combat on your turn, you may choose two. Each mode must target a different player.\n\
• Target player creates a 2/1 white and black Inkling creature token with flying.\n\
• Target player draws a card and loses 1 life.\n\
• Target player puts a +1/+1 counter on each creature they control.";

    fn shadrix() -> GameRunner {
        let mut scenario = GameScenario::new();
        scenario.at_phase(Phase::PreCombatMain);
        scenario.add_creature_from_oracle(P0, "Shadrix Silverquill", 2, 5, SHADRIX_SILVERQUILL);
        scenario.build()
    }

    /// Passes into combat and returns the key of Shadrix's prompted "may".
    fn prompted_may(runner: &mut GameRunner) -> crate::types::game_state::MayTriggerAutoChoiceKey {
        runner.pass_both_players();
        let WaitingFor::OptionalEffectChoice {
            may_trigger_key: Some(key),
            ..
        } = runner.state().waiting_for.clone()
        else {
            panic!(
                "reach: Shadrix's begin-combat trigger prompts, got {:?}",
                runner.state().waiting_for
            );
        };
        key
    }

    /// CR 104.4b + CR 603.5: a prompted answer is recorded at the action boundary; passing
    /// priority records nothing.
    #[test]
    fn a_prompted_answer_is_recorded_at_the_action_boundary() {
        let mut runner = shadrix();
        prompted_may(&mut runner);
        assert_eq!(
            runner.state().loop_decision_tally,
            LoopDecisionTally::default()
        );
        runner
            .act(GameAction::DecideOptionalEffect { accept: false })
            .expect("the may can be declined");
        assert_eq!(
            runner.state().loop_decision_tally,
            LoopDecisionTally {
                optional: 1,
                ..Default::default()
            }
        );
    }

    /// CR 603.5: a remembered decline is recorded where it answers the trigger as it resolves.
    #[test]
    fn a_remembered_decline_is_recorded_where_it_applies() {
        let key = prompted_may(&mut shadrix());
        let mut remembered = shadrix();
        remembered
            .state_mut()
            .set_may_trigger_auto_choice(key, AutoMayChoice::Decline);
        remembered.pass_both_players();
        assert!(
            !matches!(
                remembered.state().waiting_for,
                WaitingFor::OptionalEffectChoice { .. }
            ),
            "reach: the remembered decline opens no prompt"
        );
        assert_eq!(remembered.state().loop_decision_tally.optional, 1);
    }

    /// CR 603.5: a remembered answer to an optional modal trigger is recorded where it is
    /// applied.
    #[test]
    fn a_remembered_modal_may_answer_is_recorded_where_it_applies() {
        let key = prompted_may(&mut shadrix());
        let mut remembered = shadrix();
        remembered
            .state_mut()
            .set_may_trigger_auto_choice(key, AutoMayChoice::Accept);
        remembered.pass_both_players();
        assert!(
            matches!(
                remembered.state().waiting_for,
                WaitingFor::AbilityModeChoice { .. }
            ),
            "reach: the remembered accept skips to the modes, got {:?}",
            remembered.state().waiting_for
        );
        assert_eq!(remembered.state().loop_decision_tally.optional, 1);
    }
}
